func (n *Node) blockValidatorSetFromSignaturesWithFrozenLookups(
	block Block,
	frozenValidatorsForHeight func(uint64) []string,
	frozenValidatorSetHash func(uint64) (string, bool),
) ([]string, bool) {
	validators := canonicalValidatorIDs(append([]string{}, block.Signatures...))
	if len(validators) == 0 {
		return nil, false
	}
	hash := strings.TrimSpace(block.ValidatorSetHash)
	var stakeSnapshot map[string]ValidatorRecord
	if n != nil {
		stakeSnapshot = n.validatorRegistrySnapshotForHeight(block.ID)
	} else if !validatorSetCommitmentV2EnabledAt(block.ID) && !validatorSetHashV3EnabledAt(block.ID) {
		// Nil-node legacy helpers must not treat process-local mutable runtime
		// registry as consensus authority.
		stakeSnapshot = nil
	}

	hashMatchesCandidate := func(candidate []string, extraHashes ...string) bool {
		target := strings.TrimSpace(hash)
		if target == "" {
			return false
		}
		canonical := canonicalValidatorIDs(append([]string{}, candidate...))
		if len(canonical) == 0 {
			return false
		}
		for _, extra := range extraHashes {
			extra = strings.TrimSpace(extra)
			if extra != "" && strings.EqualFold(extra, target) {
				return true
			}
		}
		if len(stakeSnapshot) > 0 {
			computed := strings.TrimSpace(validatorSetHashFromSnapshotForHeight(block.ID, canonical, stakeSnapshot))
			if computed != "" && strings.EqualFold(computed, target) {
				return true
			}
		}
		if !validatorSetHashV3EnabledAt(block.ID) {
			computed := strings.TrimSpace(ValidatorSetHash(canonical))
			if computed != "" && strings.EqualFold(computed, target) {
				return true
			}
		}
		return false
	}

	// Finalized execution-result blocks can carry quorum signer subsets in
	// `Signatures`. Recover the full validator set from frozen deterministic
	// authority when it matches the committed validator_set_hash.
	if n != nil && len(block.ExecutionResults) > 0 && hash != "" {
		if frozenValidatorsForHeight == nil {
			frozenValidatorsForHeight = n.frozenValidatorsForHeight
		}
		if frozenValidatorSetHash == nil {
			frozenValidatorSetHash = n.frozenValidatorSetHash
		}
		seen := make(map[string]struct{}, 8)
		tryCandidate := func(values []string, extraHashes ...string) ([]string, bool) {
			canonical := canonicalValidatorIDs(append([]string{}, values...))
			if len(canonical) == 0 {
				return nil, false
			}
			key := strings.Join(canonical, "|")
			if _, ok := seen[key]; ok {
				return nil, false
			}
			seen[key] = struct{}{}
			if hashMatchesCandidate(canonical, extraHashes...) {
				return canonical, true
			}
			return nil, false
		}

		if frozen := frozenValidatorsForHeight(block.ID); len(frozen) > 0 {
			frozenHash, _ := frozenValidatorSetHash(block.ID)
			if matched, ok := tryCandidate(frozen, frozenHash); ok {
				return matched, true
			}
		}
		if block.ID > 1 {
			if frozenPrev := frozenValidatorsForHeight(block.ID - 1); len(frozenPrev) > 0 {
				frozenPrevHash, _ := frozenValidatorSetHash(block.ID - 1)
				if matched, ok := tryCandidate(frozenPrev, frozenPrevHash); ok {
					return matched, true
				}
			}
		}
		if frozenNext := frozenValidatorsForHeight(block.ID + 1); len(frozenNext) > 0 {
			frozenNextHash, _ := frozenValidatorSetHash(block.ID + 1)
			if matched, ok := tryCandidate(frozenNext, frozenNextHash); ok {
				return matched, true
			}
		}
		// Do not call currentValidatorSetSnapshot() here. That path resolves via
		// chainDerivedValidatorAuthorityForHeight(), which may call back into this
		// function for the same block and can recurse at startup.
		if len(n.GenesisValidators) > 0 {
			if matched, ok := tryCandidate(n.GenesisValidators); ok {
				return matched, true
			}
		}
	}

	expected := ""
	if len(stakeSnapshot) > 0 {
		expected = strings.TrimSpace(validatorSetHashFromSnapshotForHeight(block.ID, validators, stakeSnapshot))
	} else if !validatorSetHashV3EnabledAt(block.ID) {
		// Pre-v3 compatibility path: verify against canonical validator ID hash
		// derived from the committed block signatures only.
		expected = strings.TrimSpace(ValidatorSetHash(validators))
	}
	if strings.TrimSpace(expected) == "" {
		return nil, false
	}
	if validatorSetHashV3EnabledAt(block.ID) && strings.TrimSpace(expected) == "" && strings.TrimSpace(hash) != "" {
		return nil, false
	}
	if hash != "" && expected != "" && !strings.EqualFold(hash, expected) {
		return nil, false
	}
	return validators, true
}

func (n *Node) blockValidatorSetFromSignatures(block Block) ([]string, bool) {
	return n.blockValidatorSetFromSignaturesWithFrozenLookups(block, nil, nil)
}

func (n *Node) blockValidatorSetFromSignaturesLocked(block Block) ([]string, bool) {
	return n.blockValidatorSetFromSignaturesWithFrozenLookups(
		block,
		n.frozenValidatorsForHeightLocked,
		n.frozenValidatorSetHashLocked,
	)
}

func blockValidatorSetFromSignatures(block Block) ([]string, bool) {
	return (*Node)(nil).blockValidatorSetFromSignatures(block)
}

func (n *Node) validateBlockValidatorSetHashHeaderCommitment(block Block) error {
	if validatorSetCommitmentV2EnabledAt(block.ID) && strings.TrimSpace(block.ValidatorSetHash) == "" {
		return errors.New("missing_validator_set_hash")
	}
	// Finalized execution-result blocks may carry quorum signer subsets in
	// `Signatures`; strict set-hash commitment from signatures is enforced only
	// for proposal-style blocks that advertise the full active validator list.
	if len(block.Signatures) == 0 || len(block.ExecutionResults) > 0 {
		return nil
	}
	if strings.TrimSpace(block.ValidatorSetHash) == "" {
		return errors.New("missing_validator_set_hash")
	}
	if _, ok := n.blockValidatorSetFromSignatures(block); !ok {
		return errors.New("validator_set_hash_header_mismatch")
	}
	return nil
}

func validateBlockValidatorSetHashHeaderCommitment(block Block) error {
	return (*Node)(nil).validateBlockValidatorSetHashHeaderCommitment(block)
}

func (n *Node) chainParentCommittedValidatorSetHash(height uint64) (string, bool) {
	if n == nil || n.Blockchain == nil || height <= 1 {
		return "", false
	}
	parentHeight := height - 1
	if !validatorSetCommitmentV2EnabledAt(parentHeight) {
		return "", false
	}
	parent, ok := n.Blockchain.GetBlock(parentHeight)
	if !ok {
		parent, ok = n.LoadBlock(int(parentHeight))
	}
	if !ok {
		return "", false
	}
	hash := strings.TrimSpace(parent.NextValidatorSetHash)
	if hash == "" {
		return "", false
	}
	activationHeight := blockActivationHeight(parent)
	if activationHeight != 0 && activationHeight != height {
		return "", false
	}
	return hash, true
}

func snapshotValidatorRegistryHash(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return ""
	}
	if hash := strings.TrimSpace(snapshot.ValidatorRegistryHash); hash != "" {
		return hash
	}
	return ValidatorRegistrySnapshotHash(snapshot.ValidatorRegistry)
}

func snapshotPromotionWindowHash(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return ""
	}
	if hash := strings.TrimSpace(snapshot.PromotionWindowHash); hash != "" {
		return hash
	}
	return computedSnapshotPromotionWindowHash(snapshot)
}

func computedSnapshotPromotionWindowHash(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return ""
	}
	if !promotionWindowRecordV1EnabledAt(snapshot.Height) {
		return ""
	}
	window := validatorHybridPromotionWindowBucket(snapshot.Height)
	record, ok := snapshot.PromotionWindowRecords[window]
	if !ok {
		return ""
	}
	replacements := snapshot.PromotionWindowReplacements[window]
	return PromotionWindowStateHash(&record, replacements)
}

