func copyValidatorRegistrySnapshot(src map[string]ValidatorRecord) map[string]ValidatorRecord {
	if len(src) == 0 {
		return nil
	}
	out := make(map[string]ValidatorRecord, len(src))
	for id, rec := range src {
		norm := normalizeValidatorID(id)
		if norm == "" {
			norm = normalizeValidatorID(rec.ID)
		}
		if norm == "" {
			continue
		}
		recCopy := rec
		recCopy.ID = norm
		out[norm] = recCopy
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

type validatorRegistrySnapshotRecord struct {
	Height   uint64                     `json:"height"`
	Registry map[string]ValidatorRecord `json:"registry,omitempty"`
	Hash     string                     `json:"hash,omitempty"`
}

func validatorRegistrySnapshotCanonicalKey(height uint64) []byte {
	return []byte(fmt.Sprintf("validator_registry_snapshot:%d", height))
}

func validatorRegistrySnapshotLegacyKey(height uint64) []byte {
	return []byte(fmt.Sprintf("registry_snapshot:%d", height))
}

func validatorRegistrySnapshotKey(height uint64) []byte {
	return validatorRegistrySnapshotCanonicalKey(height)
}

func validatorRegistrySnapshotReadKeys(height uint64) [][]byte {
	return [][]byte{
		validatorRegistrySnapshotCanonicalKey(height),
		validatorRegistrySnapshotLegacyKey(height),
	}
}

func validatorRegistrySnapshotHeightKey() []byte {
	return []byte("validator_registry_snapshot_height")
}

func storeValidatorRegistrySnapshotHeight(meta *DB, height uint64) error {
	if meta == nil || height == 0 {
		return nil
	}
	var buf [8]byte
	binary.BigEndian.PutUint64(buf[:], height)
	return meta.Update(func(txn *Txn) error {
		return txn.Set(validatorRegistrySnapshotHeightKey(), buf[:])
	})
}

func (n *Node) loadLatestValidatorRegistrySnapshotHeight() (uint64, bool) {
	if n == nil || n.DB == nil || n.DB.Meta == nil {
		return 0, false
	}
	var height uint64
	err := n.DB.Meta.View(func(txn *Txn) error {
		item, err := txn.Get(validatorRegistrySnapshotHeightKey())
		if err != nil {
			return err
		}
		return item.Value(func(val []byte) error {
			if len(val) != 8 {
				return fmt.Errorf("invalid_validator_registry_snapshot_height")
			}
			height = binary.BigEndian.Uint64(val)
			return nil
		})
	})
	if err != nil || height == 0 {
		return 0, false
	}
	return height, true
}

func (n *Node) storeValidatorRegistrySnapshotRecord(height uint64, registry map[string]ValidatorRecord) error {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return nil
	}
	registry = copyValidatorRegistrySnapshot(registry)
	if len(registry) == 0 {
		return nil
	}
	snap := validatorRegistrySnapshotRecord{
		Height:   height,
		Registry: registry,
		Hash:     ValidatorRegistrySnapshotHash(registry),
	}
	data, err := json.Marshal(snap)
	if err != nil {
		return err
	}
	if err := n.DB.State.Update(func(txn *Txn) error {
		enc, err := encryptDBValue(data)
		if err != nil {
			return err
		}
		for _, key := range validatorRegistrySnapshotReadKeys(height) {
			if err := txn.Set(key, enc); err != nil {
				return err
			}
		}
		return nil
	}); err != nil {
		return err
	}
	if n.DB.Meta == nil {
		return errors.New("meta db not initialized")
	}
	return storeValidatorRegistrySnapshotHeight(n.DB.Meta, height)
}

func (n *Node) shouldSkipCatchupRegistrySnapshotWrite(height uint64, expectedHash string) (bool, uint64) {
	if n == nil || height <= 1 {
		return false, 0
	}
	expectedHash = strings.TrimSpace(expectedHash)
	if expectedHash == "" || !n.shouldDeferNonConsensusCommitMaintenance() {
		return false, 0
	}
	if _, sourceHeight, ok := n.committedValidatorRegistryCarryForwardCandidate(height, expectedHash); ok && sourceHeight > 0 && sourceHeight < height {
		return true, sourceHeight
	}
	return false, 0
}

func (n *Node) shouldPersistValidatorRegistryCarryForwardRepair(height, sourceHeight uint64, targetHash string) bool {
	if n == nil || sourceHeight == 0 || sourceHeight >= height {
		return true
	}
	skip, skipSource := n.shouldSkipCatchupRegistrySnapshotWrite(height, targetHash)
	return !(skip && skipSource == sourceHeight)
}

func (n *Node) storeValidatorRegistrySnapshot(height uint64) error {
	if n == nil || height == 0 {
		return nil
	}
	return n.persistValidatorRegistrySnapshotFromSource(height, GlobalValidatorRegistry.Snapshot())
}

func (n *Node) persistValidatorRegistrySnapshot(height uint64) {
	if n == nil || height == 0 {
		return
	}
	_ = n.persistValidatorRegistrySnapshotFromSource(height, GlobalValidatorRegistry.Snapshot())
}

func (n *Node) validatePersistableValidatorRegistrySource(height uint64, expectedHash string, sourceRegistry map[string]ValidatorRecord) error {
	expectedHash = strings.TrimSpace(expectedHash)
	if expectedHash == "" {
		return nil
	}
	registry := copyValidatorRegistrySnapshot(sourceRegistry)
	got := strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
	if got != "" && strings.EqualFold(got, expectedHash) {
		return nil
	}
	if carryForward, _, ok := n.findCommittedValidatorRegistrySnapshotByHashAtOrBelow(height, expectedHash); ok && len(carryForward) > 0 {
		return nil
	}
	if repaired, _, ok := n.repairGenesisCommittedValidatorRegistryByHash(expectedHash, registry); ok && len(repaired) > 0 {
		return nil
	}
	return errors.New("validator_registry_hash_mismatch")
}

func (n *Node) persistValidatorRegistrySnapshotFromSource(height uint64, sourceRegistry map[string]ValidatorRecord) error {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return nil
	}
	registry := copyValidatorRegistrySnapshot(sourceRegistry)
	if len(registry) == 0 {
		key := fmt.Sprintf("registry_persist_empty:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry persist snapshot skipped height=%d validators=0", height)
		}
		return nil
	}
	if n.Blockchain != nil {
		if block, ok := n.Blockchain.GetBlock(height); ok {
			expected := strings.TrimSpace(block.ValidatorRegistryHash)
			if expected != "" {
				got := strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
				if got == "" || !strings.EqualFold(got, expected) {
					if carryForward, sourceHeight, ok := n.findCommittedValidatorRegistrySnapshotByHashAtOrBelow(height, expected); ok && len(carryForward) > 0 {
						if err := n.storeValidatorRegistrySnapshotRecord(height, carryForward); err != nil {
							key := fmt.Sprintf("registry_persist_error:%d", height)
							if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
								log.Printf("[WARN] registry persist snapshot failed height=%d err=%v", height, err)
							}
							return err
						}
						key := fmt.Sprintf("registry_persist_carry_forward:%d", height)
						if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
							log.Printf("[REGISTRY-PERSIST] height=%d source=committed_carry_forward from=%d validators=%d hash=%s",
								height, sourceHeight, len(carryForward), ShortHash(expected))
						}
						return nil
					}
					if repaired, repairedHash, ok := n.repairGenesisCommittedValidatorRegistryByHash(expected, registry); ok && len(repaired) > 0 {
						if err := n.storeValidatorRegistrySnapshotRecord(height, repaired); err != nil {
							key := fmt.Sprintf("registry_persist_error:%d", height)
							if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
								log.Printf("[WARN] registry persist snapshot failed height=%d err=%v", height, err)
							}
							return err
						}
						key := fmt.Sprintf("registry_persist_genesis_repair:%d", height)
						if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
							log.Printf("[REGISTRY-PERSIST] height=%d source=genesis_bootstrap_repair validators=%d hash=%s",
								height, len(repaired), ShortHash(repairedHash))
						}
						return nil
					}
					key := fmt.Sprintf("registry_persist_mismatch:%d", height)
					if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
						log.Printf("[WARN] registry persist hash mismatch height=%d expected=%s got=%s", height, ShortHash(expected), ShortHash(got))
					}
					return errors.New("validator_registry_hash_mismatch")
				}
			}
		}
	}
	if err := n.storeValidatorRegistrySnapshotRecord(height, registry); err != nil {
		key := fmt.Sprintf("registry_persist_error:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry persist snapshot failed height=%d err=%v", height, err)
		}
		return err
	}
	return nil
}

func (n *Node) registrySnapshotExists(height uint64) bool {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return false
	}
	for _, key := range validatorRegistrySnapshotReadKeys(height) {
		err := n.DB.State.View(func(txn *Txn) error {
			_, err := txn.Get(key)
			return err
		})
		if err == nil {
			return true
		}
	}
	return false
}

func (n *Node) ensureRegistrySnapshot(height uint64, reason string) {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return
	}
	if n.registrySnapshotExists(height) {
		return
	}
	registry := GlobalValidatorRegistry.Snapshot()
	if len(registry) == 0 {
		key := fmt.Sprintf("registry_bootstrap_empty:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry bootstrap snapshot skipped height=%d reason=%s validators=0", height, strings.TrimSpace(reason))
		}
		return
	}
	if err := n.storeValidatorRegistrySnapshot(height); err != nil {
		key := fmt.Sprintf("registry_bootstrap_error:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry bootstrap snapshot failed height=%d reason=%s err=%v", height, strings.TrimSpace(reason), err)
		}
		return
	}
	key := fmt.Sprintf("registry_bootstrap_created:%d", height)
	if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
		log.Printf("[REGISTRY] bootstrap snapshot created height=%d validators=%d reason=%s", height, len(registry), strings.TrimSpace(reason))
	}
}

func (n *Node) ensureGenesisCommittedValidatorRegistrySnapshot(reason string) {
	if n == nil || n.DB == nil || n.DB.State == nil {
		return
	}
	const genesisCommitHeight uint64 = 1
	if existing, err := n.loadValidatorRegistrySnapshot(genesisCommitHeight); err == nil && len(existing) > 0 {
		return
	}
	registry, hash, ok := n.genesisCommittedValidatorRegistryCandidate(GlobalValidatorRegistry.Snapshot())
	if !ok || len(registry) == 0 || strings.TrimSpace(hash) == "" {
		key := "genesis_registry_snapshot_unavailable:" + strings.TrimSpace(reason)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] genesis registry snapshot skipped reason=%s validators=%d", strings.TrimSpace(reason), len(n.GenesisValidators))
		}
		return
	}
	if n.Blockchain != nil {
		if block, ok := n.Blockchain.GetBlock(genesisCommitHeight); ok {
			expected := strings.TrimSpace(block.ValidatorRegistryHash)
			if expected != "" && !strings.EqualFold(expected, hash) {
				key := "genesis_registry_snapshot_mismatch:" + strings.TrimSpace(reason)
				if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
					log.Printf("[WARN] genesis registry snapshot mismatch reason=%s expected=%s got=%s", strings.TrimSpace(reason), ShortHash(expected), ShortHash(hash))
				}
				return
			}
		}
	}
	if err := n.storeValidatorRegistrySnapshotRecord(genesisCommitHeight, registry); err != nil {
		key := "genesis_registry_snapshot_error:" + strings.TrimSpace(reason)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] genesis registry snapshot failed reason=%s err=%v", strings.TrimSpace(reason), err)
		}
		return
	}
	key := "genesis_registry_snapshot_created:" + strings.TrimSpace(reason)
	if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
		log.Printf("[REGISTRY] genesis committed snapshot created height=%d validators=%d hash=%s reason=%s",
			genesisCommitHeight,
			len(registry),
			ShortHash(hash),
			strings.TrimSpace(reason),
		)
	}
}

func (n *Node) loadValidatorRegistrySnapshot(height uint64) (map[string]ValidatorRecord, error) {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return nil, errors.New("registry_snapshot_unavailable")
	}
	var snap validatorRegistrySnapshotRecord
	var loadErr error = ErrKeyNotFound
	for _, key := range validatorRegistrySnapshotReadKeys(height) {
		loadErr = n.DB.State.View(func(txn *Txn) error {
			item, err := txn.Get(key)
			if err != nil {
				return err
			}
			return item.Value(func(val []byte) error {
				dec, err := decryptDBValue(val)
				if err != nil {
					return err
				}
				return json.Unmarshal(dec, &snap)
			})
		})
		if loadErr == nil {
			break
		}
		if !errors.Is(loadErr, ErrKeyNotFound) {
			return nil, loadErr
		}
	}
	if loadErr != nil {
		return nil, loadErr
	}
	if snap.Height != 0 && snap.Height != height {
		return nil, fmt.Errorf("registry_snapshot_height_mismatch got=%d want=%d", snap.Height, height)
	}
	if len(snap.Registry) == 0 {
		return nil, errors.New("registry_snapshot_empty")
	}
	if snap.Hash != "" {
		if got := ValidatorRegistrySnapshotHash(snap.Registry); !strings.EqualFold(strings.TrimSpace(got), strings.TrimSpace(snap.Hash)) {
			return nil, errors.New("registry_snapshot_hash_mismatch")
		}
	}
	return copyValidatorRegistrySnapshot(snap.Registry), nil
}

func (n *Node) findCommittedValidatorRegistrySnapshotByHashAtOrBelow(height uint64, targetHash string) (map[string]ValidatorRecord, uint64, bool) {
	if n == nil || n.DB == nil || n.DB.State == nil || height <= 1 {
		return nil, 0, false
	}
	targetHash = strings.TrimSpace(targetHash)
	if targetHash == "" {
		return nil, 0, false
	}
	start := height - 1
	if latest, ok := n.loadLatestValidatorRegistrySnapshotHeight(); ok && latest > 0 && latest < start {
		start = latest
	}
	for h := start; h >= 1; h-- {
		snap, err := n.loadValidatorRegistrySnapshot(h)
		if err == nil && len(snap) > 0 {
			hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(snap))
			if hash != "" && strings.EqualFold(hash, targetHash) {
				return snap, h, true
			}
		}
		if h == 1 {
			break
		}
	}
	return nil, 0, false
}

func (n *Node) committedValidatorRegistryCarryForwardCandidate(height uint64, targetHash string) (map[string]ValidatorRecord, uint64, bool) {
	if n == nil || n.DB == nil || n.DB.State == nil || height <= 1 {
		return nil, 0, false
	}
	targetHash = strings.TrimSpace(targetHash)
	if targetHash == "" {
		return nil, 0, false
	}
	candidates := []uint64{height - 1}
	if latest, ok := n.loadLatestValidatorRegistrySnapshotHeight(); ok && latest > 0 && latest < height && latest != height-1 {
		candidates = append(candidates, latest)
	}
	for _, candidateHeight := range candidates {
		snap, err := n.loadValidatorRegistrySnapshot(candidateHeight)
		if err != nil || len(snap) == 0 {
			continue
		}
		hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(snap))
		if hash != "" && strings.EqualFold(hash, targetHash) {
			return snap, candidateHeight, true
		}
	}
	return nil, 0, false
}

func (n *Node) genesisCommittedValidatorRegistryCandidate(sourceRegistry map[string]ValidatorRecord) (map[string]ValidatorRecord, string, bool) {
	if n == nil {
		return nil, "", false
	}
	ids := canonicalValidatorIDs(append([]string{}, n.GenesisValidators...))
	if len(ids) == 0 {
		return nil, "", false
	}
	sourceRegistry = copyValidatorRegistrySnapshot(sourceRegistry)
	out := make(map[string]ValidatorRecord, len(ids))
	for _, id := range ids {
		if id == "" {
			continue
		}
		rec := sourceRegistry[id]
		rec.ID = id
		rec.ConsensusPubKey = consensusPubKeyHexForValidatorID(id)
		rec.GovernanceSigner = validatorRecordBootstrapGovernanceSeed(id)
		rec.Stake = ValidatorMinStake
		rec.Status = ValidatorActive
		rec.JailUntilHeight = 0
		rec.JoinHeight = 0
		rec.TotalSlashes = 0
		rec.InactivityPenalties = 0
		if rec.ActiveHeights == nil {
			rec.ActiveHeights = make([]uint64, 0)
		}
		if rec.SignedHeights == nil {
			rec.SignedHeights = make([]uint64, 0)
		}
		out[id] = rec
	}
	if len(out) == 0 {
		return nil, "", false
	}
	hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(out))
	if hash == "" {
		return nil, "", false
	}
	return out, hash, true
}

func (n *Node) repairGenesisCommittedValidatorRegistryByHash(targetHash string, sourceRegistry map[string]ValidatorRecord) (map[string]ValidatorRecord, string, bool) {
	targetHash = strings.TrimSpace(targetHash)
	if targetHash == "" {
		return nil, "", false
	}
	candidate, hash, ok := n.genesisCommittedValidatorRegistryCandidate(sourceRegistry)
	if !ok || hash == "" || !strings.EqualFold(hash, targetHash) {
		return nil, "", false
	}
	return candidate, hash, true
}

func (n *Node) repairCommittedValidatorRegistrySnapshotFromCommittedSnapshot(height uint64, targetHash string) (map[string]ValidatorRecord, string, bool) {
	if n == nil || height == 0 {
		return nil, "", false
	}
	targetHash = strings.TrimSpace(targetHash)
	if targetHash == "" {
		return nil, "", false
	}
	snapshot, _, ok := n.resolveCommittedStateSnapshotFromStorage(height)
	if !ok || snapshot == nil || len(snapshot.ValidatorRegistry) == 0 {
		return nil, "", false
	}
	registry := copyValidatorRegistrySnapshot(snapshot.ValidatorRegistry)
	hash := strings.TrimSpace(snapshotValidatorRegistryHash(snapshot))
	if hash == "" {
		hash = strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
	}
	if hash == "" || !strings.EqualFold(hash, targetHash) {
		return nil, "", false
	}
	if err := n.storeValidatorRegistrySnapshotRecord(height, registry); err != nil {
		key := fmt.Sprintf("registry_snapshot_repair_store:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry repair store failed height=%d err=%v", height, err)
		}
		return nil, "", false
	}
	return registry, hash, true
}

func (n *Node) committedParentProjectionSnapshot(height uint64) (*StateSnapshot, string, bool) {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil {
		return nil, "none", false
	}
	parentHeight := height - 1
	if parentHeight == 0 {
		return nil, "none", false
	}
	if snap, err := n.GetSnapshot(parentHeight); err == nil && snap != nil {
		return snap, "snapshot_parent", true
	}
	if parentHeight <= 1 {
		return nil, "none", false
	}
	snap, err := n.GetSnapshotAtOrBelow(parentHeight)
	if err != nil || snap == nil {
		return nil, "none", false
	}
	// Allow a one-block-behind committed projection while the parent snapshot is
	// still materializing. This is the deterministic pre-apply path when
	// validating block h against committed snapshot h-1.
	if snap.Height+1 != parentHeight {
		return nil, "none", false
	}
	return snap, "snapshot_parent_projection", true
}

func (n *Node) resolveCommittedValidatorRegistrySnapshot(height uint64) (map[string]ValidatorRecord, string, string, bool) {
	if n == nil || height == 0 {
		return nil, "", "none", false
	}
	if registry, hash, ok := n.sparseCommittedAnchorParentRegistrySnapshot(height); ok && len(registry) > 0 {
		return registry, hash, "sparse_anchor_parent_projection", true
	}
	if snap, err := n.loadValidatorRegistrySnapshot(height); err == nil && len(snap) > 0 {
		hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(snap))
		return snap, hash, "registry_snapshot", true
	}
	if n.Blockchain == nil {
		return nil, "", "none", false
	}
	chainTip := n.Blockchain.Height()
	if chainTip == 0 {
		return nil, "", "none", false
	}
	if height > chainTip {
		if DebugConsensus {
			key := fmt.Sprintf("registry_pending_future:%d", height)
			if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
				log.Printf("[REGISTRY-PENDING] height=%d chain_tip=%d reason=future_block", height, chainTip)
			}
		}
		return nil, "", "pending_future_block", false
	}
	block, ok := n.Blockchain.GetBlock(height)
	if !ok {
		block, ok = n.LoadBlock(int(height))
	}
	if !ok {
		key := fmt.Sprintf("registry_missing_block:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-MISSING] height=%d reason=block_unavailable", height)
		}
		return nil, "", "none", false
	}
	targetHash := strings.TrimSpace(block.ValidatorRegistryHash)
	if targetHash == "" {
		key := fmt.Sprintf("registry_missing_hash:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-MISSING] height=%d reason=empty_commitment", height)
		}
		return nil, "", "none", false
	}
	if registry, sourceHeight, ok := n.committedValidatorRegistryCarryForwardCandidate(height, targetHash); ok && len(registry) > 0 {
		persistRepair := n.shouldPersistValidatorRegistryCarryForwardRepair(height, sourceHeight, targetHash)
		if persistRepair {
			if err := n.storeValidatorRegistrySnapshotRecord(height, registry); err != nil {
				key := fmt.Sprintf("registry_snapshot_repair_store:%d", height)
				if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
					log.Printf("[WARN] registry repair store failed height=%d err=%v", height, err)
				}
			}
		}
		key := fmt.Sprintf("registry_repair_success:%d", height)
		if !persistRepair {
			key = "registry_repair_success:committed_carry_forward_fast_skip_store"
		}
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			if persistRepair {
				log.Printf("[REGISTRY-REPAIR] height=%d source=committed_carry_forward_fast from=%d validators=%d",
					height,
					sourceHeight,
					len(registry),
				)
			} else {
				log.Printf("[REGISTRY-REPAIR] height=%d source=committed_carry_forward_fast_skip_store from=%d validators=%d",
					height,
					sourceHeight,
					len(registry),
				)
			}
		}
		return registry, targetHash, "committed_carry_forward_repair", true
	}
	if registry, hash, ok := n.repairCommittedValidatorRegistrySnapshotFromCommittedSnapshot(height, targetHash); ok && len(registry) > 0 {
		key := fmt.Sprintf("registry_repair_success:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-REPAIR] height=%d source=committed_snapshot_repair validators=%d", height, len(registry))
		}
		return registry, hash, "committed_snapshot_repair", true
	}
	if chainTip == height {
		if record, err := n.loadTipSnapshotRegistry(); err == nil && record != nil && record.Height == height && len(record.Registry) > 0 {
			registry := copyValidatorRegistrySnapshot(record.Registry)
			hash := strings.TrimSpace(record.ValidatorRegistryHash)
			if hash == "" {
				hash = strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
			}
			if hash != "" && strings.EqualFold(hash, targetHash) {
				if err := n.storeValidatorRegistrySnapshotRecord(height, registry); err != nil {
					key := fmt.Sprintf("registry_snapshot_repair_store:%d", height)
					if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
						log.Printf("[WARN] registry repair store failed height=%d err=%v", height, err)
					}
				}
				key := fmt.Sprintf("registry_repair_success:%d", height)
				if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
					log.Printf("[REGISTRY-REPAIR] height=%d source=tip_snapshot_repair validators=%d", height, len(registry))
				}
				return registry, targetHash, "tip_snapshot_repair", true
			}
		}
		if record, err := n.loadTipSnapshotState(); err == nil && record != nil && record.Height == height && record.Snapshot != nil && len(record.Snapshot.ValidatorRegistry) > 0 {
			registry := copyValidatorRegistrySnapshot(record.Snapshot.ValidatorRegistry)
			hash := strings.TrimSpace(snapshotValidatorRegistryHash(record.Snapshot))
			if hash == "" {
				hash = strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
			}
			if hash != "" && strings.EqualFold(hash, targetHash) {
				if err := n.storeValidatorRegistrySnapshotRecord(height, registry); err != nil {
					key := fmt.Sprintf("registry_snapshot_repair_store:%d", height)
					if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
						log.Printf("[WARN] registry repair store failed height=%d err=%v", height, err)
					}
				}
				key := fmt.Sprintf("registry_repair_success:%d", height)
				if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
					log.Printf("[REGISTRY-REPAIR] height=%d source=tip_snapshot_repair validators=%d", height, len(registry))
				}
				return registry, targetHash, "tip_snapshot_repair", true
			}
		}
	}
	if registry, sourceHeight, ok := n.findCommittedValidatorRegistrySnapshotByHashAtOrBelow(height, targetHash); ok && len(registry) > 0 {
		persistRepair := n.shouldPersistValidatorRegistryCarryForwardRepair(height, sourceHeight, targetHash)
		if persistRepair {
			if err := n.storeValidatorRegistrySnapshotRecord(height, registry); err != nil {
				key := fmt.Sprintf("registry_snapshot_repair_store:%d", height)
				if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
					log.Printf("[WARN] registry repair store failed height=%d err=%v", height, err)
				}
			}
		}
		key := fmt.Sprintf("registry_repair_success:%d", height)
		if !persistRepair {
			key = "registry_repair_success:committed_carry_forward_skip_store"
		}
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			if persistRepair {
				log.Printf("[REGISTRY-REPAIR] height=%d source=committed_carry_forward from=%d validators=%d",
					height,
					sourceHeight,
					len(registry),
				)
			} else {
				log.Printf("[REGISTRY-REPAIR] height=%d source=committed_carry_forward_skip_store from=%d validators=%d",
					height,
					sourceHeight,
					len(registry),
				)
			}
		}
		return registry, targetHash, "committed_carry_forward_repair", true
	}
	if chainTip != height {
		key := fmt.Sprintf("registry_missing_historical:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-MISSING] height=%d chain_tip=%d", height, chainTip)
		}
		return nil, "", "none", false
	}
	runtimeRegistry := copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
	if repaired, repairedHash, ok := n.repairGenesisCommittedValidatorRegistryByHash(targetHash, runtimeRegistry); ok && len(repaired) > 0 {
		if err := n.storeValidatorRegistrySnapshotRecord(height, repaired); err != nil {
			key := fmt.Sprintf("registry_snapshot_repair_store:%d", height)
			if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
				log.Printf("[WARN] registry repair store failed height=%d err=%v", height, err)
			}
		}
		key := fmt.Sprintf("registry_repair_success:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-REPAIR] height=%d source=genesis_bootstrap_repair validators=%d", height, len(repaired))
		}
		return repaired, repairedHash, "genesis_bootstrap_repair", true
	}
	if len(runtimeRegistry) == 0 {
		key := fmt.Sprintf("registry_repair_failed:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-REPAIR FAILED] height=%d reason=runtime_empty", height)
		}
		return nil, "", "none", false
	}
	hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(runtimeRegistry))
	if hash == "" || !strings.EqualFold(hash, targetHash) {
		key := fmt.Sprintf("registry_repair_failed:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-REPAIR FAILED] height=%d reason=hash_mismatch expected=%s got=%s", height, ShortHash(targetHash), ShortHash(hash))
		}
		return nil, "", "none", false
	}
	if err := n.storeValidatorRegistrySnapshotRecord(height, runtimeRegistry); err != nil {
		key := fmt.Sprintf("registry_snapshot_repair_store:%d", height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry repair store failed height=%d err=%v", height, err)
		}
	}
	key := fmt.Sprintf("registry_repair_success:%d", height)
	if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
		log.Printf("[REGISTRY-REPAIR] height=%d source=live_tip_runtime_repair validators=%d", height, len(runtimeRegistry))
	}
	return runtimeRegistry, targetHash, "live_tip_runtime_repair", true
}

func (n *Node) sparseCommittedAnchorRegistrySnapshot(height uint64) map[string]ValidatorRecord {
	if n == nil || height <= 1 || n.Blockchain == nil || n.Blockchain.Height() != height {
		return nil
	}
	if _, ok := n.Blockchain.GetBlock(height - 1); ok {
		return nil
	}
	if _, ok := n.loadDurableBlock(height - 1); ok {
		return nil
	}
	anchor, ok := n.Blockchain.GetBlock(height)
	if !ok {
		return nil
	}
	expectedHash := strings.TrimSpace(anchor.ValidatorRegistryHash)
	if expectedHash == "" {
		return nil
	}
	if registry, err := n.loadValidatorRegistrySnapshot(height); err == nil && len(registry) > 0 {
		if hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(registry)); hash != "" && strings.EqualFold(hash, expectedHash) {
			return registry
		}
	}
	if snapshot, _, ok := n.resolveCommittedStateSnapshotFromStorage(height); ok && snapshot != nil && len(snapshot.ValidatorRegistry) > 0 {
		registry := copyValidatorRegistrySnapshot(snapshot.ValidatorRegistry)
		hash := strings.TrimSpace(snapshotValidatorRegistryHash(snapshot))
		if hash == "" {
			hash = strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
		}
		if hash != "" && strings.EqualFold(hash, expectedHash) {
			return registry
		}
	}
	if registry, _, ok := n.appliedRuntimeRegistryForAnchor(height, expectedHash, "sparse_anchor_registry"); ok {
		return registry
	}
	return nil
}

func (n *Node) sparseCommittedAnchorParentRegistrySnapshot(parentHeight uint64) (map[string]ValidatorRecord, string, bool) {
	if n == nil || parentHeight == 0 || n.Blockchain == nil {
		return nil, "", false
	}
	anchorHeight := parentHeight + 1
	if chainHeight := n.Blockchain.Height(); chainHeight > 0 && anchorHeight > chainHeight {
		return nil, "", false
	}
	if _, ok := n.Blockchain.GetBlock(parentHeight); ok {
		return nil, "", false
	}
	if _, ok := n.LoadBlock(int(parentHeight)); ok {
		return nil, "", false
	}
	anchor, ok := n.Blockchain.GetBlock(anchorHeight)
	if !ok {
		anchor, ok = n.loadDurableBlock(anchorHeight)
	}
	if !ok {
		return nil, "", false
	}
	expectedHash := strings.TrimSpace(anchor.ValidatorRegistryHash)
	if expectedHash == "" {
		return nil, "", false
	}
	if registry, err := n.loadValidatorRegistrySnapshot(anchorHeight); err == nil && len(registry) > 0 {
		if hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(registry)); hash != "" && strings.EqualFold(hash, expectedHash) {
			return registry, expectedHash, true
		}
	}
	if snapshot, _, ok := n.resolveCommittedStateSnapshotFromStorage(anchorHeight); ok && snapshot != nil && len(snapshot.ValidatorRegistry) > 0 {
		registry := copyValidatorRegistrySnapshot(snapshot.ValidatorRegistry)
		hash := strings.TrimSpace(snapshotValidatorRegistryHash(snapshot))
		if hash == "" {
			hash = strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
		}
		if hash != "" && strings.EqualFold(hash, expectedHash) {
			return registry, expectedHash, true
		}
	}
	if registry, hash, ok := n.appliedRuntimeRegistryForAnchor(anchorHeight, expectedHash, "sparse_anchor_parent_projection"); ok {
		return registry, hash, true
	}
	return nil, "", false
}

func (n *Node) appliedRuntimeRegistryForAnchor(anchorHeight uint64, expectedHash string, reason string) (map[string]ValidatorRecord, string, bool) {
	if n == nil || anchorHeight == 0 {
		return nil, "", false
	}
	expectedHash = strings.TrimSpace(expectedHash)
	if expectedHash == "" {
		return nil, "", false
	}
	registry := copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
	if len(registry) == 0 {
		return nil, "", false
	}
	hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
	if hash == "" || !strings.EqualFold(hash, expectedHash) {
		return nil, "", false
	}
	if err := n.storeValidatorRegistrySnapshotRecord(anchorHeight, registry); err != nil {
		key := fmt.Sprintf("registry_anchor_runtime_store:%d", anchorHeight)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry anchor runtime repair store failed height=%d reason=%s err=%v",
				anchorHeight,
				strings.TrimSpace(reason),
				err,
			)
		}
	} else {
		key := fmt.Sprintf("registry_anchor_runtime_store_ok:%d", anchorHeight)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-REPAIR] height=%d source=applied_runtime_anchor reason=%s validators=%d",
				anchorHeight,
				strings.TrimSpace(reason),
				len(registry),
			)
		}
	}
	return registry, expectedHash, true
}

func (n *Node) persistAppliedSnapshotRegistryAnchor(snapshot StateSnapshot, reason string) bool {
	if n == nil || snapshot.Height == 0 {
		return false
	}
	anchor := snapshotAnchorBlock(snapshot)
	expectedHash := strings.TrimSpace(anchor.ValidatorRegistryHash)
	if expectedHash == "" {
		expectedHash = strings.TrimSpace(snapshotValidatorRegistryHash(&snapshot))
	}
	if expectedHash == "" {
		return false
	}
	registry := copyValidatorRegistrySnapshot(snapshot.ValidatorRegistry)
	if len(registry) == 0 && len(snapshot.StateValidators) > 0 {
		registry = validatorRegistrySnapshotFromOnChainValidators(snapshot.StateValidators)
	}
	if len(registry) == 0 {
		registry = copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
	}
	if len(registry) == 0 {
		return false
	}
	hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(registry))
	if hash == "" || !strings.EqualFold(hash, expectedHash) {
		key := fmt.Sprintf("registry_snapshot_anchor_mismatch:%d", snapshot.Height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[REGISTRY-REPAIR FAILED] height=%d reason=snapshot_anchor_hash_mismatch expected=%s got=%s source=%s",
				snapshot.Height,
				ShortHash(expectedHash),
				ShortHash(hash),
				strings.TrimSpace(reason),
			)
		}
		return false
	}
	if err := n.storeValidatorRegistrySnapshotRecord(snapshot.Height, registry); err != nil {
		key := fmt.Sprintf("registry_snapshot_anchor_store:%d", snapshot.Height)
		if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
			log.Printf("[WARN] registry snapshot anchor store failed height=%d source=%s err=%v",
				snapshot.Height,
				strings.TrimSpace(reason),
				err,
			)
		}
		return false
	}
	key := fmt.Sprintf("registry_snapshot_anchor_store_ok:%d", snapshot.Height)
	if n.shouldLogLivenessReason(key, livenessReasonLogCooldown) {
		log.Printf("[REGISTRY-REPAIR] height=%d source=snapshot_anchor_registry reason=%s validators=%d",
			snapshot.Height,
			strings.TrimSpace(reason),
			len(registry),
		)
	}
	return true
}

func (n *Node) validatorRegistrySnapshotForHeight(height uint64) map[string]ValidatorRecord {
	if n == nil {
		return nil
	}
	if height == 0 {
		if n.Blockchain != nil && n.Blockchain.Height() > 0 {
			return nil
		}
		return copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
	}
	parentHeight := uint64(0)
	if height > 0 {
		parentHeight = height - 1
	}
	chainHeight := uint64(0)
	if n.Blockchain != nil {
		chainHeight = n.Blockchain.Height()
	}
	// A verified sparse snapshot anchor is the only committed authority available
	// when its historical parent block was intentionally not retained. Resolve it
	// before consulting unprovable parent-height registry records or scheduling
	// an expensive historical rebuild.
	if registry := n.sparseCommittedAnchorRegistrySnapshot(height); len(registry) > 0 {
		return registry
	}
	parentAheadOfChain := chainHeight > 0 && parentHeight > chainHeight
	const historicalRegistryRepairWindow uint64 = 128
	deferHistoricalRegistryRepair := false
	if parentHeight > 1 && chainHeight > parentHeight && chainHeight-parentHeight > historicalRegistryRepairWindow {
		deferHistoricalRegistryRepair = true
	}
	if parentHeight > 0 && !parentAheadOfChain && n.DB != nil && n.DB.State != nil {
		if deferHistoricalRegistryRepair {
			// Startup/replay paths can touch every historical height. Existing
			// committed registry snapshots remain authoritative and cheap to read,
			// but missing old snapshots should not trigger expensive repair.
			if snap, err := n.loadValidatorRegistrySnapshot(parentHeight); err == nil && len(snap) > 0 {
				return snap
			}
			return nil
		}
		if snap, _, _, ok := n.resolveCommittedValidatorRegistrySnapshot(parentHeight); ok && len(snap) > 0 {
			return snap
		}
		if n.ensureDeterministicRegistryHistoryUpTo(parentHeight) {
			if snap, _, _, ok := n.resolveCommittedValidatorRegistrySnapshot(parentHeight); ok && len(snap) > 0 {
				return snap
			}
		}
		if height == chainHeight {
			if snap, _, ok := n.resolveCommittedStateSnapshotFromStorage(height); ok && snap != nil && len(snap.ValidatorRegistry) > 0 {
				return copyValidatorRegistrySnapshot(snap.ValidatorRegistry)
			}
		}
		if snap, _, ok := n.committedParentProjectionSnapshot(height); ok && snap != nil && len(snap.ValidatorRegistry) > 0 {
			return copyValidatorRegistrySnapshot(snap.ValidatorRegistry)
		}
	}
	if chainHeight == 0 {
		if boot, _, ok := n.genesisCommittedValidatorRegistryCandidate(GlobalValidatorRegistry.Snapshot()); ok && len(boot) > 0 {
			return boot
		}
		return copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
	}
	if chainHeight > 0 {
		historyPruned := parentHeight > 0 && n.stateHistoryPrunedForHeight(parentHeight)
		if parentHeight > 0 && DebugConsensus {
			latestPersisted, hasLatestPersisted := n.loadLatestValidatorRegistrySnapshotHeight()
			if parentHeight > chainHeight {
				if n.shouldLogLivenessReason(fmt.Sprintf("registry_snapshot_pending:%d", parentHeight), livenessReasonLogCooldown) {
					fmt.Printf("[REGISTRY-PENDING] height=%d chain_height=%d reason=future_parent\n",
						parentHeight, chainHeight)
				}
			} else if historyPruned {
				if n.shouldLogLivenessReason(fmt.Sprintf("registry_snapshot_pruned:%d", parentHeight/1024), livenessReasonLogCooldown) {
					fmt.Printf("[REGISTRY-PRUNED] height=%d chain_height=%d reason=state_history_compacted\n",
						parentHeight, chainHeight)
				}
			} else if parentHeight == chainHeight && (!hasLatestPersisted || latestPersisted < parentHeight) {
				if n.shouldLogLivenessReason(fmt.Sprintf("registry_snapshot_materializing:%d", parentHeight), livenessReasonLogCooldown) {
					fmt.Printf("[REGISTRY-MATERIALIZING] height=%d chain_height=%d latest=%d\n",
						parentHeight, chainHeight, latestPersisted)
				}
			} else if n.shouldLogLivenessReason(fmt.Sprintf("registry_snapshot_missing:%d", parentHeight), livenessReasonLogCooldown) {
				dbState := n.DB != nil && n.DB.State != nil
				fmt.Printf("[REGISTRY-MISSING] height=%d chain_height=%d db_state=%t\n",
					parentHeight, chainHeight, dbState)
			}
		}
		if parentHeight > 1 && !parentAheadOfChain && !historyPruned && n.DB != nil && n.DB.State != nil && n.startupExecutionSnapshotCanRebuildLocally(parentHeight) {
			n.maybeScheduleRegistryHistoryRebuild(parentHeight, "registry_snapshot_missing")
		}
		if parentHeight <= 1 || chainHeight <= 1 {
			if parentHeight > 0 && n.Blockchain != nil {
				if parent, ok := n.Blockchain.GetBlock(parentHeight); ok {
					if repaired, _, ok := n.repairGenesisCommittedValidatorRegistryByHash(strings.TrimSpace(parent.ValidatorRegistryHash), GlobalValidatorRegistry.Snapshot()); ok && len(repaired) > 0 {
						return repaired
					}
				}
			}
			if boot, _, ok := n.genesisCommittedValidatorRegistryCandidate(GlobalValidatorRegistry.Snapshot()); ok && len(boot) > 0 {
				return boot
			}
			if DebugConsensus {
				if n.shouldLogLivenessReason(fmt.Sprintf("registry_bootstrap:%d", parentHeight), livenessReasonLogCooldown) {
					fmt.Printf("[REGISTRY-BOOTSTRAP] height=%d chain_height=%d reason=early_height\n",
						parentHeight, chainHeight)
				}
			}
			return copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
		}
		// Existing chains must not use mutable runtime registry as authoritative
		// validator commitment source.
		if n.DB == nil || n.DB.State == nil {
			// In-memory/test compatibility fallback when no committed snapshot
			// store exists. Persisted nodes must still derive from snapshot state.
			return copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
		}
		return nil
	}
	return copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
}

func (n *Node) validatorSetHashFromFinalizedSnapshot(height uint64, validators []string) string {
	if n == nil || height == 0 {
		return ""
	}
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	if len(registrySnapshot) == 0 {
		return ""
	}
	return strings.TrimSpace(validatorSetHashFromSnapshotForHeight(height, validators, registrySnapshot))
}

func (n *Node) expectedValidatorRegistryHashWithSource(height uint64) (string, string) {
	if n == nil || height == 0 {
		return "", "none"
	}
	if lateJoin := n.lateJoinAuthoritySnapshot(); lateJoin.Active && n.shouldTrackLateJoinAuthority() {
		if lateJoin.Authoritative && lateJoin.ValidatorRegistryHash != "" {
			return lateJoin.ValidatorRegistryHash, "snapshot_anchor"
		}
		return "", "chain_sample_pending_snapshot"
	}
	if n.Blockchain != nil {
		if blk, ok := n.Blockchain.GetBlock(height); ok {
			if hash := strings.TrimSpace(blk.ValidatorRegistryHash); hash != "" {
				return hash, "chain_block"
			}
		}
	}
	if hash, ok := n.chainParentCommittedValidatorRegistryHash(height); ok {
		return hash, "chain_parent_commitment"
	}
	postForkChainCommitment := height > 1 && validatorSetCommitmentV2EnabledAt(height-1)
	parentHeight := uint64(0)
	if height > 0 {
		parentHeight = height - 1
	}
	if parentHeight > 0 && n.DB != nil && n.DB.State != nil {
		if _, hash, source, ok := n.resolveCommittedValidatorRegistrySnapshot(parentHeight); ok && strings.TrimSpace(hash) != "" {
			if n.Blockchain == nil || n.Blockchain.Height() == 0 {
				return strings.TrimSpace(hash), source
			}
			if parent, ok := n.Blockchain.GetBlock(parentHeight); ok && strings.TrimSpace(parent.ValidatorRegistryHash) != "" {
				return strings.TrimSpace(hash), source
			}
		}
	}
	if n.Blockchain != nil {
		if n.Blockchain.Height() > 0 {
			if postForkChainCommitment {
				if parentHeight > 0 {
					if parent, ok := n.Blockchain.GetBlock(parentHeight); ok && strings.TrimSpace(parent.ValidatorRegistryHash) == "" {
						return "", "none"
					}
				}
				return "", "chain_parent_commitment"
			}
			return "", "none"
		}
	}
	if postForkChainCommitment {
		// V2 strict rule: validator-registry commitment cannot be derived from
		// runtime mutable registry maps.
		return "", "chain_parent_commitment"
	}
	return "", "none"
}

func (n *Node) deterministicValidatorRegistryCommitmentForHeight(height uint64) (map[string]ValidatorRecord, string, string) {
	if n == nil || height == 0 {
		return nil, "", "none"
	}
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	if len(registrySnapshot) == 0 {
		return nil, "", "none"
	}
	hash := strings.TrimSpace(ValidatorRegistrySnapshotHash(registrySnapshot))
	if hash == "" {
		return nil, "", "none"
	}
	return registrySnapshot, hash, "committed_parent_snapshot"
}

func (n *Node) expectedValidatorSetRootWithSource(height uint64) (string, string) {
	if n == nil || height == 0 {
		return "", "none"
	}
	if n.Blockchain != nil {
		if blk, ok := n.Blockchain.GetBlock(height); ok {
			if root := strings.TrimSpace(blk.ValidatorSetRoot); root != "" {
				return root, "chain_block"
			}
		}
	}
	if height > 1 && n.Blockchain != nil {
		parentHeight := height - 1
		parent, ok := n.Blockchain.GetBlock(parentHeight)
		if !ok {
			parent, ok = n.LoadBlock(int(parentHeight))
		}
		if ok &&
			strings.TrimSpace(parent.NextValidatorSetHash) != "" &&
			strings.TrimSpace(parent.NextValidatorSetRoot) != "" {
			return strings.TrimSpace(parent.NextValidatorSetRoot), "chain_parent_commitment"
		}
	}
	if snap, source, ok := n.committedParentProjectionSnapshot(height); ok && snap != nil {
		validators := n.plannedValidatorSetForHeightFromChain(height)
		if len(validators) == 0 {
			validators = validatorsFromSnapshot(snap)
		}
		if len(validators) > 0 {
			root := strings.TrimSpace(ValidatorSetMerkleRoot(height, validators, snap.ValidatorRegistry))
			if root == "" {
				root = strings.TrimSpace(snapshotValidatorSetRoot(snap))
			}
			if root != "" {
				return root, source
			}
		}
	}
	validators := n.consensusValidatorsForHeight(height)
	if len(validators) == 0 {
		return "", "none"
	}
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	if len(registrySnapshot) == 0 {
		return "", "none"
	}
	root := strings.TrimSpace(ValidatorSetMerkleRoot(height, validators, registrySnapshot))
	if root == "" {
		return "", "none"
	}
	return root, "snapshot_parent"
}

func (n *Node) expectedNextValidatorSetRootWithSource(height uint64, activeHash string, activeRoot string) (string, string) {
	if n == nil || height == 0 {
		return "", "none"
	}
	nextHeight := height + 1
	if n.Blockchain != nil {
		if blk, ok := n.Blockchain.GetBlock(nextHeight); ok {
			if root := strings.TrimSpace(blk.ValidatorSetRoot); root != "" {
				return root, "chain_block"
			}
		}
	}
	if root, source := n.expectedValidatorSetRootWithSource(nextHeight); strings.TrimSpace(root) != "" {
		return strings.TrimSpace(root), source
	}
	nextHash, _ := n.deterministicNextValidatorSetHashWithSource(height, activeHash)
	if nextHash != "" &&
		activeHash != "" &&
		activeRoot != "" &&
		strings.EqualFold(strings.TrimSpace(nextHash), strings.TrimSpace(activeHash)) {
		return strings.TrimSpace(activeRoot), "carry_forward"
	}
	return "", "none"
}

func (n *Node) deterministicNextValidatorSetHashWithSource(height uint64, activeHash string) (string, string) {
	if n == nil || height == 0 {
		return "", "none"
	}
	nextHeight := height + 1
	if committed, ok := n.chainParentCommittedValidatorSetHash(nextHeight); ok {
		return strings.TrimSpace(committed), "chain_parent_commitment"
	}
	if strings.TrimSpace(activeHash) != "" {
		return strings.TrimSpace(activeHash), "carry_forward"
	}
	if planned := n.plannedValidatorSetForHeightFromChain(nextHeight); len(planned) > 0 {
		if hash := n.validatorSetHashFromFinalizedSnapshot(nextHeight, planned); strings.TrimSpace(hash) != "" {
			return strings.TrimSpace(hash), "chain_planned_transition"
		}
	}
	if hash, ok := n.chainValidatorSetHash(nextHeight); ok {
		return strings.TrimSpace(hash), "chain"
	}
	return "", "none"
}

func (n *Node) deterministicNextValidatorSetHash(height uint64, activeHash string) string {
	hash, _ := n.deterministicNextValidatorSetHashWithSource(height, activeHash)
	return hash
}

func (n *Node) fillBlockNextValidatorSetCommitment(block *Block) {
	if n == nil || block == nil {
		return
	}
	if !validatorSetCommitmentV2EnabledAt(block.ID) {
		block.ValidatorSetRoot = ""
		block.NextValidatorSetHash = ""
		block.NextValidatorSetRoot = ""
		block.NextValidatorSetHeight = 0
		block.ActivationHeight = 0
		block.ValidatorRegistryHash = ""
		return
	}
	root, _ := n.expectedValidatorSetRootWithSource(block.ID)
	if root == "" {
		validators := n.freezeValidatorSetForHeight(block.ID, n.GetConsensusValidators(int(block.ID)))
		registrySnapshot := n.validatorRegistrySnapshotForHeight(block.ID)
		if len(registrySnapshot) > 0 {
			root = strings.TrimSpace(ValidatorSetMerkleRoot(block.ID, validators, registrySnapshot))
		}
	}
	block.ValidatorSetRoot = strings.TrimSpace(root)
	block.NextValidatorSetHeight = block.ID + 1
	block.ActivationHeight = block.NextValidatorSetHeight
	nextHash, nextRoot, _ := n.expectedNextValidatorSetCommitmentForBlock(*block)
	block.NextValidatorSetHash = strings.TrimSpace(nextHash)
	if block.NextValidatorSetHash == "" {
		block.NextValidatorSetHash = strings.TrimSpace(block.ValidatorSetHash)
	}
	block.NextValidatorSetRoot = strings.TrimSpace(nextRoot)
	if block.NextValidatorSetRoot == "" &&
		block.ValidatorSetRoot != "" &&
		block.NextValidatorSetHash != "" &&
		strings.EqualFold(strings.TrimSpace(block.NextValidatorSetHash), strings.TrimSpace(block.ValidatorSetHash)) {
		block.NextValidatorSetRoot = strings.TrimSpace(block.ValidatorSetRoot)
	}
	registryHash, registrySource := n.expectedValidatorRegistryHashWithSource(block.ID)
	if strings.TrimSpace(registryHash) == "" {
		// Allow proposers to re-anchor registry commitments from deterministic
		// committed snapshot history when the parent block was previously
		// accepted without a header hash during bootstrap recovery.
		if _, derivedHash, derivedSource := n.deterministicValidatorRegistryCommitmentForHeight(block.ID); strings.TrimSpace(derivedHash) != "" {
			registryHash = strings.TrimSpace(derivedHash)
			registrySource = derivedSource
		}
	}
	if _, projectedHash, ok := n.projectedValidatorUpdateRegistrySnapshotForBlock(*block); ok && strings.TrimSpace(projectedHash) != "" {
		registryHash = strings.TrimSpace(projectedHash)
		registrySource = "block_tx_registry_projection"
	}
	block.ValidatorRegistryHash = strings.TrimSpace(registryHash)
	if promotionHash, _ := n.expectedPromotionWindowHashWithSource(block.ID); strings.TrimSpace(promotionHash) != "" {
		block.PromotionWindowHash = strings.TrimSpace(promotionHash)
	} else if !promotionWindowRecordV1EnabledAt(block.ID) {
		block.PromotionWindowHash = ""
	}
	if DebugConsensus {
		fmt.Printf("[REGISTRY-COMMIT] height=%d source=%s hash=%s promotion=%s\n",
			block.ID,
			registrySource,
			ShortHash(block.ValidatorRegistryHash),
			ShortHash(block.PromotionWindowHash),
		)
	}
}

func (n *Node) validateBlockNextValidatorSetCommitment(block Block) error {
	if !validatorSetCommitmentV2EnabledAt(block.ID) {
		return nil
	}
	// Strict parent-commitment rule:
	// child.validator_set_hash must match parent.next_validator_set_hash when
	// parent carries a commitment for this height.
	if parentCommitted, ok := n.chainParentCommittedValidatorSetHash(block.ID); ok {
		childHash := strings.TrimSpace(block.ValidatorSetHash)
		if childHash == "" {
			return errors.New("missing_validator_set_hash_from_parent_commitment")
		}
		if !strings.EqualFold(childHash, strings.TrimSpace(parentCommitted)) {
			return errors.New("validator_set_hash_parent_commitment_mismatch")
		}
	}
	nextHash := strings.TrimSpace(block.NextValidatorSetHash)
	if nextHash == "" {
		if block.ID == 1 && (n == nil || n.DB == nil || n.DB.State == nil) {
			if _, ok := n.chainParentCommittedValidatorSetHash(block.ID); !ok {
				return nil
			}
		}
		return errors.New("missing_next_validator_set_hash")
	}
	activationHeight := blockActivationHeight(block)
	if activationHeight != block.ID+1 {
		return errors.New("invalid_next_validator_set_height")
	}
	if block.ActivationHeight > 0 &&
		block.NextValidatorSetHeight > 0 &&
		block.ActivationHeight != block.NextValidatorSetHeight {
		return errors.New("activation_height_alias_mismatch")
	}
	expectedNext, _, source := n.expectedNextValidatorSetCommitmentForBlock(block)
	if source == "chain_parent_commitment" && strings.TrimSpace(expectedNext) == "" {
		return errors.New("expected_next_validator_set_hash_missing")
	}
	if expectedNext != "" && !strings.EqualFold(expectedNext, nextHash) {
		if candidateSource, ok := n.blockNextValidatorSetHashMatchesAuthoritativeCandidates(block, nextHash); ok {
			if DebugConsensus {
				fmt.Printf("[SET-COMMITMENT] candidate-source match accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, candidateSource, ShortHash(expectedNext), ShortHash(nextHash))
			}
			return nil
		}
		if childSource, ok := n.queuedChildMatchesParentNextValidatorSetCommitment(block, nextHash); ok {
			if DebugConsensus {
				fmt.Printf("[SET-COMMITMENT] queued-child match accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, childSource, ShortHash(expectedNext), ShortHash(nextHash))
			}
			return nil
		}
		if childSource, ok := n.queuedChildExtendsBlockDuringSync(block); ok {
			if DebugConsensus {
				fmt.Printf("[SET-COMMITMENT] queued-child continuity accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, childSource, ShortHash(expectedNext), ShortHash(nextHash))
			}
			return nil
		}
		if n.syncExecutionResultQuorumFallback(block, n.syncContinuityValidatorFallback(block)) {
			if DebugConsensus {
				fmt.Printf("[SET-COMMITMENT] execution-result quorum accepted height=%d expected=%s got=%s\n",
					block.ID, ShortHash(expectedNext), ShortHash(nextHash))
			}
			return nil
		}
		switch source {
		case "none":
			if DebugConsensus {
				fmt.Printf("[SET-COMMITMENT] weak-source mismatch accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, source, ShortHash(expectedNext), ShortHash(nextHash))
			}
			return nil
		default:
			return fmt.Errorf("next_validator_set_hash_mismatch")
		}
	}
	return nil
}

func (n *Node) validateBlockNextValidatorSetRootCommitment(block Block) error {
	if !validatorSetCommitmentV2EnabledAt(block.ID) {
		return nil
	}
	got := strings.TrimSpace(block.NextValidatorSetRoot)
	if got == "" {
		if strings.TrimSpace(block.ValidatorSetRoot) != "" {
			return errors.New("missing_next_validator_set_root")
		}
		return nil
	}
	_, expected, source := n.expectedNextValidatorSetCommitmentForBlock(block)
	if expected != "" && !strings.EqualFold(expected, got) {
		if candidateSource, ok := n.blockNextValidatorSetRootMatchesAuthoritativeCandidates(block); ok {
			if DebugConsensus {
				fmt.Printf("[NEXT-SET-ROOT] candidate-source match accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, candidateSource, ShortHash(expected), ShortHash(got))
			}
			return nil
		}
		if childSource, ok := n.queuedChildMatchesParentNextValidatorSetRootCommitment(block, got); ok {
			if DebugConsensus {
				fmt.Printf("[NEXT-SET-ROOT] queued-child match accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, childSource, ShortHash(expected), ShortHash(got))
			}
			return nil
		}
		if n.syncExecutionResultQuorumFallback(block, n.syncContinuityValidatorFallback(block)) {
			if DebugConsensus {
				fmt.Printf("[NEXT-SET-ROOT] execution-result quorum accepted height=%d expected=%s got=%s\n",
					block.ID, ShortHash(expected), ShortHash(got))
			}
			return nil
		}
		switch source {
		case "snapshot_parent", "snapshot_parent_projection", "chain_block", "block_tx_plan", "chain_planned_transition", "carry_forward":
			return errors.New("next_validator_set_root_mismatch")
		default:
			if DebugConsensus {
				fmt.Printf("[NEXT-SET-ROOT] weak-source mismatch accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, source, ShortHash(expected), ShortHash(got))
			}
			return nil
		}
	}
	return nil
}

func (n *Node) validatorSetRootCommitmentRequiredAt(height uint64) bool {
	if n == nil || height <= 1 || !validatorSetCommitmentV2EnabledAt(height) {
		return false
	}
	if n.Blockchain == nil {
		return false
	}
	parent, ok := n.Blockchain.GetBlock(height - 1)
	if !ok {
		return false
	}
	return strings.TrimSpace(parent.ValidatorSetRoot) != ""
}

func (n *Node) validateBlockValidatorSetRootCommitment(block Block) error {
	if !validatorSetCommitmentV2EnabledAt(block.ID) {
		return nil
	}
	got := strings.TrimSpace(block.ValidatorSetRoot)
	if got == "" {
		if n.validatorSetRootCommitmentRequiredAt(block.ID) {
			return errors.New("missing_validator_set_root")
		}
		return nil
	}
	expected, source := n.expectedValidatorSetRootWithSource(block.ID)
	if expected != "" && !strings.EqualFold(expected, got) {
		if childSource, ok := n.queuedChildExtendsBlockDuringSync(block); ok {
			if DebugConsensus {
				fmt.Printf("[SET-ROOT] queued-child continuity accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, childSource, ShortHash(expected), ShortHash(got))
			}
			return nil
		}
		if n.syncExecutionResultQuorumFallback(block, n.syncContinuityValidatorFallback(block)) {
			if DebugConsensus {
				fmt.Printf("[SET-ROOT] execution-result quorum accepted height=%d expected=%s got=%s\n",
					block.ID, ShortHash(expected), ShortHash(got))
			}
			return nil
		}
		switch source {
		case "snapshot_parent", "chain_block":
			return errors.New("validator_set_root_mismatch")
		default:
			if DebugConsensus {
				fmt.Printf("[SET-ROOT] weak-source mismatch accepted height=%d source=%s expected=%s got=%s\n",
					block.ID, source, ShortHash(expected), ShortHash(got))
			}
			return nil
		}
	}
	return nil
}

func (n *Node) validateBlockValidatorRegistryCommitment(block Block) error {
	if !validatorSetCommitmentV2EnabledAt(block.ID) {
		return nil
	}
	required := n.validatorRegistryCommitmentRequiredAt(block.ID)
	got := strings.TrimSpace(block.ValidatorRegistryHash)
	parentUnanchored := false
	if n != nil && block.ID > 1 && n.Blockchain != nil {
		if parent, ok := n.Blockchain.GetBlock(block.ID - 1); ok && strings.TrimSpace(parent.ValidatorRegistryHash) == "" {
			parentUnanchored = true
		}
	}
	expected, source := n.expectedValidatorRegistryHashWithSource(block.ID)
	resolvedExpected := strings.TrimSpace(expected)
	resolvedSource := source
	if resolvedExpected == "" {
		if _, derivedHash, derivedSource := n.deterministicValidatorRegistryCommitmentForHeight(block.ID); strings.TrimSpace(derivedHash) != "" {
			resolvedExpected = strings.TrimSpace(derivedHash)
			resolvedSource = derivedSource
		}
	}
	if resolvedExpected == "" {
		if DebugConsensus && parentUnanchored {
			fmt.Printf("[REGISTRY-COMMITMENT] unanchored-parent rejected height=%d parent=%d reason=missing_expected\n",
				block.ID, block.ID-1)
		}
		return errors.New("validator_registry_expected_from_parent_missing")
	}
	if got == "" {
		if block.ID == 1 && (n == nil || n.DB == nil || n.DB.State == nil) {
			if _, ok := n.chainParentCommittedValidatorRegistryHash(block.ID); !ok {
				return nil
			}
		}
		if required || resolvedExpected != "" {
			return errors.New("missing_validator_registry_hash")
		}
		return nil
	}
	if DebugConsensus {
		fmt.Printf("[REGISTRY-COMMITMENT-CHECK] height=%d required=%t parent_unanchored=%t source=%s expected=%s got=%s\n",
			block.ID,
			required,
			parentUnanchored,
			resolvedSource,
			ShortHash(resolvedExpected),
			ShortHash(got),
		)
	}
	if resolvedExpected != "" && !strings.EqualFold(resolvedExpected, got) {
		if _, projectedHash, ok := n.projectedValidatorUpdateRegistrySnapshotForBlock(block); ok &&
			strings.TrimSpace(projectedHash) != "" &&
			strings.EqualFold(strings.TrimSpace(projectedHash), got) {
			return nil
		}
		return errors.New("validator_registry_hash_mismatch")
	}
	return nil
}

func (n *Node) validateBlockPromotionWindowCommitment(block Block) error {
	if !promotionWindowRecordV1EnabledAt(block.ID) {
		if strings.TrimSpace(block.PromotionWindowHash) != "" {
			return errors.New("promotion_window_hash_before_activation")
		}
		return nil
	}
	expected, source := n.expectedPromotionWindowHashWithSource(block.ID)
	got := strings.TrimSpace(block.PromotionWindowHash)
	if strings.EqualFold(source, "not_required") || strings.EqualFold(source, "disabled") {
		if got != "" {
			return errors.New("unexpected_promotion_window_hash")
		}
		return nil
	}
	if strings.EqualFold(source, "missing_committed_record") {
		return errors.New("promotion_window_record_missing")
	}
	if expected == "" {
		if got == "" {
			return nil
		}
		return errors.New("promotion_window_expected_missing")
	}
	if got == "" {
		return errors.New("missing_promotion_window_hash")
	}
	if !strings.EqualFold(expected, got) {
		return errors.New("promotion_window_hash_mismatch")
	}
	return nil
}

func (n *Node) validatorRegistryCommitmentRequiredAt(height uint64) bool {
	if !validatorSetCommitmentV2EnabledAt(height) {
		return false
	}
	if n == nil || height == 0 {
		return false
	}
	if _, ok := n.chainParentCommittedValidatorRegistryHash(height); ok {
		return true
	}
	parentHeight := height - 1
	if parentHeight > 0 {
		if n.Blockchain != nil {
			if parent, ok := n.Blockchain.GetBlock(parentHeight); ok && strings.TrimSpace(parent.ValidatorRegistryHash) == "" {
				return false
			}
		}
		if snap, err := n.GetSnapshot(parentHeight); err == nil && snap != nil {
			return strings.TrimSpace(snapshotValidatorRegistryHash(snap)) != ""
		}
	}
	if n.Blockchain == nil {
		return false
	}
	if parentHeight == 0 {
		return false
	}
	parent, ok := n.Blockchain.GetBlock(parentHeight)
	if !ok {
		return false
	}
	return strings.TrimSpace(parent.ValidatorRegistryHash) != ""
}

func activeSetModeAdaptiveCommittee() bool {
	return normalizeActiveSetMode(ValidatorActiveSetMode) == "adaptive_committee"
}

func activeSetModeUsesRegistrySmallSet() bool {
	if GenesisValidatorSetFrozen && GenesisFrozenValidatorSetSize > 0 {
		return false
	}
	switch normalizeActiveSetMode(ValidatorActiveSetMode) {
	case "adaptive_committee", "hybrid_score_rotation":
		return true
	default:
		return false
	}
}

func displayActiveSetMode() string {
	if GenesisValidatorSetFrozen && GenesisFrozenValidatorSetSize > 0 {
		return "genesis_frozen"
	}
	return normalizeActiveSetMode(ValidatorActiveSetMode)
}

func activeRegistrySmallValidatorSetFromSnapshot(height uint64, snapshot map[string]ValidatorRecord, requireRecordedActive bool) []string {
	if height == 0 || len(snapshot) == 0 {
		return nil
	}
	maxActive := validatorHybridMaxActiveValidators()
	if maxActive <= 0 {
		return nil
	}
	out := make([]string, 0, len(snapshot))
	for _, recVal := range snapshot {
		rec := recVal
		if strings.TrimSpace(rec.ID) == "" {
			continue
		}
		id := normalizeValidatorID(rec.ID)
		if id == "" || isValidatorBanned(id) {
			continue
		}
		if requireRecordedActive && rec.Status != ValidatorActive {
			continue
		}
		rec.ID = id
		ValidatorStateMachine{}.Update(&rec, height)
		if rec.Status != ValidatorActive {
			continue
		}
		if rec.JailUntilHeight > 0 && height < rec.JailUntilHeight {
			continue
		}
		if rec.JoinHeight > 0 && height < rec.JoinHeight {
			continue
		}
		if !validatorPassesStakeGate(id, rec.Stake) {
			continue
		}
		out = append(out, id)
	}
	out = canonicalValidatorIDs(out)
	if len(out) == 0 || len(out) > maxActive {
		return nil
	}
	return deterministicStakeHashOrderedValidatorIDs(out, snapshot)
}

func (n *Node) trustedRegistrySmallValidatorSetForHeight(height uint64, requireParentCommitment bool) ([]string, map[string]ValidatorRecord) {
	if n == nil || height == 0 || !activeSetModeUsesRegistrySmallSet() {
		return nil, nil
	}
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	if len(registrySnapshot) == 0 {
		return nil, nil
	}
	if requireParentCommitment && height > 1 && validatorSetCommitmentV2EnabledAt(height-1) {
		expected, ok := n.chainParentCommittedValidatorRegistryHash(height)
		if !ok || strings.TrimSpace(expected) == "" {
			return nil, nil
		}
		got := strings.TrimSpace(ValidatorRegistrySnapshotHash(registrySnapshot))
		if got == "" || !strings.EqualFold(got, strings.TrimSpace(expected)) {
			return nil, nil
		}
	}
	active := activeRegistrySmallValidatorSetFromSnapshot(height, registrySnapshot, true)
	if len(active) == 0 {
		return nil, nil
	}
	return active, registrySnapshot
}

type validatorOnboardingEval struct {
	ID                string
	JoinHeight        uint64
	GraceUntil        uint64
	Reason            string
	Eligible          bool
	BootstrapEligible bool
}

type validatorOnboardingDecision struct {
	ID         string
	JoinHeight uint64
	GraceUntil uint64
	Reason     string
	Admitted   bool
}

func validatorRegistryRecordFromSnapshot(snapshot map[string]ValidatorRecord, id string) (ValidatorRecord, bool) {
	if len(snapshot) == 0 {
		return ValidatorRecord{}, false
	}
	if rec, ok := snapshot[id]; ok {
		return rec, true
	}
	for key, rec := range snapshot {
		if strings.EqualFold(strings.TrimSpace(key), strings.TrimSpace(id)) {
			return rec, true
		}
	}
	return ValidatorRecord{}, false
}

func onboardingGraceUntil(joinHeight uint64, grace uint64) uint64 {
	max := ^uint64(0)
	if joinHeight > max-grace {
		return max
	}
	return joinHeight + grace
}

func evaluateValidatorOnboardingFromSnapshot(id string, height uint64, snapshot map[string]ValidatorRecord) validatorOnboardingEval {
	id = normalizeValidatorID(id)
	eval := validatorOnboardingEval{
		ID:     id,
		Reason: "missing_registry",
	}
	if id == "" {
		eval.Reason = "empty_id"
		return eval
	}
	if isValidatorBanned(id) {
		eval.Reason = "banned"
		return eval
	}
	grace := validatorOnboardingGraceBlocks()
	if grace == 0 {
		eval.Reason = "grace_disabled"
		return eval
	}
	rec, ok := validatorRegistryRecordFromSnapshot(snapshot, id)
	if !ok {
		eval.Reason = "missing_registry"
		return eval
	}
	if strings.TrimSpace(rec.ID) == "" {
		rec.ID = id
	}
	recCopy := rec
	ValidatorStateMachine{}.Update(&recCopy, height)
	eval.JoinHeight = recCopy.JoinHeight
	eval.GraceUntil = onboardingGraceUntil(recCopy.JoinHeight, grace)
	if recCopy.Status == ValidatorExited {
		eval.Reason = "exited"
		return eval
	}
	if recCopy.JailUntilHeight > 0 && height < recCopy.JailUntilHeight {
		eval.Reason = "jailed"
		return eval
	}
	if !validatorPassesStakeGate(id, recCopy.Stake) {
		eval.Reason = "no_stake"
		return eval
	}
	if recCopy.JoinHeight == 0 {
		eval.Reason = "no_join_height"
		return eval
	}
	if height < recCopy.JoinHeight {
		eval.Reason = "pre_join"
		return eval
	}
	if !validatorHasAnchoredConsensusPubKeyFromSnapshot(snapshot, id) {
		eval.Reason = "awaiting_pubkey"
		return eval
	}
	if height > eval.GraceUntil {
		eval.Reason = "grace_expired"
	} else {
		eval.Eligible = true
		eval.Reason = "within_grace"
	}
	if validatorOnboardingBootstrapLaneEnabled() {
		if (!validatorOnboardingBootstrapRequireNotJailed() || !(recCopy.JailUntilHeight > 0 && height < recCopy.JailUntilHeight)) &&
			(!validatorOnboardingBootstrapRequireStake() || validatorPassesStakeGate(id, recCopy.Stake)) {
			eval.BootstrapEligible = true
		}
	}
	return eval
}

func computeValidatorOnboardingAdmissions(base []string, signedCounts map[string]uint64, minSigned uint64, height uint64, snapshot map[string]ValidatorRecord, maxSlots int) ([]string, []string, []validatorOnboardingDecision) {
	base = canonicalValidatorIDs(base)
	if len(base) == 0 || maxSlots <= 0 {
		return nil, nil, nil
	}
	if minSigned == 0 {
		minSigned = 1
	}
	admitted := make([]string, 0, maxSlots)
	candidates := make([]string, 0, len(base))
	decisions := make([]validatorOnboardingDecision, 0, len(base))
	seenCandidates := make(map[string]struct{}, len(base))
	slotsUsed := 0

	for _, id := range base {
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if signedCounts[norm] >= minSigned {
			continue
		}

		eval := evaluateValidatorOnboardingFromSnapshot(norm, height, snapshot)
		decision := validatorOnboardingDecision{
			ID:         norm,
			JoinHeight: eval.JoinHeight,
			GraceUntil: eval.GraceUntil,
			Reason:     eval.Reason,
			Admitted:   false,
		}

		if !eval.Eligible {
			decisions = append(decisions, decision)
			continue
		}

		if _, ok := seenCandidates[norm]; !ok {
			seenCandidates[norm] = struct{}{}
			candidates = append(candidates, norm)
		}

		if slotsUsed < maxSlots {
			slotsUsed++
			admitted = append(admitted, norm)
			decision.Admitted = true
			decision.Reason = "within_grace"
		} else {
			decision.Reason = "slots_full"
		}
		decisions = append(decisions, decision)
	}

	return canonicalValidatorIDs(admitted), canonicalValidatorIDs(candidates), decisions
}

func computeValidatorBootstrapLaneAdmissions(base []string, signedCounts map[string]uint64, minSigned uint64, height uint64, snapshot map[string]ValidatorRecord, maxSlots int) ([]string, []string, []validatorOnboardingDecision) {
	base = canonicalValidatorIDs(base)
	if len(base) == 0 || maxSlots <= 0 || !validatorOnboardingBootstrapLaneEnabled() {
		return nil, nil, nil
	}
	if minSigned == 0 {
		minSigned = 1
	}
	admitted := make([]string, 0, maxSlots)
	candidates := make([]string, 0, len(base))
	decisions := make([]validatorOnboardingDecision, 0, len(base))
	seenCandidates := make(map[string]struct{}, len(base))
	slotsUsed := 0

	for _, id := range base {
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if signedCounts[norm] >= minSigned {
			continue
		}
		eval := evaluateValidatorOnboardingFromSnapshot(norm, height, snapshot)
		decision := validatorOnboardingDecision{
			ID:         norm,
			JoinHeight: eval.JoinHeight,
			GraceUntil: eval.GraceUntil,
			Reason:     eval.Reason,
			Admitted:   false,
		}
		// Bootstrap lane is persistent; grace-path candidates are handled by the
		// regular onboarding path and should not consume lane slots.
		if eval.Eligible {
			decisions = append(decisions, decision)
			continue
		}
		if !eval.BootstrapEligible {
			decisions = append(decisions, decision)
			continue
		}
		if _, ok := seenCandidates[norm]; !ok {
			seenCandidates[norm] = struct{}{}
			candidates = append(candidates, norm)
		}
		if slotsUsed < maxSlots {
			slotsUsed++
			admitted = append(admitted, norm)
			decision.Admitted = true
			decision.Reason = "bootstrap_lane"
		} else {
			decision.Reason = "slots_full"
		}
		decisions = append(decisions, decision)
	}

	return canonicalValidatorIDs(admitted), canonicalValidatorIDs(candidates), decisions
}

func validatorPassesReentrySnapshotChecks(id string, height uint64, snapshot map[string]ValidatorRecord) bool {
	id = normalizeValidatorID(id)
	if id == "" {
		return false
	}
	if isValidatorBanned(id) {
		return false
	}
	rec, ok := validatorRegistryRecordFromSnapshot(snapshot, id)
	if !ok {
		return false
	}
	if strings.TrimSpace(rec.ID) == "" {
		rec.ID = id
	}
	recCopy := rec
	ValidatorStateMachine{}.Update(&recCopy, height)
	if recCopy.Status == ValidatorExited {
		return false
	}
	if recCopy.JailUntilHeight > 0 && height < recCopy.JailUntilHeight {
		return false
	}
	if recCopy.JoinHeight > 0 && height < recCopy.JoinHeight {
		return false
	}
	if !validatorPassesStakeGate(id, recCopy.Stake) {
		return false
	}
	return true
}

func (n *Node) onboardingPendingAddHeight(id string) uint64 {
	if n == nil {
		return 0
	}
	id = normalizeValidatorID(id)
	if id == "" {
		return 0
	}
	n.validatorSetMu.RLock()
	defer n.validatorSetMu.RUnlock()
	if len(n.pendingValidators) == 0 {
		return 0
	}
	for key, act := range n.pendingValidators {
		if normalizeValidatorID(key) == id {
			return act
		}
	}
	return 0
}

func (n *Node) upsertOnboardingTracker(id string, state OnboardingState, reason string, evalHeight uint64) {
	if n == nil {
		return
	}
	id = normalizeValidatorID(id)
	if id == "" {
		return
	}
	scheduled := n.onboardingPendingAddHeight(id)
	effective := validatorSetTransitionActivationHeightAt(scheduled, evalHeight)
	entry := ValidatorActivationTracker{
		State:           state,
		LastReason:      strings.TrimSpace(reason),
		ScheduledHeight: scheduled,
		EffectiveHeight: effective,
		UpdatedAt:       time.Now(),
	}
	n.onboardingTrackerMu.Lock()
	if n.onboardingTracker == nil {
		n.onboardingTracker = make(map[string]ValidatorActivationTracker)
	}
	n.onboardingTracker[id] = entry
	n.onboardingTrackerMu.Unlock()
}

func (n *Node) onboardingTrackerSnapshot(id string) (ValidatorActivationTracker, bool) {
	if n == nil {
		return ValidatorActivationTracker{}, false
	}
	id = normalizeValidatorID(id)
	if id == "" {
		return ValidatorActivationTracker{}, false
	}
	n.onboardingTrackerMu.RLock()
	defer n.onboardingTrackerMu.RUnlock()
	if n.onboardingTracker == nil {
		return ValidatorActivationTracker{}, false
	}
	entry, ok := n.onboardingTracker[id]
	return entry, ok
}

func (n *Node) nodeSyncingForActivationGate() bool {
	if n == nil || n.Consensus == nil {
		return false
	}
	n.Consensus.mu.Lock()
	syncing := n.Consensus.Syncing
	n.Consensus.mu.Unlock()
	return syncing
}

func (n *Node) shouldDeferNonConsensusCommitMaintenance() bool {
	if n == nil || n.Consensus == nil {
		return false
	}
	n.Consensus.mu.Lock()
	syncing := n.Consensus.Syncing
	inFlight := n.Consensus.syncInFlight
	n.Consensus.mu.Unlock()
	return syncing || inFlight
}

func (n *Node) validatorSetTransitionActiveAtHeight(currentHeight uint64) (bool, uint64) {
	if n == nil || currentHeight == 0 {
		return false, 0
	}
	n.validatorSetMu.RLock()
	defer n.validatorSetMu.RUnlock()
	nextTransitionHeight := uint64(0)
	for _, act := range n.pendingValidators {
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, currentHeight)
		if effectiveActivation == 0 || effectiveActivation > currentHeight {
			continue
		}
		if nextTransitionHeight == 0 || effectiveActivation < nextTransitionHeight {
			nextTransitionHeight = effectiveActivation
		}
	}
	for _, act := range n.pendingValidatorRemovals {
		effectiveActivation := validatorSetTransitionActivationHeightAt(act, currentHeight)
		if effectiveActivation == 0 || effectiveActivation > currentHeight {
			continue
		}
		if nextTransitionHeight == 0 || effectiveActivation < nextTransitionHeight {
			nextTransitionHeight = effectiveActivation
		}
	}
	return nextTransitionHeight > 0, nextTransitionHeight
}

func (n *Node) validatorSetTransitionActiveNow() (bool, uint64) {
	if n == nil || n.Blockchain == nil {
		return false, 0
	}
	return n.validatorSetTransitionActiveAtHeight(n.Blockchain.Height())
}

func (n *Node) evaluateOnboardingState(id string, height uint64, snapshot map[string]ValidatorRecord) (OnboardingState, string, bool) {
	emit := func(state OnboardingState, reason string, schedEligible bool) (OnboardingState, string, bool) {
		n.upsertOnboardingTracker(id, state, reason, height)
		return state, reason, schedEligible
	}
	if n == nil {
		return emit(OnboardingStateBlocked, "node_unavailable", false)
	}
	id = normalizeValidatorID(id)
	if id == "" {
		return emit(OnboardingStateBlocked, "empty_id", false)
	}

	eval := evaluateValidatorOnboardingFromSnapshot(id, height, snapshot)
	if !eval.Eligible && !eval.BootstrapEligible {
		reason := strings.TrimSpace(eval.Reason)
		if reason == "" {
			reason = "not_activation_ready"
		}
		if reason == "awaiting_pubkey" {
			return emit(OnboardingStateAwaitingPubKey, reason, false)
		}
		return emit(OnboardingStateBlocked, reason, false)
	}

	if !validatorPassesReentrySnapshotChecks(id, height, snapshot) {
		reason := strings.TrimSpace(eval.Reason)
		switch reason {
		case "", "within_grace", "bootstrap_lane":
			reason = "not_activation_ready"
		}
		return emit(OnboardingStateBlocked, reason, false)
	}

	if n.nodeSyncingForActivationGate() {
		return emit(OnboardingStateAwaitingSync, "sync_incomplete", true)
	}

	now := time.Now()
	localFinalized := n.getFinalizedHeight()
	if localFinalized == 0 {
		localFinalized = height
	}

	var statusEval validatorLivenessEvaluation
	statusSeen := false
	n.validatorMu.RLock()
	st := n.validatorStatus[id]
	if st != nil {
		statusSeen = true
		statusEval = n.evaluateValidatorLivenessLocked(id, st, now, localFinalized)
	}
	n.validatorMu.RUnlock()
	if statusEval.LiveStrict {
		return emit(OnboardingStateActive, "live_validator", true)
	}
	if validatorOnboardingStrictActivationEnabled() &&
		statusSeen &&
		statusEval.FailReason == "out_of_set" &&
		statusEval.FreshHeartbeat &&
		statusEval.WithinDrift {
		if n.wasInRecentFrozenSet(id, height, 2) {
			return emit(OnboardingStateCandidateDetected, "rejoin_validator_heartbeat", true)
		}
		return emit(OnboardingStateAwaitingRejoinProof, "awaiting_rejoin_proof", false)
	}

	ttl := validatorLivenessHeartbeatTTL() + validatorLivenessGrace()
	candidateFresh := false
	n.candidateMu.RLock()
	cand := n.candidates[id]
	if cand != nil && !cand.PermanentBan && (cand.BanUntil == 0 || height >= cand.BanUntil) {
		if !cand.LastHeartbeatAt.IsZero() {
			age := now.Sub(cand.LastHeartbeatAt)
			if age < 0 {
				age = 0
			}
			if age <= ttl {
				candidateFresh = true
			}
		}
	}
	n.candidateMu.RUnlock()
	if candidateFresh {
		return emit(OnboardingStateCandidateDetected, "candidate_heartbeat", true)
	}

	return emit(OnboardingStateAwaitingHeartbeat, "awaiting_heartbeat", false)
}

func (n *Node) onboardingActivationReady(id string, height uint64, snapshot map[string]ValidatorRecord) (bool, string) {
	state, reason, schedEligible := n.evaluateOnboardingState(id, height, snapshot)
	if !schedEligible {
		if n != nil && DebugConsensus && n.shouldLogOnboardingGateDecision(id, reason, height) {
			fmt.Printf("[ONBOARDING-REJECT] validator=%s state=%s reason=%s height=%d\n",
				normalizeValidatorID(id),
				state,
				reason,
				height,
			)
		}
		return false, reason
	}
	return true, reason
}

func containsNormalizedValidatorID(ids []string, target string) bool {
	target = normalizeValidatorID(target)
	if target == "" {
		return false
	}
	for _, id := range ids {
		if normalizeValidatorID(id) == target {
			return true
		}
	}
	return false
}

func isSubsetValidatorSet(subset []string, superset []string) bool {
	subset = canonicalValidatorIDs(subset)
	superset = canonicalValidatorIDs(superset)
	if len(subset) == 0 || len(superset) == 0 || len(subset) > len(superset) {
		return false
	}
	for _, id := range subset {
		if !containsNormalizedValidatorID(superset, id) {
			return false
		}
	}
	return true
}

// chainDerivedValidatorAuthorityForHeight resolves validator authority from
// committed chain state only (snapshot/block), with genesis bootstrap when no
// chain history exists.
func (n *Node) chainDerivedValidatorAuthorityForHeight(height uint64) ([]string, string, bool) {
	if n == nil || height == 0 {
		return nil, "none", false
	}
	prevHeight := height - 1
	missingCommittedSnapshot := false
	if prevHeight > 0 {
		missingCommittedSnapshot = n.missingPersistedCommittedSnapshotForHeight(prevHeight)
	}
	if prevHeight > 0 && n.DB != nil && n.DB.State != nil && !missingCommittedSnapshot {
		if snap, _, source, ok := n.ResolveCommittedStateSnapshot(prevHeight); ok && snap != nil {
			if out := canonicalValidatorIDs(validatorsFromSnapshot(snap)); len(out) > 0 {
				normalized := normalizeCommittedValidatorAuthoritySource(source)
				if normalized == "none" {
					normalized = "snapshot_committed"
				}
				return out, normalized, true
			}
		}
	}
	if n.Blockchain != nil {
		if resolved, _, source, ok := n.resolveCommittedValidatorSetForHeight(height); ok && len(resolved) > 0 {
			normalized := normalizeCommittedValidatorAuthoritySource(source)
			if normalized == "none" {
				normalized = source
			}
			return canonicalValidatorIDs(resolved), normalized, true
		}
	}
	if n.Blockchain != nil {
		chainHeight := n.Blockchain.Height()
		if chainHeight > 0 {
			return nil, "none", false
		}
	}
	if out := canonicalValidatorIDs(append([]string{}, n.GenesisValidators...)); len(out) > 0 {
		return out, "genesis_bootstrap", true
	}
	return nil, "none", false
}

func (n *Node) legacyFrozenValidatorAuthorityForHeight(height uint64) ([]string, string, string, bool) {
	if n == nil || height == 0 {
		return nil, "", "none", false
	}
	if height > 1 && validatorSetCommitmentV2EnabledAt(height-1) {
		return nil, "", "none", false
	}
	if frozen := canonicalValidatorIDs(n.frozenValidatorsForHeight(height)); len(frozen) > 0 {
		hash := ""
		if frozenHash, ok := n.frozenValidatorSetHash(height); ok {
			hash = strings.TrimSpace(frozenHash)
		}
		if hash == "" {
			hash = strings.TrimSpace(n.validatorSetHashFromFinalizedSnapshot(height, frozen))
		}
		if hash == "" {
			hash = strings.TrimSpace(ValidatorSetHash(frozen))
		}
		if hash != "" {
			return frozen, hash, "frozen", true
		}
	}
	if height <= 1 {
		return nil, "", "none", false
	}
	prevHeight := height - 1
	prevFrozen := canonicalValidatorIDs(n.frozenValidatorsForHeight(prevHeight))
	if len(prevFrozen) == 0 {
		return nil, "", "none", false
	}
	prevHash := ""
	if frozenHash, ok := n.frozenValidatorSetHash(prevHeight); ok {
		prevHash = strings.TrimSpace(frozenHash)
	}
	if prevHash == "" {
		prevHash = strings.TrimSpace(n.validatorSetHashFromFinalizedSnapshot(prevHeight, prevFrozen))
	}
	if prevHash == "" {
		prevHash = strings.TrimSpace(ValidatorSetHash(prevFrozen))
	}
	if prevHash == "" {
		return nil, "", "none", false
	}
	if n.Blockchain == nil || n.Blockchain.Height() != prevHeight {
		return nil, "", "none", false
	}
	parent, ok := n.Blockchain.GetBlock(prevHeight)
	if !ok {
		return nil, "", "none", false
	}
	nextHash := strings.TrimSpace(parent.NextValidatorSetHash)
	if nextHash != "" && !strings.EqualFold(nextHash, prevHash) {
		return nil, "", "none", false
	}
	return prevFrozen, prevHash, "carry_forward", true
}

func (n *Node) authoritativeHeartbeatValidatorSetForHeight(height uint64) ([]string, string, bool) {
	if n == nil || height == 0 {
		return nil, "none", false
	}
	if committed := canonicalValidatorIDs(n.consensusValidatorsForHeight(height)); len(committed) > 0 {
		return committed, "committed", true
	}
	validators, _, source, ok := n.legacyFrozenValidatorAuthorityForHeight(height)
	if !ok || len(validators) == 0 {
		return nil, "none", false
	}
	return validators, source, true
}

func (n *Node) authoritativeHeartbeatMembershipAtHeight(id string, height uint64) (bool, string, bool) {
	if n == nil || height == 0 {
		return false, "none", false
	}
	id = normalizeValidatorID(id)
	if id == "" {
		return false, "none", false
	}
	if validators, source, ok := n.authoritativeHeartbeatValidatorSetForHeight(height); ok {
		return containsNormalizedValidatorID(validators, id), normalizeCommitteeAuthoritySource(source), true
	}
	if validators, source, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok {
		return containsNormalizedValidatorID(validators, id), normalizeCommitteeAuthoritySource(source), true
	}
	return false, "none", false
}

func normalizeCommitteeAuthoritySource(source string) string {
	switch strings.ToLower(strings.TrimSpace(source)) {
	case "chain_block_signatures", "chain_tip_carry":
		return "chain"
	default:
		return normalizeCommittedValidatorAuthoritySource(source)
	}
}

func (n *Node) deterministicCommitteeValidatorsForHeight(height uint64) ([]string, string, bool) {
	if n == nil || height == 0 {
		return nil, "none", false
	}
	if validators := n.freezeValidatorSetForHeight(height, n.consensusValidatorsForHeight(height)); len(validators) > 0 {
		if _, source, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok {
			if normalized := normalizeCommitteeAuthoritySource(source); normalized != "none" {
				return validators, normalized, true
			}
		}
		if _, _, source, ok := n.legacyFrozenValidatorAuthorityForHeight(height); ok {
			if normalized := normalizeCommitteeAuthoritySource(source); normalized != "none" {
				return validators, normalized, true
			}
		}
		if expectedHash, source := n.expectedValidatorSetHashWithSource(height); strings.TrimSpace(expectedHash) != "" {
			normalized := normalizeCommitteeAuthoritySource(source)
			if normalized == "none" {
				normalized = "committed"
			}
			return validators, normalized, true
		}
		return validators, "committed", true
	}
	if validators, _, source, ok := n.legacyFrozenValidatorAuthorityForHeight(height); ok && len(validators) > 0 {
		normalized := normalizeCommitteeAuthoritySource(source)
		if normalized == "none" {
			normalized = "frozen"
		}
		return validators, normalized, true
	}
	return nil, "none", false
}

func (n *Node) allowBootstrapLiveValidatorFallback(height uint64) bool {
	if n == nil {
		return false
	}
	if height == 0 {
		height = n.currentEpoch()
	}
	if height == 0 {
		height = 1
	}
	if n.Blockchain != nil {
		if n.Blockchain.Height() > 0 || n.Blockchain.FinalizedHeight() > 0 {
			return false
		}
	}
	if n.getFinalizedHeight() > 0 {
		return false
	}
	if _, source, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok {
		return normalizeCommitteeAuthoritySource(source) == "genesis_bootstrap"
	}
	if _, _, _, ok := n.legacyFrozenValidatorAuthorityForHeight(height); ok {
		return false
	}
	return true
}

func (n *Node) shouldUseLegacyFrozenHeartbeatAuthority(target uint64, reportedHeight uint64, finalizedHeight uint64, execEpoch uint64, validatorSetHeight uint64) bool {
	if n == nil || target == 0 {
		return false
	}
	if target > 1 && validatorSetCommitmentV2EnabledAt(target-1) {
		return false
	}
	if n.Blockchain == nil {
		return false
	}
	localHeight := n.Blockchain.Height()
	if localHeight == 0 || target != localHeight+1 {
		return false
	}
	remoteFinalized := finalizedHeight
	if remoteFinalized == 0 {
		remoteFinalized = reportedHeight
	}
	if remoteFinalized == 0 && execEpoch > 0 {
		remoteFinalized = execEpoch - 1
	}
	if remoteFinalized == 0 && validatorSetHeight > 0 {
		remoteFinalized = validatorSetHeight - 1
	}
	return remoteFinalized == localHeight
}

func (n *Node) currentValidatorSetSnapshot() []string {
	if n == nil {
		return nil
	}
	height := uint64(1)
	if n.Blockchain != nil {
		height = n.currentEpoch()
	} else {
		n.validatorSetMu.RLock()
		if n.validatorSetHeight > 0 {
			height = n.validatorSetHeight
		}
		n.validatorSetMu.RUnlock()
	}
	if snapshot, _, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok && len(snapshot) > 0 {
		return canonicalValidatorIDs(snapshot)
	}
	n.validatorSetMu.RLock()
	if len(n.epochValidators) > 0 {
		if epochSet := n.epochValidators[height]; len(epochSet) > 0 {
			// Compatibility fallback for local reconciliation paths only.
			// Consensus authority remains chain/snapshot committed sources.
			out := canonicalValidatorIDs(append([]string{}, epochSet...))
			n.validatorSetMu.RUnlock()
			return out
		}
		if (n.Blockchain == nil || n.Blockchain.Height() == 0) && height == 1 {
			if epochSet := n.epochValidators[0]; len(epochSet) > 0 {
				out := canonicalValidatorIDs(append([]string{}, epochSet...))
				n.validatorSetMu.RUnlock()
				return out
			}
		}
	}
	// Bootstrap-only legacy fallback before any chain history exists.
	if n.Blockchain == nil || n.Blockchain.Height() == 0 {
		if len(n.currentValidators) == 0 {
			n.validatorSetMu.RUnlock()
			return nil
		}
		out := canonicalValidatorIDs(append([]string{}, n.currentValidators...))
		n.validatorSetMu.RUnlock()
		return out
	}
	n.validatorSetMu.RUnlock()
	return nil
}

func (n *Node) selfPendingAddHeight() uint64 {
	if n == nil {
		return 0
	}
	selfID := normalizeValidatorID(n.ID)
	if selfID == "" {
		return 0
	}
	n.validatorSetMu.RLock()
	defer n.validatorSetMu.RUnlock()
	if len(n.pendingValidators) == 0 {
		return 0
	}
	minAct := uint64(0)
	for id, act := range n.pendingValidators {
		if normalizeValidatorID(id) != selfID || act == 0 {
			continue
		}
		if minAct == 0 || act < minAct {
			minAct = act
		}
	}
	return minAct
}

func (n *Node) reconcileSelfActivationFrozenSet(height uint64, selfID string) bool {
	if n == nil || height == 0 {
		return false
	}
	selfID = normalizeValidatorID(selfID)
	if selfID == "" {
		return false
	}
	// Only reconcile when this node is already part of the local deterministic
	// current set. Chain-derived authority is handled separately by the explicit
	// activation fallback path and should not silently rewrite frozen membership.
	var current []string
	n.validatorSetMu.RLock()
	if len(n.epochValidators) > 0 {
		if epochSet := n.epochValidators[height]; len(epochSet) > 0 {
			current = canonicalValidatorIDs(append([]string{}, epochSet...))
		}
	}
	if len(current) == 0 && len(n.currentValidators) > 0 {
		current = canonicalValidatorIDs(append([]string{}, n.currentValidators...))
	}
	n.validatorSetMu.RUnlock()
	if !containsNormalizedValidatorID(current, selfID) {
		return false
	}
	targetHash := strings.ToLower(strings.TrimSpace(ValidatorSetHash(current)))
	if targetHash == "" {
		return false
	}
	if frozenHash, ok := n.frozenValidatorSetHash(height); ok && strings.EqualFold(strings.TrimSpace(frozenHash), targetHash) {
		return false
	}
	return n.reconcileFrozenValidatorSetHash(height, targetHash)
}

const (
	selfActivationPendingWarnCooldown       = 20 * time.Second
	selfActivationPendingReconcileThreshold = uint64(8)
)

func (n *Node) clearSelfActivationPendingState() {
	if n == nil {
		return
	}
	n.selfActivationPendingMu.Lock()
	n.selfActivationPendingSince = 0
	n.selfActivationPendingStableSince = 0
	n.selfActivationPendingStableHash = ""
	n.selfActivationPendingLastWarnAt = time.Time{}
	n.selfActivationPendingLastReconcile = 0
	n.selfActivationPendingMu.Unlock()
}

func (n *Node) maybeHandleSelfActivationPending(height uint64, selfID string) {
	if n == nil || height == 0 {
		return
	}
	selfID = normalizeValidatorID(selfID)
	if selfID == "" {
		return
	}

	deterministicSet := n.currentValidatorSetSnapshot()
	if len(deterministicSet) == 0 {
		deterministicSet = canonicalValidatorIDs(n.GetConsensusValidators(int(height)))
	}
	if !containsNormalizedValidatorID(deterministicSet, selfID) {
		n.clearSelfActivationPendingState()
		return
	}

	deterministicHash := strings.ToLower(strings.TrimSpace(ValidatorSetHash(deterministicSet)))
	if deterministicHash == "" {
		return
	}
	frozenHash, _ := n.frozenValidatorSetHash(height)
	frozenHash = strings.ToLower(strings.TrimSpace(frozenHash))

	now := time.Now()
	n.selfActivationPendingMu.Lock()
	if n.selfActivationPendingSince == 0 {
		n.selfActivationPendingSince = height
	}
	if n.selfActivationPendingStableHash != deterministicHash {
		n.selfActivationPendingStableHash = deterministicHash
		n.selfActivationPendingStableSince = height
	}
	if n.selfActivationPendingStableSince == 0 {
		n.selfActivationPendingStableSince = height
	}
	pendingBlocks := uint64(0)
	if height > n.selfActivationPendingSince {
		pendingBlocks = height - n.selfActivationPendingSince
	}
	stableBlocks := uint64(0)
	if height > n.selfActivationPendingStableSince {
		stableBlocks = height - n.selfActivationPendingStableSince
	}
	shouldReconcile := pendingBlocks >= selfActivationPendingReconcileThreshold &&
		stableBlocks >= selfActivationPendingReconcileThreshold &&
		n.selfActivationPendingLastReconcile != height
	if shouldReconcile {
		n.selfActivationPendingLastReconcile = height
	}
	shouldWarn := DebugConsensus
	if shouldWarn && !n.selfActivationPendingLastWarnAt.IsZero() && now.Sub(n.selfActivationPendingLastWarnAt) < selfActivationPendingWarnCooldown {
		shouldWarn = false
	}
	if shouldWarn {
		n.selfActivationPendingLastWarnAt = now
	}
	n.selfActivationPendingMu.Unlock()

	if shouldWarn {
		fmt.Printf("[ACTIVATION-PENDING] id=%s height=%d reason=activation_pending_not_in_frozen_set pending_blocks=%d stable_blocks=%d deterministic_hash=%s frozen_hash=%s reconcile=%t\n",
			selfID, height, pendingBlocks, stableBlocks, ShortHash(deterministicHash), ShortHash(frozenHash), shouldReconcile)
	}
	if shouldReconcile {
		if n.reconcileSelfActivationFrozenSet(height, selfID) && DebugConsensus {
			if repairedHash, ok := n.frozenValidatorSetHash(height); ok {
				fmt.Printf("[ACTIVATION-PENDING] id=%s height=%d action=reconcile_applied frozen_hash=%s\n",
					selfID, height, ShortHash(strings.TrimSpace(repairedHash)))
			}
		}
	}
}

func (n *Node) missingPersistedCommittedSnapshotForHeight(height uint64) bool {
	if n == nil || height == 0 || n.DB == nil || n.DB.State == nil || n.Blockchain == nil {
		return false
	}
	chainHeight := n.Blockchain.Height()
	if chainHeight == 0 || height > chainHeight {
		return false
	}
	_, _, ok := n.resolveCommittedStateSnapshotFromStorage(height)
	return !ok
}

func (n *Node) allowSelfActivationChainDerivedFallback(height uint64, source string) bool {
	if n == nil || height == 0 {
		return false
	}
	switch normalizeSnapshotAuthoritySource(source) {
	case "snapshot_committed":
		return true
	case "tip_snapshot_repair", "trusted_snapshot":
		return false
	}
	switch normalizeCommittedValidatorAuthoritySource(source) {
	case "genesis_bootstrap":
		return true
	case "chain_parent_commitment", "registry_verified":
		if height <= 1 {
			return false
		}
		return n.missingPersistedCommittedSnapshotForHeight(height - 1)
	default:
		return false
	}
}

func (n *Node) selfActivationCommittedSetFallbackSource(height uint64, selfID string) (string, bool) {
	if n == nil || height <= 1 {
		return "", false
	}
	selfID = normalizeValidatorID(selfID)
	if selfID == "" || !n.missingPersistedCommittedSnapshotForHeight(height-1) {
		return "", false
	}
	if resolved, _, source, ok := n.resolveCommittedValidatorSetForHeight(height); ok &&
		containsNormalizedValidatorID(resolved, selfID) {
		return normalizeCommitteeAuthoritySource(source), true
	}
	if committed := canonicalValidatorIDs(n.consensusValidatorsForHeight(height)); len(committed) > 0 &&
		containsNormalizedValidatorID(committed, selfID) {
		source := "chain_parent_commitment"
		if _, expectedSource := n.expectedValidatorSetHashWithSource(height); expectedSource != "" {
			source = expectedSource
		}
		return normalizeCommitteeAuthoritySource(source), true
	}
	return "", false
}

func (n *Node) selfActiveValidatorAt(height uint64) (bool, string) {
	if n == nil {
		return false, "stake_or_key_unavailable"
	}
	if height == 0 {
		height = n.currentEpoch()
	}
	if !n.canParticipateAsValidator() {
		n.clearSelfActivationPendingState()
		return false, "stake_or_key_unavailable"
	}
	if !validatorOnboardingStrictActivationEnabled() {
		n.clearSelfActivationPendingState()
		return true, "active"
	}
	selfID := normalizeValidatorID(n.ID)
	if selfID == "" {
		return false, "activation_pending_not_in_frozen_set"
	}
	// Once a parent block has committed this height's validator-set hash, the
	// frozen/chain-derived set is authoritative. Registry lifecycle state may
	// include validators that are not in the current committee yet.
	if activeSetModeUsesRegistrySmallSet() && (height <= 1 || !validatorSetCommitmentV2EnabledAt(height-1)) {
		if active, _ := n.trustedRegistrySmallValidatorSetForHeight(height, true); containsNormalizedValidatorID(active, selfID) {
			n.clearSelfActivationPendingState()
			return true, "active"
		}
	}
	frozen := n.frozenValidatorsForHeight(height)
	missingCommittedSnapshot := height > 1 && n.missingPersistedCommittedSnapshotForHeight(height-1)
	if !containsNormalizedValidatorID(frozen, selfID) {
		if missingCommittedSnapshot {
			if source, ok := n.selfActivationCommittedSetFallbackSource(height, selfID); ok {
				n.clearSelfActivationPendingState()
				if DebugConsensus {
					if n.shouldLogLivenessReason(fmt.Sprintf("activation_fallback:%d", height), livenessReasonLogCooldown) {
						fmt.Printf("[ACTIVATION-FALLBACK] id=%s height=%d source=%s reason=snapshot_missing\n",
							selfID, height, normalizeCommitteeAuthoritySource(source))
					}
				}
				return true, "active_chain_derived_fallback"
			}
		}
		if derived, source, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok &&
			containsNormalizedValidatorID(derived, selfID) &&
			n.allowSelfActivationChainDerivedFallback(height, source) {
			n.clearSelfActivationPendingState()
			if DebugConsensus {
				if n.shouldLogLivenessReason(fmt.Sprintf("activation_fallback:%d", height), livenessReasonLogCooldown) {
					fmt.Printf("[ACTIVATION-FALLBACK] id=%s height=%d source=%s reason=frozen_missing\n",
						selfID, height, normalizeCommitteeAuthoritySource(source))
				}
			}
			return true, "active_chain_derived_fallback"
		}
		if !missingCommittedSnapshot {
			if source, ok := n.selfActivationCommittedSetFallbackSource(height, selfID); ok {
				n.clearSelfActivationPendingState()
				if DebugConsensus {
					if n.shouldLogLivenessReason(fmt.Sprintf("activation_fallback:%d", height), livenessReasonLogCooldown) {
						fmt.Printf("[ACTIVATION-FALLBACK] id=%s height=%d source=%s reason=snapshot_missing\n",
							selfID, height, normalizeCommitteeAuthoritySource(source))
					}
				}
				return true, "active_chain_derived_fallback"
			}
		}
		if validators, _, _, ok := n.legacyFrozenValidatorAuthorityForHeight(height); ok && containsNormalizedValidatorID(validators, selfID) {
			n.clearSelfActivationPendingState()
			return true, "active"
		}
	}
	if !containsNormalizedValidatorID(frozen, selfID) {
		if n.reconcileSelfActivationFrozenSet(height, selfID) {
			frozen = n.frozenValidatorsForHeight(height)
		}
	}
	if containsNormalizedValidatorID(frozen, selfID) {
		n.clearSelfActivationPendingState()
		return true, "active"
	}
	n.maybeHandleSelfActivationPending(height, selfID)
	frozen = n.frozenValidatorsForHeight(height)
	if containsNormalizedValidatorID(frozen, selfID) {
		n.clearSelfActivationPendingState()
		return true, "active"
	}
	return false, "activation_pending_not_in_frozen_set"
}

func (n *Node) stableFrozenHashForAdvertise(height uint64) string {
	if n == nil {
		return ""
	}
	if height == 0 {
		height = n.currentEpoch()
	}
	if hash, ok := n.frozenValidatorSetHash(height); ok {
		hash = strings.TrimSpace(hash)
		if hash != "" {
			return hash
		}
	}
	if height > 1 {
		if hash, ok := n.frozenValidatorSetHash(height - 1); ok {
			hash = strings.TrimSpace(hash)
			if hash != "" {
				return hash
			}
		}
	}
	return ""
}

func shouldLogOnboardingDecision(reason string) bool {
	switch reason {
	case "within_grace", "bootstrap_lane", "slots_full", "no_stake", "grace_expired", "jailed", "banned":
		return true
	default:
		return false
	}
}

const onboardingOfflinePendingLogCooldown = 20 * time.Second

func (n *Node) validatorPeerLikelyOffline(id string) bool {
	if n == nil {
		return false
	}
	id = normalizeValidatorID(id)
	if id == "" {
		return false
	}

	now := time.Now()
	hasTelemetry := false
	backoffActive := false

	n.peerStateMu.Lock()
	for peerID, vid := range n.peerToValidator {
		if normalizeValidatorID(vid) != id {
			continue
		}
		hasTelemetry = true
		if n.connectedPeers[peerID] && n.peerHelloOK[peerID] {
			n.peerStateMu.Unlock()
			return false
		}
		if n.connectingPeers[peerID] {
			n.peerStateMu.Unlock()
			return false
		}
		if next, ok := n.peerDialNext[peerID]; ok && !next.IsZero() && now.Before(next) {
			backoffActive = true
		}
	}
	n.peerStateMu.Unlock()

	if backoffActive {
		return true
	}
	if hasTelemetry {
		return true
	}

	ValidatorAddrBook.mu.RLock()
	_, hasAddr := ValidatorAddrBook.m[id]
	ValidatorAddrBook.mu.RUnlock()
	return hasAddr
}

func (n *Node) isOfflinePendingOnboarding(id, reason string, _ uint64) bool {
	if n == nil {
		return false
	}
	id = normalizeValidatorID(id)
	reason = strings.TrimSpace(strings.ToLower(reason))
	if id == "" || reason != "awaiting_pubkey" {
		return false
	}

	ttl := validatorLivenessHeartbeatTTL() + validatorLivenessGrace()
	now := time.Now()
	hasFreshHeartbeat := false

	n.validatorMu.RLock()
	if st := n.validatorStatus[id]; st != nil && !st.LastSeen.IsZero() {
		age := now.Sub(st.LastSeen)
		if age < 0 {
			age = 0
		}
		if age <= ttl {
			hasFreshHeartbeat = true
		}
	}
	n.validatorMu.RUnlock()

	n.candidateMu.RLock()
	if cand := n.candidates[id]; cand != nil && !cand.LastHeartbeatAt.IsZero() {
		age := now.Sub(cand.LastHeartbeatAt)
		if age < 0 {
			age = 0
		}
		if age <= ttl {
			hasFreshHeartbeat = true
		}
	}
	n.candidateMu.RUnlock()

	if hasFreshHeartbeat {
		return false
	}
	return n.validatorPeerLikelyOffline(id)
}

func (n *Node) shouldEmitOnboardingLog(bucket, id, reason string, admitted bool, cooldown time.Duration) bool {
	if n == nil || cooldown <= 0 {
		return true
	}
	id = normalizeValidatorID(id)
	reason = strings.TrimSpace(strings.ToLower(reason))
	if id == "" || reason == "" {
		return true
	}
	key := strings.TrimSpace(strings.ToLower(bucket)) + "|" + id + "|" + reason + "|" + strconv.FormatBool(admitted)
	now := time.Now()
	n.onboardingLogMu.Lock()
	defer n.onboardingLogMu.Unlock()
	if n.onboardingLogLast == nil {
		n.onboardingLogLast = make(map[string]time.Time)
	}
	if last, ok := n.onboardingLogLast[key]; ok && now.Sub(last) < cooldown {
		return false
	}
	pruneBefore := now.Add(-4 * cooldown)
	for k, ts := range n.onboardingLogLast {
		if ts.Before(pruneBefore) {
			delete(n.onboardingLogLast, k)
		}
	}
	n.onboardingLogLast[key] = now
	return true
}

func (n *Node) shouldLogOnboardingGateDecision(id, reason string, height uint64) bool {
	if n == nil {
		return true
	}
	if !n.isOfflinePendingOnboarding(id, reason, height) {
		return true
	}
	return n.shouldEmitOnboardingLog("onboarding_gate", id, reason, false, onboardingOfflinePendingLogCooldown)
}

func (n *Node) shouldLogOnboardingDecisionForID(bucket string, d validatorOnboardingDecision, height uint64) bool {
	if !shouldLogOnboardingDecision(d.Reason) {
		return false
	}
	if !n.isOfflinePendingOnboarding(d.ID, "awaiting_pubkey", height) {
		return true
	}
	return n.shouldEmitOnboardingLog(bucket, d.ID, d.Reason, d.Admitted, onboardingOfflinePendingLogCooldown)
}

func (n *Node) getEligibleSortedValidatorIDs(height uint64, hint []string) []string {
	if n == nil {
		return canonicalValidatorIDs(hint)
	}
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	if len(registrySnapshot) == 0 {
		legacyWeakSource := height <= 1 || !validatorSetCommitmentV2EnabledAt(height-1)
		if legacyWeakSource {
			// Legacy eligibility paths may use runtime registry as a weak hint only.
			// Consensus hash commitment authority still comes from chain/snapshot.
			registrySnapshot = copyValidatorRegistrySnapshot(GlobalValidatorRegistry.Snapshot())
		}
	}
	base := canonicalValidatorIDs(append([]string{}, hint...))
	if activeSetModeUsesRegistrySmallSet() {
		if fromRegistry := selectAllStakedValidatorsFromSnapshot(height, registrySnapshot); len(fromRegistry) > 0 {
			base = canonicalValidatorIDs(fromRegistry)
		}
	}
	if len(base) == 0 {
		base = canonicalValidatorIDs(n.consensusValidatorsForHeight(height))
	}
	if len(base) == 0 {
		base = canonicalValidatorIDs(n.GetConsensusValidators(int(height)))
	}
	if len(base) == 0 {
		return nil
	}

	baseHash := n.validatorSetHashFromFinalizedSnapshot(height, base)
	if strings.TrimSpace(baseHash) == "" {
		baseHash = ValidatorSetHash(base)
	}
	var version uint64
	if len(baseHash) >= 16 {
		if parsed, err := strconv.ParseUint(baseHash[:16], 16, 64); err == nil {
			version = parsed
		}
	}
	version ^= height

	n.validatorSetMu.RLock()
	cachedVersion := n.eligibleIndexVersion
	cachedEligible := append([]string{}, n.eligibleSortedValidators...)
	n.validatorSetMu.RUnlock()
	if cachedVersion == version && len(cachedEligible) > 0 {
		return cachedEligible
	}

	if activeSetModeUsesRegistrySmallSet() && len(registrySnapshot) > 0 {
		safeStaked := selectAllStakedValidatorsFromSnapshot(height, registrySnapshot)
		if len(safeStaked) > 0 && len(safeStaked) <= validatorHybridMaxActiveValidators() {
			filtered := make([]string, 0, len(safeStaked))
			for _, id := range safeStaked {
				norm := normalizeValidatorID(id)
				if norm == "" {
					continue
				}
				rec, ok := validatorRegistryRecordFromSnapshot(registrySnapshot, norm)
				if ok {
					rec.ID = norm
				}
				if ok && rec.Status == ValidatorActive {
					filtered = append(filtered, norm)
					continue
				}
				if validatorOnboardingStrictActivationEnabled() {
					ready, _ := n.onboardingActivationReady(norm, height, registrySnapshot)
					if !ready {
						continue
					}
				}
				filtered = append(filtered, norm)
			}
			filtered = deterministicStakeHashOrderedValidatorIDs(filtered, registrySnapshot)
			if len(filtered) > 0 {
				n.validatorSetMu.Lock()
				n.eligibleIndexVersion = version
				n.eligibleSortedValidators = append([]string{}, filtered...)
				n.validatorSetMu.Unlock()
				return filtered
			}
		}
	}

	window := validatorSelectionActivityWindowBlocks()
	minSigned := validatorSelectionMinSignedBlocks()
	if minSigned == 0 {
		minSigned = 1
	}
	tip := uint64(0)
	if height > 0 {
		tip = height - 1
	}
	signedCounts := n.recentSignedCountFromFinalizedChain(tip, window)
	onboardingSlots := validatorOnboardingMaxNewSlots()
	bootstrapLaneSlots := validatorOnboardingBootstrapMaxNewSlots()

	filtered := make([]string, 0, len(base))
	seen := make(map[string]struct{}, len(base))
	for _, id := range base {
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if _, ok := seen[norm]; ok {
			continue
		}
		if signedCounts[norm] >= minSigned {
			filtered = append(filtered, norm)
			seen[norm] = struct{}{}
		}
	}

	if onboardingSlots > 0 {
		admitted, _, decisions := computeValidatorOnboardingAdmissions(base, signedCounts, minSigned, height, registrySnapshot, onboardingSlots)
		for _, id := range admitted {
			norm := normalizeValidatorID(id)
			if norm == "" {
				continue
			}
			if _, ok := seen[norm]; ok {
				continue
			}
			if validatorOnboardingStrictActivationEnabled() {
				ready, reason := n.onboardingActivationReady(norm, height, registrySnapshot)
				if !ready {
					if DebugConsensus && n.shouldLogOnboardingGateDecision(norm, reason, height) {
						fmt.Printf("[ONBOARDING-GATE] id=%s height=%d admitted=false reason=%s\n", norm, height, reason)
					}
					continue
				}
			}
			filtered = append(filtered, norm)
			seen[norm] = struct{}{}
		}
		if DebugConsensus {
			for _, d := range decisions {
				if !n.shouldLogOnboardingDecisionForID("onboarding", d, height) {
					continue
				}
				fmt.Printf("[ONBOARDING] id=%s join_h=%d grace_until=%d admitted=%t reason=%s\n",
					d.ID,
					d.JoinHeight,
					d.GraceUntil,
					d.Admitted,
					d.Reason,
				)
			}
		}
	}
	if bootstrapLaneSlots > 0 && validatorOnboardingBootstrapLaneEnabled() {
		admittedLane, _, laneDecisions := computeValidatorBootstrapLaneAdmissions(base, signedCounts, minSigned, height, registrySnapshot, bootstrapLaneSlots)
		for _, id := range admittedLane {
			norm := normalizeValidatorID(id)
			if norm == "" {
				continue
			}
			if _, ok := seen[norm]; ok {
				continue
			}
			if validatorOnboardingStrictActivationEnabled() {
				ready, reason := n.onboardingActivationReady(norm, height, registrySnapshot)
				if !ready {
					if DebugConsensus && n.shouldLogOnboardingGateDecision(norm, reason, height) {
						fmt.Printf("[ONBOARDING-GATE] id=%s height=%d admitted=false reason=%s\n", norm, height, reason)
					}
					continue
				}
			}
			filtered = append(filtered, norm)
			seen[norm] = struct{}{}
		}
		if DebugConsensus {
			for _, d := range laneDecisions {
				if !n.shouldLogOnboardingDecisionForID("onboarding_lane", d, height) {
					continue
				}
				fmt.Printf("[ONBOARDING-LANE] id=%s join_h=%d grace_until=%d admitted=%t reason=%s\n",
					d.ID,
					d.JoinHeight,
					d.GraceUntil,
					d.Admitted,
					d.Reason,
				)
			}
		}
	}

	// live_starvation_reentry:
	// if signed-activity filtering under-fills committee eligibility, re-admit
	// live validators from base in deterministic base order.
	desiredEligible := n.adaptiveCommitteeTarget(len(base))
	if len(filtered) < desiredEligible {
		needed := desiredEligible - len(filtered)
		liveIDs := n.snapshotLiveValidatorIDsForSetSafety(height)
		prevMembers := make(map[string]struct{})
		if height > 0 {
			// Post-bootstrap re-entry is uniform for all validators: a live node may
			// be re-admitted only if it was already in the frozen set at H-1.
			for _, id := range n.frozenValidatorsForHeight(height - 1) {
				norm := normalizeValidatorID(id)
				if norm == "" {
					continue
				}
				prevMembers[norm] = struct{}{}
			}
		}
		for _, id := range base {
			if needed <= 0 {
				break
			}
			norm := normalizeValidatorID(id)
			if norm == "" {
				continue
			}
			if _, ok := seen[norm]; ok {
				continue
			}
			if _, ok := liveIDs[norm]; !ok {
				continue
			}
			if _, ok := prevMembers[norm]; !ok {
				continue
			}
			if !validatorPassesReentrySnapshotChecks(norm, height, registrySnapshot) {
				continue
			}
			filtered = append(filtered, norm)
			seen[norm] = struct{}{}
			needed--
			if DebugConsensus {
				fmt.Printf("[REENTRY] height=%d added=%s reason=live_prev_member_starvation\n", height, norm)
			}
		}
	}

	floor := minActiveValidatorsFloor()
	if len(filtered) < floor {
		for _, id := range base {
			norm := normalizeValidatorID(id)
			if norm == "" {
				continue
			}
			if _, ok := seen[norm]; ok {
				continue
			}
			filtered = append(filtered, norm)
			seen[norm] = struct{}{}
			if len(filtered) >= floor {
				break
			}
		}
	}

	filtered = deterministicStakeHashOrderedValidatorIDs(filtered, registrySnapshot)
	safeFiltered := append([]string{}, filtered...)
	if len(safeFiltered) == 0 {
		safeFiltered = deterministicStakeHashOrderedValidatorIDs(base, registrySnapshot)
	}

	if DeterministicValidatorSelection {
		deterministicFiltered := make([]string, 0, len(safeFiltered))
		for _, id := range safeFiltered {
			if IsValidatorEligible(id, int(height)) {
				deterministicFiltered = append(deterministicFiltered, id)
			}
		}
		deterministicFiltered = deterministicStakeHashOrderedValidatorIDs(deterministicFiltered, registrySnapshot)
		if len(deterministicFiltered) > 0 {
			filtered = deterministicFiltered
		} else {
			filtered = safeFiltered
		}
	} else {
		filtered = safeFiltered
	}
	if len(filtered) == 0 {
		filtered = deterministicStakeHashOrderedValidatorIDs(base, registrySnapshot)
	}

	n.validatorSetMu.Lock()
	n.eligibleIndexVersion = version
	n.eligibleSortedValidators = append([]string{}, filtered...)
	n.validatorSetMu.Unlock()
	return filtered
}

func (n *Node) committeeForHeight(height uint64, hint []string) []string {
	if n == nil || height == 0 {
		return nil
	}

	n.validatorSetMu.RLock()
	if n.committeeByHeight != nil {
		if existing := n.committeeByHeight[height]; len(existing) > 0 {
			out := append([]string{}, existing...)
			n.validatorSetMu.RUnlock()
			return out
		}
	}
	n.validatorSetMu.RUnlock()

	eligible := n.deterministicCommitteeEligibleValidators(height, hint)
	if len(eligible) == 0 {
		return nil
	}
	target := n.adaptiveCommitteeTarget(len(eligible))
	committee := n.buildAdaptiveCommittee(height, eligible, target)
	if len(committee) == 0 {
		committee = eligible
	}
	hash := n.validatorSetHashFromFinalizedSnapshot(height, committee)
	if strings.TrimSpace(hash) == "" {
		hash = ValidatorSetHash(committee)
	}
	prevHash := ""
	if height > 1 {
		prevHash, _ = n.committeeHashForHeight(height - 1)
	}

	n.validatorSetMu.Lock()
	if n.committeeByHeight == nil {
		n.committeeByHeight = make(map[uint64][]string)
	}
	if n.committeeHashByHeight == nil {
		n.committeeHashByHeight = make(map[uint64]string)
	}
	n.committeeByHeight[height] = append([]string{}, committee...)
	n.committeeHashByHeight[height] = hash
	n.pruneCommitteeStateLocked(height)
	n.validatorSetMu.Unlock()

	if DebugConsensus && !strings.EqualFold(strings.TrimSpace(prevHash), strings.TrimSpace(hash)) {
		fmt.Printf("[COMMITTEE] height=%d size=%d target=%d hash=%s\n", height, len(committee), target, ShortHash(hash))
	}
	return committee
}

// deterministicCommitteeEligibleValidators keeps consensus committee
// construction independent from heartbeat, liveness, onboarding queues, and
// other node-local state. Membership changes must arrive through committed
// validator authority; adaptive selection only rotates that committed pool.
func (n *Node) deterministicCommitteeEligibleValidators(height uint64, hint []string) []string {
	if n == nil || height == 0 {
		return nil
	}
	base := canonicalValidatorIDs(hint)
	if len(base) == 0 {
		if committed, _, ok := n.chainDerivedValidatorAuthorityForHeight(height); ok {
			base = canonicalValidatorIDs(committed)
		}
	}
	if len(base) == 0 {
		base = canonicalValidatorIDs(n.consensusValidatorsForHeight(height))
	}
	if len(base) == 0 && (n.Blockchain == nil || n.Blockchain.Height() == 0) {
		base = canonicalValidatorIDs(n.GenesisValidators)
	}
	if len(base) == 0 {
		return nil
	}
	return deterministicStakeHashOrderedValidatorIDs(base, n.validatorRegistrySnapshotForHeight(height))
}

func (n *Node) committeeHashForHeight(height uint64) (string, bool) {
	if n == nil || height == 0 {
		return "", false
	}
	n.validatorSetMu.RLock()
	defer n.validatorSetMu.RUnlock()
	if n.committeeHashByHeight == nil {
		return "", false
	}
	hash := strings.TrimSpace(n.committeeHashByHeight[height])
	if hash == "" {
		return "", false
	}
	return hash, true
}

func (n *Node) pruneCommitteeStateLocked(height uint64) {
	if n == nil || height == 0 {
		return
	}
	lower := uint64(0)
	if height > 2 {
		lower = height - 2
	}
	upper := height + 2

	pruneSliceMap := func(m map[uint64][]string) {
		for h := range m {
			if h < lower || h > upper {
				delete(m, h)
			}
		}
	}
	pruneHashMap := func(m map[uint64]string) {
		for h := range m {
			if h < lower || h > upper {
				delete(m, h)
			}
		}
	}
	pruneLiveMap := func(m map[uint64]map[string]bool) {
		for h := range m {
			if h < lower || h > upper {
				delete(m, h)
			}
		}
	}
	pruneTimeMap := func(m map[uint64]time.Time) {
		for h := range m {
			if h < lower || h > upper {
				delete(m, h)
			}
		}
	}
	pruneDurMap := func(m map[uint64]time.Duration) {
		for h := range m {
			if h < lower || h > upper {
				delete(m, h)
			}
		}
	}

	// Do not prune frozen validator-set history here.
	// Frozen sets are consensus-critical historical anchors and may be needed
	// later for startup self-check / repair at historical heights.
	pruneSliceMap(n.committeeByHeight)
	pruneHashMap(n.committeeHashByHeight)
	pruneLiveMap(n.committeeLiveByHeight)
	pruneTimeMap(n.safeModeUntilByHeight)
	pruneDurMap(n.safeModeWindowByHeight)
}

func (n *Node) replaceFrozenValidatorSetForCommittedHash(height uint64, validators []string, hash string) []string {
	if n == nil || height == 0 {
		return nil
	}
	canonical := canonicalValidatorIDs(validators)
	hash = strings.TrimSpace(hash)
	if len(canonical) == 0 || hash == "" {
		return nil
	}

	n.validatorSetMu.Lock()
	if n.frozenValidatorsByHeight == nil {
		n.frozenValidatorsByHeight = make(map[uint64][]string)
	}
	if n.frozenValidatorHashByHeight == nil {
		n.frozenValidatorHashByHeight = make(map[uint64]string)
	}
	n.frozenValidatorsByHeight[height] = append([]string{}, canonical...)
	n.frozenValidatorHashByHeight[height] = hash
	if n.committeeByHeight != nil {
		n.committeeByHeight[height] = append([]string{}, canonical...)
	}
	if n.committeeHashByHeight != nil {
		n.committeeHashByHeight[height] = hash
	}
	n.pruneCommitteeStateLocked(height)
	n.validatorSetMu.Unlock()

	n.persistValidatorFreezeEntry(height, canonical, hash)
	if DebugConsensus && n.shouldLogLivenessReason(fmt.Sprintf("frozen_set_repair:%d:%s", height, strings.ToLower(hash)), livenessReasonLogCooldown) {
		fmt.Printf("[SET-FREEZE-REPAIR] height=%d vhash=%s size=%d source=committed_parent\n",
			height, ShortHash(hash), len(canonical))
	}
	return canonical
}

func (n *Node) repairFrozenValidatorSetForCommittedHash(height uint64, targetHash string, candidates ...[]string) ([]string, bool) {
	if n == nil || height == 0 {
		return nil, false
	}
	targetHash = strings.TrimSpace(targetHash)
	if targetHash == "" {
		return nil, false
	}
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	tryCandidate := func(values []string) ([]string, bool) {
		if matched, ok := n.validatorSetCandidateMatchesTarget(height, targetHash, values, registrySnapshot); ok {
			return n.replaceFrozenValidatorSetForCommittedHash(height, matched, targetHash), true
		}
		return nil, false
	}
	for _, candidate := range candidates {
		if repaired, ok := tryCandidate(candidate); ok {
			return repaired, true
		}
	}
	if resolved, resolvedHash, _, ok := n.resolveCommittedValidatorSetForHeight(height); ok &&
		strings.EqualFold(strings.TrimSpace(resolvedHash), targetHash) {
		if repaired, ok := tryCandidate(resolved); ok {
			return repaired, true
		}
		return n.replaceFrozenValidatorSetForCommittedHash(height, resolved, targetHash), true
	}
	if height > 1 {
		if frozen, ok := n.committedFrozenValidatorSetCandidate(targetHash, height-1); ok {
			if repaired, ok := tryCandidate(frozen); ok {
				return repaired, true
			}
		}
	}
	if reconstructed, ok := n.reconstructValidatorSetCandidateForTarget(height, targetHash, registrySnapshot, candidates...); ok {
		return n.replaceFrozenValidatorSetForCommittedHash(height, reconstructed, targetHash), true
	}
	return nil, false
}

func (n *Node) freezeValidatorSetForHeight(height uint64, hint []string) []string {
	if n == nil || height == 0 {
		return nil
	}

	expectedHash := ""
	if height > 1 && validatorSetCommitmentV2EnabledAt(height-1) {
		if committed, ok := n.chainParentCommittedValidatorSetHash(height); ok {
			expectedHash = strings.TrimSpace(committed)
		}
	}

	if frozen := n.frozenValidatorsForHeight(height); len(frozen) > 0 {
		if expectedHash == "" {
			return frozen
		}
		if matched, ok := n.validatorSetCandidateMatchesTarget(height, expectedHash, frozen, nil); ok {
			return matched
		}
		if repaired, ok := n.repairFrozenValidatorSetForCommittedHash(height, expectedHash, hint, frozen); ok {
			return repaired
		}
		if DebugConsensus && n.shouldLogLivenessReason(fmt.Sprintf("stale_frozen_set:%d", height), livenessReasonLogCooldown) {
			fmt.Printf("[SET-FREEZE-REJECT] height=%d expected=%s stale_size=%d reason=committed_parent_hash_mismatch\n",
				height, ShortHash(expectedHash), len(frozen))
		}
		return nil
	}

	candidate := canonicalValidatorIDs(append([]string{}, hint...))
	genesisCandidate := []string(nil)
	plannedCandidate := false
	if GenesisValidatorSetFrozen {
		if planned := n.plannedValidatorSetForHeightFromChain(height); len(planned) > 0 {
			candidate = planned
			plannedCandidate = true
		} else if height <= 1 || len(candidate) == 0 {
			if genesis := canonicalValidatorIDs(n.GenesisValidators); len(genesis) > 0 {
				candidate = genesis
				genesisCandidate = genesis
			}
		} else if genesis := canonicalValidatorIDs(n.GenesisValidators); len(genesis) > 0 &&
			len(candidate) < len(genesis) &&
			isSubsetValidatorSet(candidate, genesis) {
			candidate = genesis
			genesisCandidate = genesis
		} else if genesis := canonicalValidatorIDs(n.GenesisValidators); len(genesis) > 0 {
			genesisCandidate = genesis
		}
	}
	applyAdaptiveCommittee := activeSetModeAdaptiveCommittee()
	if GenesisValidatorSetFrozen {
		if plannedCandidate ||
			(len(genesisCandidate) > 0 && (sameStringSlice(candidate, genesisCandidate) || len(candidate) > len(genesisCandidate))) {
			applyAdaptiveCommittee = false
		}
	}
	if applyAdaptiveCommittee && len(candidate) > 0 {
		candidate = n.committeeForHeight(height, candidate)
	}
	if len(candidate) == 0 {
		candidate = canonicalValidatorIDs(n.consensusValidatorsForHeight(height))
		if applyAdaptiveCommittee && len(candidate) > 0 {
			candidate = n.committeeForHeight(height, candidate)
		}
	}
	if len(candidate) == 0 {
		// Avoid speculative future committee synthesis when no deterministic
		// validator-set hint exists for this height (typical during catch-up).
		// Returning nil here prevents false local hash expectations that can
		// deadlock sync on validator-set mismatch.
		return nil
	}
	if len(candidate) == 0 {
		return nil
	}

	hash := ""
	if expectedHash != "" {
		if matched, ok := n.validatorSetCandidateMatchesTarget(height, expectedHash, candidate, nil); ok {
			candidate = matched
			hash = expectedHash
		} else if repaired, ok := n.repairFrozenValidatorSetForCommittedHash(height, expectedHash, hint, candidate); ok {
			return repaired
		} else {
			if DebugConsensus && n.shouldLogLivenessReason(fmt.Sprintf("candidate_set_mismatch:%d", height), livenessReasonLogCooldown) {
				fmt.Printf("[SET-FREEZE-REJECT] height=%d expected=%s candidate_size=%d reason=committed_parent_hash_mismatch\n",
					height, ShortHash(expectedHash), len(candidate))
			}
			return nil
		}
	}
	if strings.TrimSpace(hash) == "" {
		hash = n.validatorSetHashFromFinalizedSnapshot(height, candidate)
		if strings.TrimSpace(hash) == "" {
			hash = ValidatorSetHash(candidate)
		}
	}
	n.validatorSetMu.Lock()
	if n.frozenValidatorsByHeight == nil {
		n.frozenValidatorsByHeight = make(map[uint64][]string)
	}
	if n.frozenValidatorHashByHeight == nil {
		n.frozenValidatorHashByHeight = make(map[uint64]string)
	}
	if existing := n.frozenValidatorsByHeight[height]; len(existing) > 0 {
		out := append([]string{}, existing...)
		n.validatorSetMu.Unlock()
		return out
	}
	// Deterministic fast-path:
	// if validator-set hash is unchanged from previous height, carry forward the
	// already-frozen set and avoid re-freeze event/log churn.
	if height > 1 {
		if prevHash, ok := n.frozenValidatorHashByHeight[height-1]; ok && strings.EqualFold(strings.TrimSpace(prevHash), strings.TrimSpace(hash)) {
			carry := n.frozenValidatorsByHeight[height-1]
			if len(carry) == 0 {
				carry = candidate
			}
			n.frozenValidatorsByHeight[height] = append([]string{}, carry...)
			n.frozenValidatorHashByHeight[height] = prevHash
			n.pruneCommitteeStateLocked(height)
			out := append([]string{}, n.frozenValidatorsByHeight[height]...)
			n.validatorSetMu.Unlock()
			return out
		}
	}
	n.frozenValidatorsByHeight[height] = append([]string{}, candidate...)
	n.frozenValidatorHashByHeight[height] = hash
	n.pruneCommitteeStateLocked(height)
	n.validatorSetMu.Unlock()
	n.persistValidatorFreezeEntry(height, candidate, hash)

	if DebugConsensus {
		fmt.Printf("[SET-FREEZE] height=%d vhash=%s size=%d\n", height, ShortHash(hash), len(candidate))
	}
	return candidate
}

func (n *Node) consensusLeaderForHeightRound(height uint64, round uint32, validators []string) string {
	if height == 0 {
		return ""
	}
	base := n.freezeValidatorSetForHeight(height, validators)
	if len(base) == 0 {
		return ""
	}
	// Consensus-critical rule:
	// proposer selection must be a pure function of (height, frozen validator set).
	// Do not use runtime eligibility/pubkey heuristics here, or peers can diverge
	// and trigger "invalid_proposer" loops.
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	leaderHeight := height + uint64(round)
	return LeaderForHeightFromSnapshot(leaderHeight, base, registrySnapshot)
}

func (n *Node) committeeLiveMapForHeight(height uint64) map[string]bool {
	if n == nil || height == 0 {
		return nil
	}
	_ = n.committeeLivenessSnapshot(height)
	n.validatorSetMu.RLock()
	defer n.validatorSetMu.RUnlock()
	if len(n.committeeLiveByHeight) == 0 {
		return nil
	}
	src := n.committeeLiveByHeight[height]
	if len(src) == 0 {
		return nil
	}
	out := make(map[string]bool, len(src))
	for id, live := range src {
		out[id] = live
	}
	return out
}

func (n *Node) consensusReadyValidatorsForHeight(height uint64, validators []string) []string {
	if n == nil || height == 0 {
		return nil
	}
	base := n.freezeValidatorSetForHeight(height, validators)
	if len(base) == 0 {
		return nil
	}
	baseSet := make(map[string]struct{}, len(base))
	for _, id := range base {
		if normID := normalizeValidatorID(id); normID != "" {
			baseSet[normID] = struct{}{}
		}
	}
	localID := normalizeValidatorID(n.ID)
	localReady := false
	if _, inSet := baseSet[localID]; inSet && localID != "" {
		if ready, _ := n.localExecutionBroadcastReady(height); ready {
			localReady = true
		}
	}
	now := time.Now()
	localFinalized := n.getFinalizedHeight()
	ready := make([]string, 0, len(base))
	seen := make(map[string]struct{}, len(base))
	if localReady {
		ready = append(ready, localID)
		seen[localID] = struct{}{}
	}
	n.validatorMu.RLock()
	for _, id := range base {
		normID := normalizeValidatorID(id)
		if normID == "" {
			continue
		}
		if _, ok := seen[normID]; ok {
			continue
		}
		st := n.validatorStatus[normID]
		if !n.isValidatorLiveForConsensusLocked(normID, st, now, localFinalized) {
			continue
		}
		ready = append(ready, normID)
		seen[normID] = struct{}{}
	}
	n.validatorMu.RUnlock()
	return canonicalValidatorIDs(ready)
}

func validatorReadyMap(validators []string) map[string]bool {
	validators = canonicalValidatorIDs(validators)
	if len(validators) == 0 {
		return nil
	}
	out := make(map[string]bool, len(validators))
	for _, id := range validators {
		out[id] = true
	}
	return out
}

// selectLiveLeaderForHeightRound returns the canonical leader for a height and
// round. Local liveness is intentionally ignored here; heartbeat views must not
// change proposal identity or round selection.
func (n *Node) selectLiveLeaderForHeightRound(height uint64, round uint32, validators []string) (string, uint32, int) {
	if n == nil || height == 0 {
		return "", round, 0
	}
	base := n.freezeValidatorSetForHeight(height, validators)
	if len(base) == 0 {
		return "", round, 0
	}
	registrySnapshot := n.validatorRegistrySnapshotForHeight(height)
	canonicalLeader := LeaderForHeightFromSnapshot(height+uint64(round), base, registrySnapshot)
	return canonicalLeader, round, 0
}

func clampProposerRound(round uint32) uint32 {
	maxRound := ProposerRoundMax
	if maxRound == 0 {
		return round
	}
	if round > maxRound {
		return maxRound
	}
	return round
}

func proposerRoundRecoveryCap() uint32 {
	return ProposerRoundMax
}

func effectiveProposerRoundTimeout(roundTimeout time.Duration, minBlockInterval time.Duration, realTick time.Duration) time.Duration {
	if roundTimeout <= 0 {
		roundTimeout = 15 * time.Second
	}
	if ConsensusFastProposerFailoverEnabled {
		minTimeout := ConsensusFastProposerFailoverMin
		if minTimeout <= 0 {
			minTimeout = time.Second
		}
		if realTick > 0 {
			tickFloor := realTick / 2
			if tickFloor <= 0 {
				tickFloor = realTick
			}
			if minTimeout < tickFloor {
				minTimeout = tickFloor
			}
		}
		if roundTimeout < minTimeout {
			roundTimeout = minTimeout
		}
		return roundTimeout
	}
	minTimeout := 2 * time.Second
	if realTick > 0 {
		if candidate := 2 * realTick; candidate > minTimeout {
			minTimeout = candidate
		}
	}
	if minBlockInterval > minTimeout {
		minTimeout = minBlockInterval
	}
	if roundTimeout < minTimeout {
		roundTimeout = minTimeout
	}
	return roundTimeout
}

func effectiveConfiguredProposerRoundTimeout() time.Duration {
	realTick := GlobalConfig.RealTick
	if realTick <= 0 {
		realTick = 2 * time.Second
	}
	return effectiveProposerRoundTimeout(ProposerRoundTimeout, ConsensusMinBlockInterval, realTick)
}

func proposerRoundAdvanceFromAnchor(baseRound uint32, anchor time.Time, now time.Time, roundTimeout time.Duration) uint32 {
	baseRound = clampProposerRound(baseRound)
	if roundTimeout <= 0 || anchor.IsZero() || !now.After(anchor) {
		return baseRound
	}
	elapsed := now.Sub(anchor)
	if elapsed < roundTimeout {
		return baseRound
	}
	advanced := uint64(baseRound) + uint64(elapsed/roundTimeout)
	if advanced > uint64(^uint32(0)) {
		advanced = uint64(^uint32(0))
	}
	return clampProposerRound(uint32(advanced))
}

func computeConsensusRound(now time.Time, epochStartedAt time.Time, observedRound uint32, observedAt time.Time, minBlockInterval time.Duration, roundTimeout time.Duration, realTick time.Duration) uint32 {
	timeout := effectiveProposerRoundTimeout(roundTimeout, minBlockInterval, realTick)
	anchorAt := observedAt
	if !ConsensusFastProposerFailoverEnabled && !epochStartedAt.IsZero() && minBlockInterval > 0 {
		proposalWindowStart := epochStartedAt.Add(minBlockInterval)
		if anchorAt.IsZero() || anchorAt.Before(proposalWindowStart) {
			anchorAt = proposalWindowStart
		}
	}
	if anchorAt.IsZero() {
		if !epochStartedAt.IsZero() {
			anchorAt = epochStartedAt
		} else {
			anchorAt = now
		}
	}
	return proposerRoundAdvanceFromAnchor(observedRound, anchorAt, now, timeout)
}

func consensusRoundAnchorsWithGateHold(epochStartedAt time.Time, observedAt time.Time, gateHeldAt time.Time) (time.Time, time.Time) {
	if gateHeldAt.IsZero() {
		return epochStartedAt, observedAt
	}
	if epochStartedAt.IsZero() || gateHeldAt.After(epochStartedAt) {
		epochStartedAt = gateHeldAt
	}
	if observedAt.IsZero() || gateHeldAt.After(observedAt) {
		observedAt = gateHeldAt
	}
	return epochStartedAt, observedAt
}

func (n *Node) setProposedRound(height uint64, round uint32) {
	if n == nil || height == 0 {
		return
	}
	n.leaderMu.Lock()
	n.setProposedRoundLocked(height, round)
	n.leaderMu.Unlock()
}

func (n *Node) setProposedRoundLocked(height uint64, round uint32) {
	if n == nil || height == 0 {
		return
	}
	round = clampProposerRound(round)
	if n.lastProposedRoundByHeight == nil {
		n.lastProposedRoundByHeight = make(map[uint64]uint32)
	}
	if n.lastProposedRoundAtByHeight == nil {
		n.lastProposedRoundAtByHeight = make(map[uint64]time.Time)
	}
	current := clampProposerRound(n.lastProposedRoundByHeight[height])
	if current > round {
		round = current
	}
	if round > current {
		n.lastProposedRoundAtByHeight[height] = time.Now()
	}
	n.lastProposedRoundByHeight[height] = round
	if len(n.lastProposedRoundByHeight) > 1024 {
		cutoff := height
		if cutoff > 256 {
			cutoff -= 256
		} else {
			cutoff = 0
		}
		for h := range n.lastProposedRoundByHeight {
			if h < cutoff {
				delete(n.lastProposedRoundByHeight, h)
				if n.lastProposedRoundAtByHeight != nil {
					delete(n.lastProposedRoundAtByHeight, h)
				}
			}
		}
	}
}

func (n *Node) proposedRoundForHeight(height uint64) uint32 {
	if n == nil || height == 0 {
		return 0
	}
	n.leaderMu.Lock()
	defer n.leaderMu.Unlock()
	if n.lastProposedRoundByHeight == nil {
		return 0
	}
	return clampProposerRound(n.lastProposedRoundByHeight[height])
}

func (n *Node) proposedRoundAnchorForHeight(height uint64) (uint32, time.Time) {
	if n == nil || height == 0 {
		return 0, time.Time{}
	}
	n.leaderMu.Lock()
	defer n.leaderMu.Unlock()
	if n.lastProposedRoundByHeight == nil {
		return 0, time.Time{}
	}
	round := clampProposerRound(n.lastProposedRoundByHeight[height])
	if n.lastProposedRoundAtByHeight == nil {
		return round, time.Time{}
	}
	return round, n.lastProposedRoundAtByHeight[height]
}

func (n *Node) localProposerRoundForHeight(height uint64) uint32 {
	if n == nil || height == 0 {
		return 0
	}
	round := n.proposedRoundForHeight(height)
	roundTimeout := effectiveProposerRoundTimeout(ProposerRoundTimeout, ConsensusMinBlockInterval, 0)
	if roundTimeout <= 0 {
		return round
	}
	stall := n.commitStallDuration()
	if stall < roundTimeout {
		return round
	}
	stallRound := clampProposerRound(uint32(stall / roundTimeout))
	if stallRound > round {
		return stallRound
	}
	return round
}

func (n *Node) storeLeaderBlock(block Block) bool {
	n.execResultsMu.Lock()
	proposalSeen := n.proposalAlreadySeenLocked(block)
	n.execResultsMu.Unlock()
	if proposalSeen {
		if DebugConsensus {
			fmt.Printf("[EXEC-PROPOSAL-KEEP] height=%d round=%d block=%s reason=proposal_seen\n",
				block.ID,
				block.Round,
				ShortHash(block.BlockHash),
			)
		}
		return true
	}

	lockedBlock, lockedVotes, keepLocked, lockReason := n.quorumLockedProposalHoldStateForIncomingRound(block.ID, block, -1)
	if keepLocked && proposalConflictsWithAcceptedLock(lockedBlock, block) {
		if DebugConsensus {
			fmt.Printf("[ROUND-FAILOVER] rejected held proposal height=%d held_round=%d held_block=%s incoming_round=%d incoming_block=%s votes=%d reason=%s\n",
				block.ID,
				lockedBlock.Round,
				ShortHash(lockedBlock.BlockHash),
				block.Round,
				ShortHash(block.BlockHash),
				lockedVotes,
				lockReason,
			)
		}
		return false
	}
	heldBlock, heldVotes, keepHeld, holdReason := n.acceptedProposalHoldStateForIncomingRound(block.ID, block.Round)
	if keepHeld && proposalConflictsWithAcceptedLock(heldBlock, block) {
		if DebugConsensus {
			fmt.Printf("[ROUND-FAILOVER] rejected held proposal height=%d held_round=%d held_block=%s incoming_round=%d incoming_block=%s votes=%d reason=%s\n",
				block.ID,
				heldBlock.Round,
				ShortHash(heldBlock.BlockHash),
				block.Round,
				ShortHash(block.BlockHash),
				heldVotes,
				holdReason,
			)
		}
		return false
	}
	var replaced bool
	var existing Block
	stored := false
	n.leaderMu.Lock()
	if n.leaderBlocks == nil {
		n.leaderBlocks = make(map[uint64]Block)
	}
	if current, ok := n.leaderBlocks[block.ID]; ok {
		existing = current
		if existing.BlockHash == block.BlockHash {
			if block.Round > existing.Round {
				if _, _, committed := n.proposalHasSignedCommitQuorum(existing); committed {
					if DebugConsensus {
						fmt.Printf("[ROUND-FAILOVER] keeping quorum-locked leader height=%d round=%d incoming_round=%d block=%s\n",
							block.ID, existing.Round, block.Round, ShortHash(block.BlockHash))
					}
					stored = true
					n.leaderMu.Unlock()
					n.noteObservedProposal(block)
					n.onLeaderProposalReplaced(block.ID, existing, block)
					return true
				}
				if DebugConsensus {
					fmt.Printf("[ROUND-FAILOVER] advancing leader round height=%d round=%d->%d block=%s\n",
						block.ID, existing.Round, block.Round, ShortHash(block.BlockHash))
				}
				n.leaderBlocks[block.ID] = block
				n.setProposedRoundLocked(block.ID, block.Round)
				replaced = true
			}
			stored = true
		} else {
			if block.Round > existing.Round {
				if DebugConsensus {
					fmt.Printf("[ROUND-FAILOVER] replacing leader block height=%d round=%d->%d have=%s got=%s\n",
						block.ID, existing.Round, block.Round, ShortHash(existing.BlockHash), ShortHash(block.BlockHash))
				}
				n.leaderBlocks[block.ID] = block
				n.setProposedRoundLocked(block.ID, block.Round)
				replaced = true
				stored = true
			} else if block.Round < existing.Round {
				if DebugConsensus {
					fmt.Printf("[ROUND-FAILOVER] ignored stale round block height=%d round=%d current=%d\n",
						block.ID, block.Round, existing.Round)
				}
				n.leaderMu.Unlock()
				return false
			} else {
				if DebugConsensus {
					fmt.Printf("WARN: conflicting leader block at height %d (have=%s got=%s)\n",
						block.ID,
						ShortHash(existing.BlockHash),
						ShortHash(block.BlockHash),
					)
				}
				n.leaderMu.Unlock()
				return false
			}
		}
	} else {
		n.leaderBlocks[block.ID] = block
		n.setProposedRoundLocked(block.ID, block.Round)
		stored = true
	}
	n.leaderMu.Unlock()

	if !stored {
		return false
	}
	n.noteObservedProposal(block)
	if replaced {
		n.onLeaderProposalReplaced(block.ID, existing, block)
	}
	return true
}

func (n *Node) getLeaderBlock(epoch uint64) (Block, bool) {
	n.leaderMu.Lock()
	defer n.leaderMu.Unlock()
	if n.leaderBlocks == nil {
		return Block{}, false
	}
	block, ok := n.leaderBlocks[epoch]
	return block, ok
}

func (n *Node) clearLeaderBlock(epoch uint64) {
	n.leaderMu.Lock()
	defer n.leaderMu.Unlock()
	if n.leaderBlocks == nil {
		return
	}
	delete(n.leaderBlocks, epoch)
}

func (n *Node) clearLeaderBlockIfBlock(epoch uint64, block Block) bool {
	if n == nil || epoch == 0 || strings.TrimSpace(block.BlockHash) == "" {
		return false
	}
	n.leaderMu.Lock()
	defer n.leaderMu.Unlock()
	if n.leaderBlocks == nil {
		return false
	}
	current, ok := n.leaderBlocks[epoch]
	if !ok || !strings.EqualFold(strings.TrimSpace(current.BlockHash), strings.TrimSpace(block.BlockHash)) {
		return false
	}
	delete(n.leaderBlocks, epoch)
	return true
}

// BuildLeaderBlock creates the leader's proposal for the current epoch.
func (n *Node) BuildLeaderBlock(epoch uint64) Block {
	last := n.Blockchain.LastBlock()
	nextID := last.ID + 1
	if epoch != nextID {
		epoch = nextID
	}

	txs, txMerkle, receipts := n.buildDeterministicExecutionArtifacts(epoch)

	blockType := BlockTypeTime
	if len(txs) > 0 {
		blockType = BlockTypeWork
	}

	validators := n.freezeValidatorSetForHeight(epoch, n.GetConsensusValidators(int(epoch)))
	round := n.proposedRoundForHeight(epoch)
	proposer := n.consensusLeaderForHeightRound(epoch, round, validators)
	if proposer == "" {
		proposer = n.ID
	}
	validatorSetHash := n.validatorSetHashFromFinalizedSnapshot(epoch, validators)
	if strings.TrimSpace(validatorSetHash) == "" {
		validatorSetHash = strings.TrimSpace(ValidatorSetHash(validators))
	}
	expectedHash, expectedHashSource := n.expectedValidatorSetHashWithSource(epoch)
	validatorSetHashSource := "local_deterministic"
	if strings.TrimSpace(expectedHash) != "" {
		validatorSetHash = strings.TrimSpace(expectedHash)
		validatorSetHashSource = expectedHashSource
	}
	block := Block{
		ID:           epoch,
		Type:         blockType,
		Round:        round,
		Transactions: txs,
		Receipts:     receipts,
		PrevHash:     last.BlockHash,
		Proposer:     proposer,
		BlockTime:    LogicalTimeForEpoch(epoch),
	}
	block.Timestamp = int64(SystemTimeUnits(block.BlockTime))
	block.MempoolRoot = txMerkle
	block.ReceiptRoot = ComputeReceiptRoot(receipts)
	block.ValidatorSetHash = validatorSetHash
	if DebugConsensus {
		fmt.Printf("[SET-COMMITMENT-SOURCE] height=%d source=%s hash=%s\n",
			epoch, validatorSetHashSource, ShortHash(validatorSetHash))
	}
	n.fillBlockNextValidatorSetCommitment(&block)
	stateRoot, execCtx, _ := n.executionStateRootForBlock(block)
	block.StateRoot = stateRoot
	block.BlockHash = HashBlock(block)
	n.SignBlock(&block)
	log.Printf("[EXEC-BUILD] kind=leader height=%d round=%d proposer=%s prev=%s tx_count=%d tx_merkle=%s parent_source=%s parent_height=%d parent_hash=%s parent_ledger=%s runtime_ledger=%s execution_ledger=%s root_version=%s state_root=%s block=%s proposal=%s",
		block.ID,
		block.Round,
		ShortID(block.Proposer),
		ShortHash(block.PrevHash),
		len(block.Transactions),
		ShortHash(block.MempoolRoot),
		execCtx.ParentSource,
		execCtx.ParentHeight,
		ShortHash(execCtx.ParentHash),
		ShortHash(execCtx.ParentLedgerHash),
		ShortHash(execCtx.RuntimeLedgerHash),
		ShortHash(execCtx.ExecutionLedgerHash),
		execCtx.RootVersion,
		ShortHash(block.StateRoot),
		ShortHash(block.BlockHash),
		proposalVoteKey(block.ID, block.Round, block.BlockHash, block.MempoolRoot, block.StateRoot),
	)
	return block
}

// BuildFallbackBlock creates a deterministic empty block for an epoch.
// This is used to recover from leader stalls without relying on mempool sync.
func (n *Node) BuildFallbackBlock(epoch uint64) Block {
	last := n.Blockchain.LastBlock()
	nextID := last.ID + 1
	if epoch == 0 || epoch != nextID {
		epoch = nextID
	}

	validators := n.freezeValidatorSetForHeight(epoch, n.GetConsensusValidators(int(epoch)))
	round := n.proposedRoundForHeight(epoch)
	proposer := n.consensusLeaderForHeightRound(epoch, round, validators)
	if proposer == "" {
		proposer = n.ID
	}
	validatorSetHash := n.validatorSetHashFromFinalizedSnapshot(epoch, validators)
	if strings.TrimSpace(validatorSetHash) == "" {
		validatorSetHash = strings.TrimSpace(ValidatorSetHash(validators))
	}
	expectedHash, expectedHashSource := n.expectedValidatorSetHashWithSource(epoch)
	validatorSetHashSource := "local_deterministic"
	if strings.TrimSpace(expectedHash) != "" {
		validatorSetHash = strings.TrimSpace(expectedHash)
		validatorSetHashSource = expectedHashSource
	}

	block := Block{
		ID:        epoch,
		Type:      BlockTypeTime,
		Round:     round,
		PrevHash:  last.BlockHash,
		Proposer:  proposer,
		BlockTime: LogicalTimeForEpoch(epoch),
	}
	block.Timestamp = int64(SystemTimeUnits(block.BlockTime))
	block.MempoolRoot = ""
	block.ReceiptRoot = ""
	block.ValidatorSetHash = validatorSetHash
	if DebugConsensus {
		fmt.Printf("[SET-COMMITMENT-SOURCE] height=%d source=%s hash=%s\n",
			epoch, validatorSetHashSource, ShortHash(validatorSetHash))
	}
	n.fillBlockNextValidatorSetCommitment(&block)
	stateRoot, execCtx, _ := n.executionStateRootForBlock(block)
	block.StateRoot = stateRoot
	block.BlockHash = HashBlock(block)
	n.SignBlock(&block)
	log.Printf("[EXEC-BUILD] kind=fallback height=%d round=%d proposer=%s prev=%s tx_count=%d tx_merkle=%s parent_source=%s parent_height=%d parent_hash=%s parent_ledger=%s runtime_ledger=%s execution_ledger=%s root_version=%s state_root=%s block=%s proposal=%s",
		block.ID,
		block.Round,
		ShortID(block.Proposer),
		ShortHash(block.PrevHash),
		len(block.Transactions),
		ShortHash(block.MempoolRoot),
		execCtx.ParentSource,
		execCtx.ParentHeight,
		ShortHash(execCtx.ParentHash),
		ShortHash(execCtx.ParentLedgerHash),
		ShortHash(execCtx.RuntimeLedgerHash),
		ShortHash(execCtx.ExecutionLedgerHash),
		execCtx.RootVersion,
		ShortHash(block.StateRoot),
		ShortHash(block.BlockHash),
		proposalVoteKey(block.ID, block.Round, block.BlockHash, block.MempoolRoot, block.StateRoot),
	)
	return block
}

func (m *Mempool) Clear() {
	m.mu.Lock()
	defer m.mu.Unlock()

	for _, tx := range m.Transactions {
		if amount := pendingSpendAmount(tx); amount > 0 {
			rollbackPendingSpend(normalizeCoin(tx.Coin), tx.From, amount)
		}
	}

	m.Transactions = nil
	m.txByID = make(map[string]struct{})
	m.txBySenderNonce = make(map[string]string)
	m.pendingCountBySender = make(map[string]int)
	m.nextNonceBySender = make(map[string]int)
}

func ParseSignature(entry string) (addr string, sig []byte, ok bool) {
	parts := strings.Split(entry, ":")
	if len(parts) != 2 {
		return "", nil, false
	}

	addr = parts[0]
	sigHex := parts[1]

	if addr == "" || sigHex == "" {
		return "", nil, false
	}

	sig, err := hex.DecodeString(sigHex)
	if err != nil {
		return "", nil, false
	}

	return addr, sig, true
}

func VerifyBlockSignatures(block Block, validators []string) bool {
	active := len(validators)
	if active < 2 {
		return false
	}

	allowed := make(map[string]bool, active)
	for _, v := range validators {
		allowed[v] = true
	}

	valid := 0
	seen := map[string]bool{}

	for _, entry := range block.Signatures {
		addr, sig, ok := ParseSignature(entry)
		if !ok {
			continue
		}

		if !allowed[addr] {
			continue
		}

		if seen[addr] {
			continue
		}
		seen[addr] = true

		validatorPubKeysMu.RLock()
		pub, ok := ValidatorPubKeys[addr]
		validatorPubKeysMu.RUnlock()
		if !ok || len(pub) != ed25519.PublicKeySize {
			continue
		}

		if ed25519.Verify(pub, []byte(block.BlockHash), sig) {
			valid++
		}
	}

	required := (active*2)/3 + 1
	return valid >= required
}

const seenBlockHashLimit = 50000
const seenTxIDLimit = 200000
const maxQueuedForkBlocksPerHeight = 5

func blockSeenKey(block Block) string {
	hash := strings.TrimSpace(block.BlockHash)
	if hash == "" {
		return ""
	}
	if block.ID == 0 && block.Round == 0 {
		return hash
	}
	return fmt.Sprintf("%d:%d:%s", block.ID, block.Round, hash)
}

func (n *Node) markBlockSeen(hash string) bool {
	if hash == "" {
		return false
	}
	n.seenBlockMu.Lock()
	defer n.seenBlockMu.Unlock()

	if n.SeenBlockHashes == nil {
		n.SeenBlockHashes = make(map[string]bool)
	}
	if n.SeenBlockHashes[hash] {
		return true
	}

	n.SeenBlockHashes[hash] = true
	n.seenBlockQueue = append(n.seenBlockQueue, hash)

	for len(n.seenBlockQueue)-n.seenBlockHead > seenBlockHashLimit {
		old := n.seenBlockQueue[n.seenBlockHead]
		n.seenBlockHead++
		delete(n.SeenBlockHashes, old)
	}

	if n.seenBlockHead > 1024 && n.seenBlockHead*2 > len(n.seenBlockQueue) {
		n.seenBlockQueue = append([]string(nil), n.seenBlockQueue[n.seenBlockHead:]...)
		n.seenBlockHead = 0
	}

	return false
}

func (n *Node) unmarkBlockSeen(hash string) {
	if n == nil || hash == "" {
		return
	}
	n.seenBlockMu.Lock()
	defer n.seenBlockMu.Unlock()
	if n.SeenBlockHashes == nil {
		return
	}
	delete(n.SeenBlockHashes, hash)
}

func (n *Node) hasSeenTx(txID string) bool {
	if txID == "" {
		return false
	}
	n.seenTxMu.Lock()
	defer n.seenTxMu.Unlock()
	if n.SeenTxIDs == nil {
		n.SeenTxIDs = make(map[string]bool)
	}
	return n.SeenTxIDs[txID]
}

func (n *Node) markTxSeen(txID string) {
	if txID == "" {
		return
	}
	n.seenTxMu.Lock()
	defer n.seenTxMu.Unlock()
	if n.SeenTxIDs == nil {
		n.SeenTxIDs = make(map[string]bool)
	}
	if n.SeenTxIDs[txID] {
		return
	}
	n.SeenTxIDs[txID] = true
	n.seenTxQueue = append(n.seenTxQueue, txID)

	for len(n.seenTxQueue)-n.seenTxHead > seenTxIDLimit {
		old := n.seenTxQueue[n.seenTxHead]
		n.seenTxHead++
		delete(n.SeenTxIDs, old)
	}
	if n.seenTxHead > 1024 && n.seenTxHead*2 > len(n.seenTxQueue) {
		n.seenTxQueue = append([]string(nil), n.seenTxQueue[n.seenTxHead:]...)
		n.seenTxHead = 0
	}
}

func snapshotSupportedVersion(v uint32) bool {
	return v == 2 || v == 3 || v == SnapshotVersion
}

func snapshotHasTrustedExecutionLedger(snapshot *StateSnapshot) bool {
	if snapshot == nil {
		return false
	}
	if snapshot.Version < SnapshotVersion {
		return false
	}
	return strings.EqualFold(strings.TrimSpace(snapshot.LedgerStage), snapshotLedgerStageExecution)
}

func snapshotTransitionDigest(m map[string]uint64) string {
	if len(m) == 0 {
		return ""
	}
	normalized := make(map[string]uint64, len(m))
	for id := range m {
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if current, ok := normalized[norm]; !ok || m[id] < current {
			normalized[norm] = m[id]
		}
	}
	keys := make([]string, 0, len(normalized))
	for id := range normalized {
		keys = append(keys, id)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, id := range keys {
		parts = append(parts, fmt.Sprintf("%s=%d", id, normalized[id]))
	}
	return strings.Join(parts, ",")
}

func snapshotValidatorSetHash(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return ""
	}
	hash := strings.TrimSpace(snapshot.ValidatorSetHash)
	if hash != "" {
		return hash
	}
	return ValidatorSetHash(validatorsFromSnapshot(snapshot))
}

func snapshotValidatorSetRoot(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return ""
	}
	root := strings.TrimSpace(snapshot.ValidatorSetRoot)
	if root != "" {
		return root
	}
	validators := validatorsFromSnapshot(snapshot)
	if len(validators) == 0 {
		return ""
	}
	return ValidatorSetMerkleRoot(snapshot.Height, validators, snapshot.ValidatorRegistry)
}

func snapshotNextValidatorSetRoot(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return ""
	}
	root := strings.TrimSpace(snapshot.NextValidatorSetRoot)
	if root != "" {
		return root
	}
	currentHash := strings.TrimSpace(snapshotValidatorSetHash(snapshot))
	nextHash := strings.TrimSpace(snapshot.NextValidatorSetHash)
	if currentHash != "" && nextHash != "" && strings.EqualFold(currentHash, nextHash) {
		return strings.TrimSpace(snapshotValidatorSetRoot(snapshot))
	}
	return ""
}

func snapshotCheckpointSignBytesLegacy(snapshot *StateSnapshot) []byte {
	if snapshot == nil {
		return nil
	}
	setRoot := strings.TrimSpace(snapshotValidatorSetRoot(snapshot))
	if setRoot == "" {
		return []byte(fmt.Sprintf("%s|%d|%s|%s|%s|%s",
			strings.TrimSpace(ChainID),
			snapshot.Height,
			strings.TrimSpace(snapshot.BlockHash),
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshot.LedgerHash),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
		))
	}
	return []byte(fmt.Sprintf("%s|%d|%s|%s|%s|%s|%s",
		strings.TrimSpace(ChainID),
		snapshot.Height,
		strings.TrimSpace(snapshot.BlockHash),
		strings.TrimSpace(snapshot.StateRoot),
		strings.TrimSpace(snapshot.LedgerHash),
		strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
		setRoot,
	))
}

func snapshotCheckpointSignBytesV1(snapshot *StateSnapshot) []byte {
	if snapshot == nil {
		return nil
	}
	checkpointHeight := snapshot.CheckpointHeight
	if checkpointHeight == 0 {
		checkpointHeight = snapshotCheckpointHeightFor(snapshot.Height)
	}
	domain := strings.TrimSpace(snapshot.CheckpointDomain)
	if domain == "" {
		domain = syncSnapshotCheckpointDomain()
	}
	setRoot := strings.TrimSpace(snapshotValidatorSetRoot(snapshot))
	registryHash := strings.TrimSpace(snapshotValidatorRegistryHash(snapshot))
	if setRoot == "" {
		return []byte(fmt.Sprintf("%s|%s|%d|%s|%s|%s",
			domain,
			strings.TrimSpace(ChainID),
			checkpointHeight,
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
			registryHash,
		))
	}
	return []byte(fmt.Sprintf("%s|%s|%d|%s|%s|%s|%s",
		domain,
		strings.TrimSpace(ChainID),
		checkpointHeight,
		strings.TrimSpace(snapshot.StateRoot),
		strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
		registryHash,
		setRoot,
	))
}

func snapshotCheckpointSignBytes(snapshot *StateSnapshot) []byte {
	if snapshot == nil {
		return nil
	}
	if snapshotCheckpointV1EnabledAt(snapshot.Height) {
		return snapshotCheckpointSignBytesV1(snapshot)
	}
	return snapshotCheckpointSignBytesLegacy(snapshot)
}

func snapshotCanonicalPayload(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return ""
	}
	version := snapshot.Version
	if version == 0 {
		version = SnapshotVersion
	}
	setRoot := strings.TrimSpace(snapshotValidatorSetRoot(snapshot))
	nextHash := strings.TrimSpace(snapshot.NextValidatorSetHash)
	nextRoot := strings.TrimSpace(snapshotNextValidatorSetRoot(snapshot))
	nextHeight := snapshotActivationHeight(snapshot)
	// Snapshot trust must be anchored to committed chain state only.
	// Live transition bookkeeping (`ValidatorSetHeight`, pending adds/removes)
	// can differ transiently across otherwise healthy validators and must not
	// split snapshot quorum for an identical committed tip.
	payload := ""
	if nextHash == "" && nextHeight == 0 && setRoot == "" {
		payload = fmt.Sprintf("v=%d|chain=%s|h=%d|bh=%s|sr=%s|lh=%s|vh=%s|ph=%s|gh=%s|cp_h=%d|cp_d=%s",
			version,
			strings.TrimSpace(ChainID),
			snapshot.Height,
			strings.TrimSpace(snapshot.BlockHash),
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshot.LedgerHash),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
			strings.TrimSpace(snapshot.PrevHash),
			strings.TrimSpace(snapshot.GenesisHash),
			snapshot.CheckpointHeight,
			strings.TrimSpace(snapshot.CheckpointDomain),
		)
	} else if nextHash == "" && nextHeight == 0 && nextRoot == "" {
		payload = fmt.Sprintf("v=%d|chain=%s|h=%d|bh=%s|sr=%s|lh=%s|vh=%s|vr=%s|ph=%s|gh=%s|cp_h=%d|cp_d=%s",
			version,
			strings.TrimSpace(ChainID),
			snapshot.Height,
			strings.TrimSpace(snapshot.BlockHash),
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshot.LedgerHash),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
			setRoot,
			strings.TrimSpace(snapshot.PrevHash),
			strings.TrimSpace(snapshot.GenesisHash),
			snapshot.CheckpointHeight,
			strings.TrimSpace(snapshot.CheckpointDomain),
		)
	} else if setRoot == "" && nextRoot == "" {
		payload = fmt.Sprintf("v=%d|chain=%s|h=%d|bh=%s|sr=%s|lh=%s|vh=%s|nsh=%s|nsh_h=%d|ph=%s|gh=%s|cp_h=%d|cp_d=%s",
			version,
			strings.TrimSpace(ChainID),
			snapshot.Height,
			strings.TrimSpace(snapshot.BlockHash),
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshot.LedgerHash),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
			nextHash,
			nextHeight,
			strings.TrimSpace(snapshot.PrevHash),
			strings.TrimSpace(snapshot.GenesisHash),
			snapshot.CheckpointHeight,
			strings.TrimSpace(snapshot.CheckpointDomain),
		)
	} else if setRoot == "" {
		payload = fmt.Sprintf("v=%d|chain=%s|h=%d|bh=%s|sr=%s|lh=%s|vh=%s|nsh=%s|nsh_r=%s|nsh_h=%d|ph=%s|gh=%s|cp_h=%d|cp_d=%s",
			version,
			strings.TrimSpace(ChainID),
			snapshot.Height,
			strings.TrimSpace(snapshot.BlockHash),
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshot.LedgerHash),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
			nextHash,
			nextRoot,
			nextHeight,
			strings.TrimSpace(snapshot.PrevHash),
			strings.TrimSpace(snapshot.GenesisHash),
			snapshot.CheckpointHeight,
			strings.TrimSpace(snapshot.CheckpointDomain),
		)
	} else if nextRoot == "" {
		payload = fmt.Sprintf("v=%d|chain=%s|h=%d|bh=%s|sr=%s|lh=%s|vh=%s|vr=%s|nsh=%s|nsh_h=%d|ph=%s|gh=%s|cp_h=%d|cp_d=%s",
			version,
			strings.TrimSpace(ChainID),
			snapshot.Height,
			strings.TrimSpace(snapshot.BlockHash),
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshot.LedgerHash),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
			setRoot,
			nextHash,
			nextHeight,
			strings.TrimSpace(snapshot.PrevHash),
			strings.TrimSpace(snapshot.GenesisHash),
			snapshot.CheckpointHeight,
			strings.TrimSpace(snapshot.CheckpointDomain),
		)
	} else {
		payload = fmt.Sprintf("v=%d|chain=%s|h=%d|bh=%s|sr=%s|lh=%s|vh=%s|vr=%s|nsh=%s|nsh_r=%s|nsh_h=%d|ph=%s|gh=%s|cp_h=%d|cp_d=%s",
			version,
			strings.TrimSpace(ChainID),
			snapshot.Height,
			strings.TrimSpace(snapshot.BlockHash),
			strings.TrimSpace(snapshot.StateRoot),
			strings.TrimSpace(snapshot.LedgerHash),
			strings.TrimSpace(snapshotValidatorSetHash(snapshot)),
			setRoot,
			nextHash,
			nextRoot,
			nextHeight,
			strings.TrimSpace(snapshot.PrevHash),
			strings.TrimSpace(snapshot.GenesisHash),
			snapshot.CheckpointHeight,
			strings.TrimSpace(snapshot.CheckpointDomain),
		)
	}
	if snapshotCheckpointV1EnabledAt(snapshot.Height) {
		payload = fmt.Sprintf("%s|vrh=%s", payload, strings.TrimSpace(snapshotValidatorRegistryHash(snapshot)))
	}
	if hash := strings.TrimSpace(snapshotPromotionWindowHash(snapshot)); hash != "" {
		payload = fmt.Sprintf("%s|pwh=%s", payload, hash)
	}
	if stage := strings.TrimSpace(snapshot.LedgerStage); stage != "" {
		payload = fmt.Sprintf("%s|ls=%s", payload, stage)
	}
	if snapshot.FinalizedHeight > 0 || strings.TrimSpace(snapshot.EpochAnchorHash) != "" || strings.TrimSpace(snapshot.FinalityRoot) != "" {
		payload = fmt.Sprintf("%s|fe=%d|fh=%d|fhsh=%s|fsr=%s|fvsh=%s|fvsr=%s|ea=%s|pea=%s|fr=%s",
			payload,
			snapshot.FinalizedEpoch,
			snapshot.FinalizedHeight,
			strings.TrimSpace(snapshot.FinalizedHash),
			strings.TrimSpace(snapshot.FinalizedStateRoot),
			strings.TrimSpace(snapshot.FinalizedValidatorSetHash),
			strings.TrimSpace(snapshot.FinalizedValidatorSetRoot),
			strings.TrimSpace(snapshot.EpochAnchorHash),
			strings.TrimSpace(snapshot.PreviousEpochAnchorHash),
			strings.TrimSpace(snapshot.FinalityRoot),
		)
	}
	return payload
}

func snapshotCanonicalHash(snapshot *StateSnapshot) string {
	payload := snapshotCanonicalPayload(snapshot)
	if payload == "" {
		return ""
	}
	sum := sha256.Sum256([]byte(payload))
	return hex.EncodeToString(sum[:])
}

func populateSnapshotDerivedFields(snapshot *StateSnapshot) {
	if snapshot == nil {
		return
	}
	if snapshot.Version == 0 {
		snapshot.Version = SnapshotVersion
	}
	if len(snapshot.StateValidators) == 0 && len(snapshot.ValidatorRegistry) > 0 {
		snapshot.StateValidators = onChainValidatorsFromRegistrySnapshot(snapshot.ValidatorRegistry, snapshot.PendingValidators, snapshot.Height)
	}
	if len(snapshot.ValidatorRegistry) == 0 && len(snapshot.StateValidators) > 0 {
		snapshot.ValidatorRegistry = validatorRegistrySnapshotFromOnChainValidators(snapshot.StateValidators)
	}
	if snapshot.NextValidatorSetHeight == 0 && snapshot.ActivationHeight > 0 {
		snapshot.NextValidatorSetHeight = snapshot.ActivationHeight
	}
	if snapshot.ActivationHeight == 0 && snapshot.NextValidatorSetHeight > 0 {
		snapshot.ActivationHeight = snapshot.NextValidatorSetHeight
	}
	if strings.TrimSpace(snapshot.ValidatorSetHash) == "" {
		snapshot.ValidatorSetHash = snapshotValidatorSetHash(snapshot)
	}
	if strings.TrimSpace(snapshot.ValidatorSetRoot) == "" {
		snapshot.ValidatorSetRoot = snapshotValidatorSetRoot(snapshot)
	}
	if strings.TrimSpace(snapshot.NextValidatorSetRoot) == "" {
		snapshot.NextValidatorSetRoot = snapshotNextValidatorSetRoot(snapshot)
	}
	if strings.TrimSpace(snapshot.ValidatorRegistryHash) == "" {
		snapshot.ValidatorRegistryHash = ValidatorRegistrySnapshotHash(snapshot.ValidatorRegistry)
	}
	if strings.TrimSpace(snapshot.PromotionWindowHash) == "" {
		snapshot.PromotionWindowHash = snapshotPromotionWindowHash(snapshot)
	}
	if strings.TrimSpace(snapshot.StateMerkleRoot) == "" {
		snapshot.StateMerkleRoot = LedgerStateMerkleRoot(snapshot.Ledger)
	}
	if snapshot.CheckpointHeight == 0 {
		snapshot.CheckpointHeight = snapshotCheckpointHeightFor(snapshot.Height)
	}
	if snapshotCheckpointV1EnabledAt(snapshot.Height) && strings.TrimSpace(snapshot.CheckpointDomain) == "" {
		snapshot.CheckpointDomain = syncSnapshotCheckpointDomain()
	}
	if strings.TrimSpace(snapshot.SnapshotHash) == "" {
		snapshot.SnapshotHash = snapshotCanonicalHash(snapshot)
	}
}

func snapshotMetadataRejectReason(snapshot *StateSnapshot) string {
	if snapshot == nil {
		return "snapshot_metadata_invalid"
	}
	if snapshot.Height == 0 || strings.TrimSpace(snapshot.BlockHash) == "" || strings.TrimSpace(snapshot.StateRoot) == "" || strings.TrimSpace(snapshot.LedgerHash) == "" {
		return "snapshot_metadata_invalid"
	}
	if !snapshotSupportedVersion(snapshot.Version) {
		return "snapshot_metadata_invalid"
	}
	if reason := snapshotFinalityMetadataRejectReason(snapshot); reason != "" {
		return reason
	}
	ledgerHash := HashLedger(snapshot.Ledger)
	if ledgerHash != snapshot.LedgerHash {
		return "ledger_hash_mismatch"
	}
	stateMerkleRoot := LedgerStateMerkleRoot(snapshot.Ledger)
	if stateMerkleRoot == "" {
		return "snapshot_metadata_invalid"
	}
	if providedStateMerkle := strings.TrimSpace(snapshot.StateMerkleRoot); providedStateMerkle != "" &&
		!strings.EqualFold(providedStateMerkle, stateMerkleRoot) {
		return "state_merkle_root_mismatch"
	}
	if GenesisHash != "" && snapshot.GenesisHash != "" && snapshot.GenesisHash != GenesisHash {
		return "genesis_hash_mismatch"
	}
	if strings.TrimSpace(snapshotValidatorSetHash(snapshot)) == "" {
		return "snapshot_metadata_invalid"
	}
	if root := strings.TrimSpace(snapshot.ValidatorSetRoot); root != "" {
		expectedRoot := ValidatorSetMerkleRoot(snapshot.Height, validatorsFromSnapshot(snapshot), snapshot.ValidatorRegistry)
		if expectedRoot != "" && !strings.EqualFold(root, expectedRoot) {
			return "validator_set_root_mismatch"
		}
	}
	if nextRoot := strings.TrimSpace(snapshot.NextValidatorSetRoot); nextRoot != "" {
		currentHash := strings.TrimSpace(snapshotValidatorSetHash(snapshot))
		nextHash := strings.TrimSpace(snapshot.NextValidatorSetHash)
		if currentHash != "" && nextHash != "" && strings.EqualFold(currentHash, nextHash) {
			currentRoot := strings.TrimSpace(snapshotValidatorSetRoot(snapshot))
			if currentRoot != "" && !strings.EqualFold(nextRoot, currentRoot) {
				return "next_validator_set_root_mismatch"
			}
		}
	}
	if hash := strings.TrimSpace(snapshot.ValidatorRegistryHash); hash != "" {
		if !strings.EqualFold(hash, ValidatorRegistrySnapshotHash(snapshot.ValidatorRegistry)) {
			return "registry_hash_mismatch"
		}
	}
	if hash := strings.TrimSpace(snapshot.PromotionWindowHash); hash != "" {
		if !strings.EqualFold(hash, computedSnapshotPromotionWindowHash(snapshot)) {
			return "promotion_window_hash_mismatch"
		}
	}
	if snapshot.NextValidatorSetHeight > 0 &&
		snapshot.ActivationHeight > 0 &&
		snapshot.NextValidatorSetHeight != snapshot.ActivationHeight {
		return "next_validator_set_height_mismatch"
	}
	checkpointHeight := snapshot.CheckpointHeight
	if checkpointHeight == 0 {
		checkpointHeight = snapshotCheckpointHeightFor(snapshot.Height)
	}
	if checkpointHeight > snapshot.Height {
		return "snapshot_metadata_invalid"
	}
	if snapshotCheckpointV1EnabledAt(snapshot.Height) {
		if !strings.EqualFold(strings.TrimSpace(snapshot.CheckpointDomain), syncSnapshotCheckpointDomain()) {
			return "snapshot_checkpoint_domain_mismatch"
		}
	}
	if hash := strings.TrimSpace(snapshot.SnapshotHash); hash != "" {
		if !strings.EqualFold(hash, snapshotCanonicalHash(snapshot)) {
			return "snapshot_hash_mismatch"
		}
	}
	return ""
}

func snapshotHasValidMetadata(snapshot *StateSnapshot) bool {
	return snapshotMetadataRejectReason(snapshot) == ""
}

func (n *Node) attachSnapshotCheckpointProof(snapshot *StateSnapshot) {
	if n == nil || snapshot == nil {
		return
	}
	if !isValidatorSigningKeyUsable(n.ValidatorKey) {
		return
	}
	signer := normalizeValidatorID(n.ID)
	if signer == "" {
		signer = normalizeValidatorID(n.ValidatorKey.ID)
	}
	if signer == "" {
		return
	}
	if snapshot.CheckpointHeight == 0 {
		snapshot.CheckpointHeight = snapshotCheckpointHeightFor(snapshot.Height)
	}
	if snapshotCheckpointV1EnabledAt(snapshot.Height) {
		snapshot.CheckpointDomain = syncSnapshotCheckpointDomain()
	}
	sig, ok := n.signValidatorPayload(snapshotCheckpointSignBytes(snapshot))
	if !ok {
		return
	}
	if len(sig) == 0 {
		return
	}
	if snapshot.CheckpointProof == nil {
		snapshot.CheckpointProof = make(map[string]string)
	}
	snapshot.CheckpointProof[signer] = hex.EncodeToString(sig)
}

func (n *Node) verifySnapshotCheckpointProofForValidator(snapshot *StateSnapshot, validatorID string) bool {
	if snapshot == nil {
		return false
	}
	if !n.snapshotCheckpointProofRequired() {
		return true
	}
	norm := normalizeValidatorID(validatorID)
	if norm == "" {
		return false
	}
	if len(snapshot.CheckpointProof) == 0 {
		return false
	}
	sigHex := strings.TrimSpace(snapshot.CheckpointProof[norm])
	if sigHex == "" {
		for key, value := range snapshot.CheckpointProof {
			if normalizeValidatorID(key) == norm {
				sigHex = strings.TrimSpace(value)
				break
			}
		}
	}
	if sigHex == "" {
		return false
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != ed25519.SignatureSize {
		return false
	}
	v1Required := snapshotCheckpointV1EnabledAt(snapshot.Height)
	if v1Required {
		if snapshot.CheckpointHeight == 0 || !strings.EqualFold(strings.TrimSpace(snapshot.CheckpointDomain), syncSnapshotCheckpointDomain()) {
			return false
		}
	}
	signBytesV1 := snapshotCheckpointSignBytesV1(snapshot)
	signBytesLegacy := snapshotCheckpointSignBytesLegacy(snapshot)
	for _, pub := range execResultPubKeyCandidates(norm) {
		if ed25519.Verify(pub, signBytesV1, sig) {
			return true
		}
		if !v1Required && ed25519.Verify(pub, signBytesLegacy, sig) {
			return true
		}
	}
	return false
}

func (n *Node) snapshotCheckpointProofCandidateIDs(snapshot *StateSnapshot) []string {
	if snapshot == nil || len(snapshot.CheckpointProof) == 0 {
		return nil
	}
	ids := make([]string, 0, len(snapshot.CheckpointProof))
	seen := make(map[string]struct{}, len(snapshot.CheckpointProof))
	for id := range snapshot.CheckpointProof {
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if _, ok := seen[norm]; ok {
			continue
		}
		seen[norm] = struct{}{}
		ids = append(ids, norm)
	}
	sort.Strings(ids)
	return ids
}

func (n *Node) verifySnapshotCheckpointProofBatch(snapshot *StateSnapshot, validatorIDs []string, required int) int {
	if snapshot == nil {
		return 0
	}
	if !n.snapshotCheckpointProofRequired() {
		if required > 0 {
			return required
		}
		return len(validatorIDs)
	}
	if required <= 0 {
		required = 1
	}
	if len(validatorIDs) == 0 {
		validatorIDs = n.snapshotCheckpointProofCandidateIDs(snapshot)
	}
	if len(validatorIDs) == 0 {
		return 0
	}
	unique := make([]string, 0, len(validatorIDs))
	seen := make(map[string]struct{}, len(validatorIDs))
	for _, id := range validatorIDs {
		norm := normalizeValidatorID(id)
		if norm == "" {
			continue
		}
		if _, ok := seen[norm]; ok {
			continue
		}
		seen[norm] = struct{}{}
		unique = append(unique, norm)
	}
	if len(unique) == 0 {
		return 0
	}
	workers := syncEd25519BatchVerifyWorkers()
	if workers > len(unique) {
		workers = len(unique)
	}
	if workers <= 0 {
		workers = 1
	}
	jobs := make(chan string, len(unique))
	results := make(chan bool, len(unique))
	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for id := range jobs {
				results <- n.verifySnapshotCheckpointProofForValidator(snapshot, id)
			}
		}()
	}
	for _, id := range unique {
		jobs <- id
	}
	close(jobs)
	wg.Wait()
	close(results)
	valid := 0
	for ok := range results {
		if ok {
			valid++
		}
	}
	return valid
}

func (n *Node) verifySnapshotCheckpointProofPolicy(snapshot *StateSnapshot) (int, int, bool) {
	if snapshot == nil {
		return 0, 0, false
	}
	if !n.snapshotCheckpointProofRequired() {
		return 0, 0, true
	}
	candidates := n.snapshotCheckpointProofCandidateIDs(snapshot)
	if len(candidates) == 0 {
		return 0, 1, false
	}
	required := 1
	ids := candidates
	authorityIDs := n.validatorAuthorityIDsForQuorum(snapshot.Height)
	if quorum := execQuorumRequired(len(authorityIDs)); quorum > 0 && len(candidates) >= quorum {
		required = quorum
		ids = authorityIDs
	}
	valid := n.verifySnapshotCheckpointProofBatch(snapshot, ids, required)
	return valid, required, valid >= required
}

func snapshotTrustKey(snapshot *StateSnapshot) string {
	if !snapshotHasValidMetadata(snapshot) {
		return ""
	}
	return fmt.Sprintf("%d:%s:%s:%s", snapshot.Height, snapshot.BlockHash, snapshot.StateRoot, snapshot.LedgerHash)
}

func (n *Node) recordSnapshotVote(validatorID string, snapshot *StateSnapshot) (int, string) {
	if validatorID == "" || snapshot == nil {
		return 0, ""
	}
	key := snapshotTrustKey(snapshot)
	if key == "" {
		return 0, ""
	}
	n.snapshotTrustMu.Lock()
	defer n.snapshotTrustMu.Unlock()
	if n.snapshotVotes == nil {
		n.snapshotVotes = make(map[string]map[string]struct{})
	}
	if n.snapshotCache == nil {
		n.snapshotCache = make(map[string]*StateSnapshot)
	}
	if n.snapshotVotes[key] == nil {
		n.snapshotVotes[key] = make(map[string]struct{})
	}
	n.snapshotVotes[key][validatorID] = struct{}{}
	if _, ok := n.snapshotCache[key]; !ok {
		n.snapshotCache[key] = snapshot
	}
	return len(n.snapshotVotes[key]), key
}

func (n *Node) getSnapshotByKey(key string) *StateSnapshot {
	if key == "" {
		return nil
	}
	n.snapshotTrustMu.Lock()
	defer n.snapshotTrustMu.Unlock()
	if n.snapshotCache == nil {
		return nil
	}
	return n.snapshotCache[key]
}

func (n *Node) majorityHeartbeatHeight() (uint64, int, int, bool) {
	nextHeight := n.Blockchain.Height() + 1
	active := 0
	if validators, _, ok := n.authoritativeHeartbeatValidatorSetForHeight(nextHeight); ok {
		active = len(validators)
	}
	if active == 0 {
		return 0, 0, 0, false
	}
	required := execQuorumRequired(active)
	if required == 0 {
		return 0, 0, 0, false
	}

	now := time.Now()
	const statusTTL = 2 * time.Minute
	heights := make([]uint64, 0, active)
	n.validatorMu.RLock()
	for id, st := range n.validatorStatus {
		if st == nil {
			continue
		}
		if now.Sub(st.LastSeen) > statusTTL {
			continue
		}
		if !n.validatorInAnyHeartbeatSet(id, st.ReportedHeight, st.FinalizedHeight, st.ExecEpoch, st.ValidatorSetHeight) {
			continue
		}
		h := st.FinalizedHeight
		if h == 0 {
			h = st.ReportedHeight
		}
		if h > 0 {
			heights = append(heights, h)
		}
	}
	n.validatorMu.RUnlock()
	if len(heights) < required {
		return 0, len(heights), required, false
	}

	// Pick the highest height that has quorum support (>= required validators at or above it).
	sort.Slice(heights, func(i, j int) bool { return heights[i] < heights[j] })
	quorumHeight := heights[len(heights)-required]
	if quorumHeight == 0 {
		return 0, len(heights), required, false
	}

	votes := 0
	for _, h := range heights {
		if h >= quorumHeight {
			votes++
		}
	}
	return quorumHeight, votes, required, true
}

func (n *Node) startupRemoteHeartbeatHeight() (uint64, int, int, bool) {
	if n == nil || n.Blockchain == nil {
		return 0, 0, 0, false
	}
	nextHeight := n.Blockchain.Height() + 1
	active := 0
	if validators, _, ok := n.authoritativeHeartbeatValidatorSetForHeight(nextHeight); ok {
		active = len(validators)
	}
	if active == 0 {
		return 0, 0, 0, false
	}
	required := execQuorumRequired(active)
	if required == 0 {
		return 0, 0, 0, false
	}

	now := time.Now()
	const statusTTL = 2 * time.Minute
	selfID := normalizeValidatorID(n.ID)
	heights := make([]uint64, 0, active)
	n.validatorMu.RLock()
	for id, st := range n.validatorStatus {
		if st == nil {
			continue
		}
		if normalizeValidatorID(id) == selfID {
			continue
		}
		if now.Sub(st.LastSeen) > statusTTL {
			continue
		}
		if !n.validatorInAnyHeartbeatSet(id, st.ReportedHeight, st.FinalizedHeight, st.ExecEpoch, st.ValidatorSetHeight) {
			continue
		}
		h := st.FinalizedHeight
		if h == 0 {
			h = st.ReportedHeight
		}
		if h > 0 {
			heights = append(heights, h)
		}
	}
	n.validatorMu.RUnlock()
	if len(heights) < required {
		return 0, len(heights), required, false
	}

	sort.Slice(heights, func(i, j int) bool { return heights[i] < heights[j] })
	quorumHeight := heights[len(heights)-required]
	if quorumHeight == 0 {
		return 0, len(heights), required, false
	}

	votes := 0
	for _, h := range heights {
		if h >= quorumHeight {
			votes++
		}
	}
	return quorumHeight, votes, required, true
}

func (n *Node) bestObservedSyncHeight() (uint64, int) {
	now := time.Now()
	const statusTTL = 2 * time.Minute

	type validatorHeight struct {
		id   string
		h    uint64
		seen time.Time
	}

	snap := make([]validatorHeight, 0)
	n.validatorMu.RLock()
	for id, st := range n.validatorStatus {
		if st == nil {
			continue
		}
		h := st.FinalizedHeight
		if h == 0 {
			h = st.ReportedHeight
		}
		snap = append(snap, validatorHeight{
			id:   id,
			h:    h,
			seen: st.LastSeen,
		})
	}
	n.validatorMu.RUnlock()

	best := uint64(0)
	votes := 0
	for _, v := range snap {
		if v.id == n.ID || v.h == 0 {
			continue
		}
		if now.Sub(v.seen) > statusTTL {
			continue
		}
		if !n.isValidatorInSet(v.id) {
			continue
		}
		if v.h > best {
			best = v.h
			votes = 1
		} else if v.h == best {
			votes++
		}
	}

	ackBest := uint64(0)
	ackVotes := 0
	n.peerStateMu.Lock()
	for _, h := range n.peerAckHeight {
		if h == 0 {
			continue
		}
		if h > ackBest {
			ackBest = h
			ackVotes = 1
		} else if h == ackBest {
			ackVotes++
		}
	}
	n.peerStateMu.Unlock()

	if ackBest > best {
		return ackBest, ackVotes
	}
	return best, votes
}

func (n *Node) startupRemoteObservedSyncHeight() (uint64, int) {
	if n == nil {
		return 0, 0
	}
	now := time.Now()
	const statusTTL = 2 * time.Minute
	selfID := normalizeValidatorID(n.ID)

	type validatorHeight struct {
		id   string
		h    uint64
		seen time.Time
	}

	snap := make([]validatorHeight, 0)
	n.validatorMu.RLock()
	for id, st := range n.validatorStatus {
		if st == nil {
			continue
		}
		if normalizeValidatorID(id) == selfID {
			continue
		}
		h := st.FinalizedHeight
		if h == 0 {
			h = st.ReportedHeight
		}
		snap = append(snap, validatorHeight{
			id:   id,
			h:    h,
			seen: st.LastSeen,
		})
	}
	n.validatorMu.RUnlock()

	best := uint64(0)
	votes := 0
	for _, v := range snap {
		if v.h == 0 {
			continue
		}
		if now.Sub(v.seen) > statusTTL {
			continue
		}
		if !n.isValidatorInSet(v.id) {
			continue
		}
		if v.h > best {
			best = v.h
			votes = 1
		} else if v.h == best {
			votes++
		}
	}

	ackBest := uint64(0)
	ackVotes := 0
	n.peerStateMu.Lock()
	for peerID, h := range n.peerAckHeight {
		if h == 0 {
			continue
		}
		if !n.peerHelloOK[peerID] {
			continue
		}
		if normalizeNodeRole(n.peerRole[peerID]) != "validator" {
			continue
		}
		if strings.TrimSpace(n.peerToValidator[peerID]) == "" {
			continue
		}
		if h > ackBest {
			ackBest = h
			ackVotes = 1
		} else if h == ackBest {
			ackVotes++
		}
	}
	n.peerStateMu.Unlock()

	if ackBest > best {
		return ackBest, ackVotes
	}
	return best, votes
}

func syncNearTipGraceBlocks() uint64 {
	// Consensus re-entry must be tighter than the liveness drift window.
	// A validator that rejoins while several blocks behind can keep signing an
	// old height and never fully catch up under pressure. Keep only a one-block
	// near-tip bypass; block-range sync handles anything larger.
	return 1
}

func nearSyncTip(localHeight, targetHeight uint64) bool {
	if targetHeight == 0 || targetHeight <= localHeight {
		return true
	}
	return (targetHeight - localHeight) <= syncNearTipGraceBlocks()
}

func snapshotSessionActiveForHeight(session SnapshotSession, localHeight uint64) bool {
	return session.Active &&
		normalizeSnapshotSyncStage(session.Stage) != SnapshotSyncStageSyncComplete &&
		(session.FreezeHeight == 0 || localHeight < session.FreezeHeight)
}

func statusNearTipSyncCompleteAllowed(localHeight, targetHeight uint64, snapshotActive bool) bool {
	return statusNearTipSyncCompleteAllowedForRole(localHeight, targetHeight, snapshotActive, "validator")
}

func statusNearTipSyncCompleteAllowedForRole(localHeight, targetHeight uint64, snapshotActive bool, role string) bool {
	if snapshotActive || targetHeight <= localHeight {
		return false
	}
	role = normalizeNodeRole(role)
	lag := targetHeight - localHeight
	grace := syncNearTipGraceBlocks()
	if role == "validator" {
		return false
	}
	if role == "full" || role == "light" {
		grace = validatorLivenessMaxHeightDriftBlocks()
		if grace < syncNearTipGraceBlocks() {
			grace = syncNearTipGraceBlocks()
		}
		return lag <= grace
	}
	return consensusStarted.Load() && lag <= grace
}

func (n *Node) consensusSyncReferenceHeight() uint64 {
	if n == nil {
		return 0
	}
	if finalized := n.getFinalizedHeight(); finalized > 0 {
		return finalized
	}
	if n.Blockchain != nil {
		return n.Blockchain.Height()
	}
	return 0
}

// effectiveConsensusSyncState returns the sync gate state that consensus paths
// should honor. A stale raw Syncing bit must not keep blocking proposal/vote
// flow once the node is already at, or within the near-tip grace of, its best
// known target and there is no active snapshot session.
func (n *Node) effectiveConsensusSyncState(localHeight uint64) (syncing bool, paused bool, target uint64) {
	if n == nil {
		return false, false, 0
	}
	if localHeight == 0 {
		localHeight = n.consensusSyncReferenceHeight()
	}
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		syncing = n.Consensus.Syncing
		paused = n.Consensus.Paused
		target = n.Consensus.SyncTarget
		n.Consensus.mu.Unlock()
	}
	snapshotSession := n.snapshotSessionSnapshot()
	if snapshotSession.Active {
		syncing = true
		if snapshotSession.FreezeHeight > target {
			target = snapshotSession.FreezeHeight
		}
	}
	if n.Host != nil && len(n.Host.Network().Peers()) > 0 {
		quorumHeight, _, quorumRequired, quorumOK := n.majorityHeartbeatHeight()
		observedHeight, observedVotes := n.bestObservedSyncHeight()
		if candidate := selectSyncTargetHeight(localHeight, quorumHeight, quorumOK, observedHeight, observedVotes, quorumRequired); candidate > target {
			target = candidate
		}
	}
	if syncing && !snapshotSession.Active && nearSyncTip(localHeight, target) {
		syncing = false
	}
	return syncing, paused, target
}

func (n *Node) consensusNearTipSyncBypassAllowed(height, localHeight, target uint64) bool {
	if n == nil {
		return false
	}
	if session := n.snapshotSessionSnapshot(); session.Active {
		sessionTarget := session.FreezeHeight
		if session.CandidateHeight > sessionTarget {
			sessionTarget = session.CandidateHeight
		}
		if sessionTarget > localHeight {
			return false
		}
		if height > 0 && localHeight+1 < height {
			return false
		}
		return true
	}
	if target == 0 || !nearSyncTip(localHeight, target) {
		return false
	}
	if height == 0 {
		return true
	}
	return height <= localHeight+1
}

func (n *Node) consensusSyncGateForHeight(height uint64) (blocked bool, reason string, target uint64) {
	if n == nil {
		return false, "", 0
	}
	localHeight := n.consensusSyncReferenceHeight()
	rawSyncInFlight := false
	rawSyncing := false
	rawPaused := false
	rawTarget := uint64(0)
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		rawSyncInFlight = n.Consensus.syncInFlight
		rawSyncing = n.Consensus.Syncing
		rawPaused = n.Consensus.Paused
		rawTarget = n.Consensus.SyncTarget
		n.Consensus.mu.Unlock()
	}
	syncing, paused, target := n.effectiveConsensusSyncState(localHeight)
	if rawTarget > target {
		target = rawTarget
	}
	active := rawSyncInFlight || rawSyncing || rawPaused || syncing || paused
	if !active {
		return false, "", target
	}
	syncModePause := rawSyncInFlight || rawSyncing || syncing || target > 0
	if syncModePause && n.consensusNearTipSyncBypassAllowed(height, localHeight, target) {
		return false, "", target
	}
	if rawPaused || paused {
		if syncModePause {
			return true, "syncing", target
		}
		return true, "consensus_paused", target
	}
	return true, "syncing", target
}

