func applyFullNodeSafeSyncProfile(role string) {
	role = normalizeNodeRole(role)
	if role != "full" && role != "light" {
		return
	}
	changes := []string{}
	ensureUint64 := func(name string, ptr *uint64, value uint64) {
		if ptr == nil || *ptr >= value {
			return
		}
		old := *ptr
		*ptr = value
		changes = append(changes, fmt.Sprintf("%s=%d->%d", name, old, value))
	}
	ensureIntAtLeast := func(name string, ptr *int, value int) {
		if ptr == nil || *ptr >= value {
			return
		}
		old := *ptr
		*ptr = value
		changes = append(changes, fmt.Sprintf("%s=%d->%d", name, old, value))
	}
	capInt := func(name string, ptr *int, value int) {
		if ptr == nil || *ptr <= 0 || *ptr <= value {
			return
		}
		old := *ptr
		*ptr = value
		changes = append(changes, fmt.Sprintf("%s=%d->%d", name, old, value))
	}
	ensureUint64("direct_gossip_max_blocks", &SyncDirectGossipMaxBlocks, 512)
	ensureUint64("fast_block_sync_max_blocks", &SyncFastBlockSyncMaxBlocks, 1024)
	ensureUint64("restart_snapshot_grace_blocks", &SyncRestartSnapshotGraceBlocks, 512)
	ensureUint64("snapshot_threshold_blocks", &SyncSnapshotCatchupThresholdBlocks, 4096)
	ensureUint64("delta_replay_batch_blocks", &SyncDeltaReplayBatchBlocks, 2048)
	ensureUint64("sync_peer_timeout_seconds", &SyncPeerTimeoutSeconds, 20)
	ensureIntAtLeast("delta_replay_verify_workers", &SyncDeltaReplayVerifyWorkers, 4)
	capInt("delta_replay_verify_workers", &SyncDeltaReplayVerifyWorkers, 4)
	capInt("snapshot_parallel_chunks", &SyncSnapshotParallelChunks, 4)
	if SyncSnapshotParallelChunks <= 0 {
		old := SyncSnapshotParallelChunks
		SyncSnapshotParallelChunks = 4
		changes = append(changes, fmt.Sprintf("snapshot_parallel_chunks=%d->%d", old, SyncSnapshotParallelChunks))
	}
	if len(changes) > 0 {
		log.Printf("[SYNC-PROFILE] role=%s profile=safe_full_node changes=%s", role, strings.Join(changes, ","))
	}
}

func deltaReplayVerifyWorkerCount(batchSize int) int {
	if batchSize <= 0 {
		return 1
	}
	workers := syncDeltaReplayVerifyWorkers()
	if workers > 16 {
		workers = 16
	}
	if workers < 1 {
		workers = 1
	}
	if workers > batchSize {
		workers = batchSize
	}
	return workers
}

func missingBlockRecoveryCooldown() time.Duration {
	return 1500 * time.Millisecond
}

func shouldStartMissingBlockRecovery(now, lastAt time.Time, inFlight bool, lastHeight, missingHeight uint64) bool {
	if missingHeight == 0 {
		return false
	}
	if inFlight && lastHeight == missingHeight {
		return false
	}
	if lastHeight == missingHeight && !lastAt.IsZero() && now.Sub(lastAt) < missingBlockRecoveryCooldown() {
		return false
	}
	return true
}

func syncCatchupStage(localHeight, targetHeight uint64) string {
	lag := syncLagBlocks(localHeight, targetHeight)
	if lag == 0 {
		return "idle"
	}
	if lag <= syncDirectGossipMaxBlocks() {
		return "direct_gossip"
	}
	if stageMax := syncRangeFetchStageMaxBlocks(); stageMax > 0 && lag <= stageMax {
		return "range_fetch"
	}
	if !syncDeltaStateSyncEnabled() {
		return "state_bootstrap"
	}
	if lag < syncSnapshotCatchupThresholdBlocks() {
		return "delta_replay"
	}
	if lag <= syncSnapshotDeltaMaxBlocks() {
		return "snapshot_delta"
	}
	return "state_bootstrap"
}

type syncCatchupPlan struct {
	Stage                  string
	Mode                   string
	Action                 string
	Lag                    uint64
	BatchMax               uint64
	BlockRange             bool
	DeltaReplay            bool
	Snapshot               bool
	StateBootstrap         bool
	UsableHead             bool
	HeadStage              string
	RequireCheckpointProof bool
	BackgroundHistory      bool
	RecentReplayWindow     uint64
	TargetSeconds          uint64
}

func normalizeUsableHeadRole(role string) string {
	role = strings.ToLower(strings.TrimSpace(role))
	switch role {
	case "archive", "archive_node", "archive-full", "archive_full":
		return "archive"
	default:
		return normalizeNodeRole(role)
	}
}

func syncUsableHeadRoleAllowed(role string, archiveMode bool) bool {
	if archiveMode {
		role = "archive"
	}
	role = normalizeUsableHeadRole(role)
	for _, allowed := range SyncUsableHeadRoles {
		if normalizeUsableHeadRole(allowed) == role {
			return true
		}
	}
	return false
}

func syncUsableHeadMinGapBlocks() uint64 {
	if SyncUsableHeadMinGapBlocks == 0 {
		return syncSnapshotCatchupThresholdBlocks()
	}
	return SyncUsableHeadMinGapBlocks
}

func syncUsableHeadTargetSeconds() uint64 {
	if SyncUsableHeadTargetSeconds == 0 {
		return 3
	}
	return SyncUsableHeadTargetSeconds
}

func syncUsableHeadRecentReplayWindowBlocks() uint64 {
	if SyncUsableHeadRecentReplayWindowBlocks == 0 {
		return 2048
	}
	return SyncUsableHeadRecentReplayWindowBlocks
}

func syncPlanAllowsUsableHead(stage string, lag uint64, role string, archiveMode bool) bool {
	return SyncUsableHeadFastBootstrapEnabled &&
		normalizeSyncStage(stage) == "state_bootstrap" &&
		lag >= syncUsableHeadMinGapBlocks() &&
		syncUsableHeadRoleAllowed(role, archiveMode)
}

func syncStageStatusAction(stage string) string {
	stage = normalizeSyncStage(stage)
	if action := syncSnapshotStageAction(stage); action != "" {
		return action
	}
	switch stage {
	case "direct_gossip":
		return "direct_gossip"
	case "range_fetch":
		return "range_fetch"
	case "idle":
		return "up_to_date"
	default:
		return ""
	}
}

func syncBatchMaxForStage(stage string) uint64 {
	switch normalizeSyncStage(stage) {
	case "direct_gossip":
		return syncDirectGossipMaxBlocks()
	case "range_fetch":
		return syncRangeFetchMaxBlocks()
	case "delta_replay":
		return syncDeltaReplayBatchBlocks()
	default:
		return 0
	}
}

func syncCatchupPlanForStage(stage string, localHeight, targetHeight uint64) syncCatchupPlan {
	stage = normalizeSyncStage(stage)
	if stage == "" {
		stage = syncCatchupStage(localHeight, targetHeight)
	}
	lag := syncLagBlocks(localHeight, targetHeight)
	plan := syncCatchupPlan{
		Stage:    stage,
		Mode:     syncModeForStage(stage),
		Action:   syncStageStatusAction(stage),
		Lag:      lag,
		BatchMax: syncBatchMaxForStage(stage),
	}
	switch stage {
	case "direct_gossip", "range_fetch":
		plan.BlockRange = true
	case "delta_replay":
		plan.DeltaReplay = true
	case "snapshot_delta":
		plan.Snapshot = true
	case "state_bootstrap":
		plan.Snapshot = true
		plan.StateBootstrap = true
	}
	return plan
}

func syncCatchupPlanForLag(localHeight, targetHeight uint64) syncCatchupPlan {
	return syncCatchupPlanForStage(syncCatchupStage(localHeight, targetHeight), localHeight, targetHeight)
}

func syncCatchupPlanForRole(localHeight, targetHeight uint64, role string, archiveMode bool) syncCatchupPlan {
	plan := syncCatchupPlanForLag(localHeight, targetHeight)
	if syncPlanAllowsUsableHead(plan.Stage, plan.Lag, role, archiveMode) {
		plan.UsableHead = true
		plan.HeadStage = "checkpoint_verify"
		plan.RequireCheckpointProof = SyncUsableHeadRequireCheckpointProof
		plan.BackgroundHistory = SyncUsableHeadBackgroundHistory
		plan.RecentReplayWindow = syncUsableHeadRecentReplayWindowBlocks()
		plan.TargetSeconds = syncUsableHeadTargetSeconds()
	}
	return plan
}

func syncModeForStage(stage string) string {
	switch normalizeSyncStage(stage) {
	case "realtime_gossip":
		return "gossip"
	case "direct_gossip", "range_fetch", "delta_replay":
		return "blocks"
	case "snapshot_delta":
		return "snapshot"
	case "state_bootstrap":
		return "warp"
	case "idle":
		return "idle"
	default:
		return ""
	}
}

func syncModeMetricCode(stage string, mode string) int {
	switch normalizeSyncStage(stage) {
	case "realtime_gossip", "direct_gossip", "idle":
		return 0
	case "range_fetch":
		return 1
	case "delta_replay":
		return 2
	case "snapshot_delta", "state_bootstrap":
		return 3
	}
	switch normalizeSyncMode(mode) {
	case "gossip", "idle":
		return 0
	case "blocks":
		return 1
	case "snapshot", "warp":
		return 3
	default:
		return 0
	}
}

func syncCatchupMode(localHeight, targetHeight uint64) string {
	return syncModeForStage(syncCatchupStage(localHeight, targetHeight))
}

func syncStageUsesSnapshotTransfer(stage string) bool {
	return stage == "snapshot_delta" || stage == "state_bootstrap"
}

func syncSnapshotStageAction(stage string) string {
	switch stage {
	case "state_bootstrap":
		return "state_snapshot_bootstrap"
	case "delta_replay":
		return "delta_replay"
	case "snapshot_delta":
		return "snapshot_delta"
	default:
		return ""
	}
}

func syncSnapshotProgressAction(stage string, baseAction string) string {
	if stage != "state_bootstrap" {
		return baseAction
	}
	switch baseAction {
	case "snapshot_fetch_verify":
		return "state_snapshot_bootstrap"
	case "snapshot_applied":
		return "state_snapshot_applied"
	default:
		return baseAction
	}
}

const (
	syncPipelinePeerDiscovery = "peer_discovery"
	syncPipelineHeightSample  = "height_sampling"
	syncPipelineSnapshotSync  = "snapshot_sync"
	syncPipelineBlockCatchup  = "block_catchup"
	syncPipelineLiveConsensus = "live_consensus"
)

func syncMinPeers() int {
	minPeers := SelfHealMinPeers
	if minPeers <= 0 {
		minPeers = 1
	}
	return minPeers
}

func (n *Node) snapshotSyncStartMinPeers(targetHeight uint64, required int) int {
	minPeers := syncMinPeers()
	if required > 0 && required < minPeers {
		minPeers = required
	}
	if n != nil && targetHeight > 0 {
		if quorum := execQuorumRequired(len(n.GetConsensusValidators(int(targetHeight)))); quorum > 0 && quorum < minPeers {
			minPeers = quorum
		}
	}
	if minPeers <= 0 {
		return 1
	}
	return minPeers
}

func computeSyncPipelineStage(
	localHeight uint64,
	targetHeight uint64,
	peers int,
	minPeers int,
	snapshotActive bool,
	forceSnapshot bool,
	syncing bool,
	syncComplete bool,
) string {
	if minPeers <= 0 {
		minPeers = 1
	}
	if syncComplete && !syncing && !snapshotActive {
		return syncPipelineLiveConsensus
	}
	if snapshotActive || forceSnapshot {
		return syncPipelineSnapshotSync
	}
	if peers < minPeers {
		return syncPipelinePeerDiscovery
	}
	if targetHeight == 0 || targetHeight <= localHeight {
		return syncPipelineHeightSample
	}
	return syncPipelineBlockCatchup
}

func (n *Node) allowFreshNodeBlockCatchup(localHeight uint64, targetHeight uint64) bool {
	if n == nil || targetHeight == 0 || localHeight != 0 {
		return false
	}
	if targetHeight <= 1 {
		return true
	}
	return n.freshJoinFallbackBlockReplayAllowed(localHeight, targetHeight)
}

func syncSnapshotRetryBudget() uint64 {
	return 3
}

func syncRestartBlockRangeLagLimit() uint64 {
	return syncRestartSnapshotGraceBlocks()
}

func syncPromoteDeltaReplayToSnapshot(localHeight uint64, lag uint64) bool {
	if localHeight == 0 || lag == 0 {
		return false
	}
	limit := syncRestartBlockRangeLagLimit()
	if limit == 0 {
		limit = syncFastBlockSyncMaxBlocks()
	}
	if limit == 0 {
		limit = 256
	}
	return lag > limit
}

func (n *Node) freshJoinFallbackBlockReplayAllowed(localHeight uint64, targetHeight uint64) bool {
	if n == nil || localHeight != 0 || targetHeight <= 1 {
		return false
	}
	if !syncFreshJoinFallbackBlockReplayEnabled() {
		return false
	}
	session := n.snapshotSessionSnapshot()
	degraded := n.snapshotSessionFailureDegradeActive()
	if session.RetryCount < syncSnapshotRetryBudget() && !degraded {
		return false
	}
	if degraded || session.RetryCount >= syncSnapshotRetryBudget() {
		return true
	}
	sampleReady, _, networkHeight, _, networkHash := n.startupNetworkValidatorSetSampleStatus(localHeight)
	if !sampleReady || networkHeight <= localHeight {
		return false
	}
	return strings.TrimSpace(networkHash) != ""
}

func (n *Node) preferBlockRangeCatchup(localHeight uint64, targetHeight uint64) bool {
	if n == nil || targetHeight == 0 || targetHeight <= localHeight {
		return false
	}
	if localHeight == 0 {
		return targetHeight <= 1 || n.freshJoinFallbackBlockReplayAllowed(localHeight, targetHeight)
	}
	lag := syncLagBlocks(localHeight, targetHeight)
	if lag <= syncRestartBlockRangeLagLimit() {
		return true
	}
	if stageMax := syncRangeFetchStageMaxBlocks(); stageMax > 0 && lag <= stageMax {
		return true
	}
	if n.snapshotSessionFailureDegradeActive() {
		return false
	}
	session := n.snapshotSessionSnapshot()
	if session.RetryCount >= syncSnapshotRetryBudget() {
		return false
	}
	return false
}

func snapshotAnchorUnreachableRetryCount(session SnapshotSession) uint64 {
	if session.RetryCount == 0 {
		return 0
	}
	lastErr := strings.ToLower(strings.TrimSpace(session.LastError))
	lastReject := strings.ToLower(strings.TrimSpace(session.LastRejectReason))
	if strings.Contains(lastErr, "snapshot_anchor_unreachable") || strings.Contains(lastReject, "snapshot_anchor_unreachable") {
		return session.RetryCount
	}
	if count, ok := session.StrictReasonCounts["snapshot_anchor_unreachable"]; ok && count > 0 {
		return session.RetryCount
	}
	return 0
}

func (n *Node) shouldForceSnapshotForFreshNode(localHeight uint64, targetHeight uint64) bool {
	if n == nil || localHeight != 0 || targetHeight == 0 {
		return false
	}
	if targetHeight <= 1 {
		return false
	}
	return !n.freshJoinFallbackBlockReplayAllowed(localHeight, targetHeight)
}

func (n *Node) syncPipelineStageForStatus(localHeight uint64, targetHeight uint64, peers int, snapshotActive bool, syncing bool, syncComplete bool) string {
	minPeers := n.snapshotSyncStartMinPeers(targetHeight, 0)
	forceSnapshot := n.shouldForceSnapshotForFreshNode(localHeight, targetHeight)
	return computeSyncPipelineStage(localHeight, targetHeight, peers, minPeers, snapshotActive, forceSnapshot, syncing, syncComplete)
}

func (n *Node) noteSyncPipelineStage(stage string) {
	if n == nil {
		return
	}
	stage = strings.TrimSpace(stage)
	if stage == "" {
		return
	}
	now := time.Now()
	var shouldLog bool
	n.syncMu.Lock()
	if n.syncPipelineStage != stage {
		if n.syncPipelineStageAt.IsZero() || now.Sub(n.syncPipelineStageAt) >= 2*time.Second {
			shouldLog = true
		}
		n.syncPipelineStage = stage
		n.syncPipelineStageAt = now
	}
	n.syncMu.Unlock()
	if shouldLog {
		log.Printf("[SYNC-PIPELINE] stage=%s", stage)
	}
}

func syncStageUsesBlockRangeFetch(stage string) bool {
	return stage == "direct_gossip" || stage == "range_fetch"
}

func syncBlockRangeAction(stage string) string {
	if syncStageUsesBlockRangeFetch(stage) {
		return "block_range_fetch"
	}
	return ""
}

func syncGossipAction(stage string) string {
	if normalizeSyncStage(stage) == "realtime_gossip" {
		return "gossip_validate_apply"
	}
	return ""
}

func (n *Node) gossipTransportStatus() (blockActive bool, txActive bool, validatorActive bool) {
	if n == nil || n.Host == nil || n.PubSub == nil {
		return false, false, false
	}
	blockActive = n.BlockSubscription != nil || n.BlockTopic != nil || n.TopicBlocks != nil
	txActive = n.TxSubscription != nil || n.TxTopic != nil
	validatorActive = n.ValidatorSub != nil || n.ValidatorTopic != nil || n.ConsensusSub != nil || n.ConsensusTopic != nil
	return blockActive, txActive, validatorActive
}

func (n *Node) gossipRealtimePipelineStatus(syncComplete bool, syncing bool, snapshotActive bool, remoteReady bool) (realtime bool, pipeline string, blockActive bool, txActive bool, validatorActive bool) {
	blockActive, txActive, validatorActive = n.gossipTransportStatus()
	if !syncComplete || syncing || snapshotActive {
		return false, "", blockActive, txActive, validatorActive
	}
	if n == nil || n.Host == nil || n.PubSub == nil || len(n.Host.Network().Peers()) == 0 {
		if blockActive || txActive || validatorActive {
			return false, "gossip_transport_partial", blockActive, txActive, validatorActive
		}
		return false, "", blockActive, txActive, validatorActive
	}
	if !blockActive || !txActive || !validatorActive {
		return false, "gossip_transport_partial", blockActive, txActive, validatorActive
	}
	if !remoteReady {
		return false, "gossip_wait_remote_sample", blockActive, txActive, validatorActive
	}
	return true, "new_block_gossip_validate_apply", blockActive, txActive, validatorActive
}

func syncSnapshotChunkSizeBytes() uint64 {
	if SyncSnapshotChunkSizeBytes == 0 {
		return 1024 * 1024
	}
	return SyncSnapshotChunkSizeBytes
}

