func (n *Node) catchUpFromNetwork(targetHeight uint64) {

	if n.Host == nil || n.Consensus == nil {

		return

	}

	cs := n.Consensus

	cs.mu.Lock()

	// Sync mode is a hard barrier: only one catch-up goroutine runs at a time,

	// but the target can be extended while it is running.

	if targetHeight > cs.SyncTarget {

		cs.SyncTarget = targetHeight

	}

	if cs.syncInFlight {

		cs.mu.Unlock()

		return

	}

	cs.syncInFlight = true

	cs.Syncing = true

	cs.Paused = true

	cs.mu.Unlock()

	if DebugConsensus {

		fmt.Printf("[FORCE-SYNC] local=%d peer=%d\n",

			n.Blockchain.Height(), targetHeight)

	}

	defer func() {

		localHeight := n.Blockchain.Height()
		cleared := false

		cs.mu.Lock()

		targetHeight := cs.SyncTarget

		cs.syncInFlight = false

		if targetHeight == 0 {

			cs.Syncing = false

			cs.Paused = false

			cs.SyncTarget = 0

			cs.mu.Unlock()

			return

		}

		if localHeight < targetHeight {
			cs.Syncing = true

			cs.Paused = true

		} else {

			cs.Syncing = false

			cs.Paused = false

			cs.SyncTarget = 0
			cleared = true

		}

		cs.mu.Unlock()
		if cleared {
			n.replayQueuedExecutionVotes()
		}

	}()

	// Snapshot-first sync only. No full chain replay.

	_ = n.applySnapshotForSyncHeight(targetHeight)

}

type syncPeerCandidate struct {
	PID        peer.ID
	Height     uint64
	Reputation float64
	Score      float64
	Priority   int
}

func (n *Node) pickSyncPeers(targetHeight uint64, exclude map[peer.ID]struct{}, limit int) []peer.ID {
	if n == nil || n.Host == nil || limit == 0 {
		return nil
	}

	peers := n.Host.Network().Peers()
	if len(peers) == 0 {
		return nil
	}

	avoidProvider := n.consumeSyncAvoidProviderOnce()
	buildCandidates := func(skipAvoid bool) []syncPeerCandidate {
		candidates := make([]syncPeerCandidate, 0, len(peers))
		for _, pid := range peers {
			if _, skip := exclude[pid]; skip {
				continue
			}
			if skipAvoid && avoidProvider != "" && strings.EqualFold(pid.String(), avoidProvider) {
				continue
			}
			if n.isPeerQuarantined(pid.String()) {
				continue
			}

			candidate := syncPeerCandidate{
				PID:        pid,
				Reputation: n.syncPeerReputationValue(pid.String()),
				Score:      n.syncPeerScoreValue(pid.String()),
				Priority:   2,
			}

			peerHeight, peerFinalized := n.peerHeightSnapshot(pid.String())
			if peerFinalized > candidate.Height {
				candidate.Height = peerFinalized
			}
			if peerHeight > candidate.Height {
				candidate.Height = peerHeight
			}
			if candidate.Height > 0 {
				candidate.Priority = 1
				if candidate.Height >= targetHeight {
					candidate.Priority = 0
				}
			}

			candidates = append(candidates, candidate)
		}
		return candidates
	}

	candidates := buildCandidates(true)
	if len(candidates) == 0 && avoidProvider != "" {
		candidates = buildCandidates(false)
	}

	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].Priority != candidates[j].Priority {
			return candidates[i].Priority < candidates[j].Priority
		}
		iReady := targetHeight > 0 && candidates[i].Height >= targetHeight
		jReady := targetHeight > 0 && candidates[j].Height >= targetHeight
		if iReady && jReady {
			if candidates[i].Reputation != candidates[j].Reputation {
				return candidates[i].Reputation > candidates[j].Reputation
			}
			if candidates[i].Score != candidates[j].Score {
				return candidates[i].Score > candidates[j].Score
			}
			if candidates[i].Height != candidates[j].Height {
				return candidates[i].Height > candidates[j].Height
			}
			return candidates[i].PID.String() < candidates[j].PID.String()
		}
		if candidates[i].Height != candidates[j].Height {
			return candidates[i].Height > candidates[j].Height
		}
		if candidates[i].Reputation != candidates[j].Reputation {
			return candidates[i].Reputation > candidates[j].Reputation
		}
		if candidates[i].Score != candidates[j].Score {
			return candidates[i].Score > candidates[j].Score
		}
		return candidates[i].PID.String() < candidates[j].PID.String()
	})

	if limit < 0 || limit > len(candidates) {
		limit = len(candidates)
	}
	out := make([]peer.ID, 0, limit)
	for _, candidate := range candidates[:limit] {
		out = append(out, candidate.PID)
	}
	return out
}

func (n *Node) pickSyncPeer(targetHeight uint64, exclude map[peer.ID]struct{}) (peer.ID, bool) {
	peers := n.pickSyncPeers(targetHeight, exclude, 1)
	if len(peers) == 0 {
		return "", false
	}
	return peers[0], true
}

func (n *Node) BuildCensorshipEvidence(

	block Block,

	tx Transaction,

) CensorshipEvidence {
	ev := CensorshipEvidence{

		Leader: block.Proposer,

		TxID: tx.ID,

		Fee: tx.Fee,

		Height: block.ID,

		BlockHash: block.BlockHash,

		MempoolRoot: block.MempoolRoot,

		ObservedAt: block.ID,

		Observer: normalizeValidatorID(n.ID),

		Timestamp: time.Now().Unix(),
	}
	if n != nil && ev.Observer != "" {
		if sig, ok := n.signValidatorPayload(censorshipEvidenceSignBytes(ev)); ok {
			ev.ObserverSig = sig
		}
	}
	return ev

}

func censorshipEvidenceSignBytes(ev CensorshipEvidence) []byte {
	observer := normalizeValidatorID(ev.Observer)
	leader := normalizeValidatorID(ev.Leader)
	return []byte(fmt.Sprintf("%d|%s|%s|%s|%d|%s|%s|%d",
		ev.Height,
		ev.BlockHash,
		leader,
		ev.TxID,
		ev.Fee,
		ev.MempoolRoot,
		observer,
		ev.ObservedAt,
	))
}

