// NEW QUEUE MANAGEMENT FUNCTIONS

// =====================================================

func (n *Node) QueueFutureBlock(block Block) bool {

	if n != nil && n.hasCommittedDifferentHash(block.ID, block.BlockHash) {
		n.recordFinalizedHashConflictEvidence(block.ID, block.Round, "", block.BlockHash, "queued_fork_finalized_height")
		return false
	}

	// Initialize map if needed

	n.forkMu.Lock()

	defer n.forkMu.Unlock()

	if n.ForkBlocks == nil {

		n.ForkBlocks = make(map[uint64][]Block)

	}

	// Check if we already have this block at this height

	for i, existing := range n.ForkBlocks[block.ID] {

		if existing.BlockHash != block.BlockHash {
			continue
		}
		if block.Round > existing.Round {
			n.ForkBlocks[block.ID][i] = block
			goto queued
		}
		return false // Already queued
	}

	// Add to queue

	n.ForkBlocks[block.ID] = append(n.ForkBlocks[block.ID], block)

queued:
	if len(n.ForkBlocks[block.ID]) > maxQueuedForkBlocksPerHeight {
		sort.SliceStable(n.ForkBlocks[block.ID], func(i, j int) bool {
			if n.ForkBlocks[block.ID][i].Round != n.ForkBlocks[block.ID][j].Round {
				return n.ForkBlocks[block.ID][i].Round > n.ForkBlocks[block.ID][j].Round
			}
			return n.ForkBlocks[block.ID][i].BlockHash < n.ForkBlocks[block.ID][j].BlockHash
		})
		n.ForkBlocks[block.ID] = append([]Block(nil), n.ForkBlocks[block.ID][:maxQueuedForkBlocksPerHeight]...)
	}
	queueTip := block.ID
	for h, queued := range n.ForkBlocks {
		if h > queueTip && len(queued) > 0 {
			queueTip = h
		}
	}
	stage, provider := n.syncDiagnosticContext()
	localHeight := uint64(0)
	if n.Blockchain != nil {
		localHeight = n.Blockchain.Height()
	}
	fmt.Printf("[SYNC-QUEUE-ADD] stage=%s provider=%s local=%d next=%d queued_height=%d queued_at_height=%d queue_tip=%d proposer=%s hash=%s prev=%s\n",
		stage,
		ShortID(provider),
		localHeight,
		localHeight+1,
		block.ID,
		len(n.ForkBlocks[block.ID]),
		queueTip,
		ShortID(block.Proposer),
		ShortHash(block.BlockHash),
		ShortHash(block.PrevHash),
	)

	return true

}

func (n *Node) syncDiagnosticContext() (stage string, provider string) {
	if n == nil {
		return "", ""
	}
	n.syncMu.Lock()
	stage = strings.TrimSpace(n.syncStage)
	provider = strings.TrimSpace(n.syncProvider)
	n.syncMu.Unlock()
	if stage == "" {
		stage = "idle"
	}
	return stage, provider
}

const syncQueueApplyFailureEscalationThreshold uint64 = 5

func (n *Node) recordSyncApplyFailure(localHeight uint64, block Block, reason string) uint64 {
	if n == nil {
		return 0
	}
	reason = strings.TrimSpace(reason)
	if block.ID == 0 || strings.TrimSpace(block.BlockHash) == "" || reason == "" {
		return 0
	}

	n.syncMu.Lock()
	defer n.syncMu.Unlock()

	sameFailure := n.syncApplyFailureHeight == block.ID &&
		strings.EqualFold(strings.TrimSpace(n.syncApplyFailureBlockHash), strings.TrimSpace(block.BlockHash)) &&
		strings.EqualFold(strings.TrimSpace(n.syncApplyFailureReason), reason)
	if sameFailure {
		n.syncApplyFailureCount++
	} else {
		n.syncApplyFailureHeight = block.ID
		n.syncApplyFailureLocalHeight = localHeight
		n.syncApplyFailureBlockHash = strings.TrimSpace(block.BlockHash)
		n.syncApplyFailurePrevHash = strings.TrimSpace(block.PrevHash)
		n.syncApplyFailureReason = reason
		n.syncApplyFailureProposer = normalizeValidatorID(block.Proposer)
		n.syncApplyFailureCount = 1
	}
	n.syncApplyFailureAt = time.Now()
	return n.syncApplyFailureCount
}

func (n *Node) syncApplyFailure(height uint64, blockHash string) (reason string, count uint64, ok bool) {
	if n == nil || height == 0 || strings.TrimSpace(blockHash) == "" {
		return "", 0, false
	}
	n.syncMu.Lock()
	defer n.syncMu.Unlock()
	if n.syncApplyFailureHeight != height ||
		!strings.EqualFold(strings.TrimSpace(n.syncApplyFailureBlockHash), strings.TrimSpace(blockHash)) {
		return "", 0, false
	}
	return strings.TrimSpace(n.syncApplyFailureReason), n.syncApplyFailureCount, true
}

func (n *Node) clearSyncApplyFailure(height uint64, blockHash string) {
	if n == nil || height == 0 || strings.TrimSpace(blockHash) == "" {
		return
	}
	n.syncMu.Lock()
	defer n.syncMu.Unlock()
	if n.syncApplyFailureHeight != height ||
		!strings.EqualFold(strings.TrimSpace(n.syncApplyFailureBlockHash), strings.TrimSpace(blockHash)) {
		return
	}
	n.syncApplyFailureHeight = 0
	n.syncApplyFailureLocalHeight = 0
	n.syncApplyFailureBlockHash = ""
	n.syncApplyFailurePrevHash = ""
	n.syncApplyFailureReason = ""
	n.syncApplyFailureProposer = ""
	n.syncApplyFailureCount = 0
	n.syncApplyFailureAt = time.Time{}
}

func (n *Node) forceSnapshotSyncAfterCurrentSync(targetHeight uint64, reason string) {
	if n == nil || targetHeight == 0 {
		return
	}
	go func() {
		deadline := time.Now().Add(5 * time.Second)
		for time.Now().Before(deadline) {
			if n.Blockchain != nil && n.Blockchain.Height() >= targetHeight {
				return
			}
			inFlight := false
			if n.Consensus != nil {
				n.Consensus.mu.Lock()
				inFlight = n.Consensus.syncInFlight
				n.Consensus.mu.Unlock()
			}
			if !inFlight {
				break
			}
			time.Sleep(100 * time.Millisecond)
		}
		if n.Blockchain != nil && n.Blockchain.Height() >= targetHeight {
			return
		}
		n.forceSnapshotSyncToHeight(targetHeight, reason)
	}()
}

type scheduledUpdateTraceState struct {
	CurrentHeight        uint64
	UpdateHeight         uint64
	Step                 string
	DueTransition        bool
	DeferForSync         bool
	UpdateBlocked        bool
	PlannedOnly          bool
	Updated              bool
	ProcessedAdds        int
	ProcessedRemoves     int
	NextTransitionHeight uint64
	TransitionValidators int
	NextValidators       int
}

var scheduledUpdateTraceOutput io.Writer

func logScheduledUpdateTrace(stage string, provider string, state scheduledUpdateTraceState) {
	step := strings.TrimSpace(state.Step)
	if step == "" {
		return
	}
	stage = strings.TrimSpace(stage)
	if stage == "" {
		stage = "idle"
	}
	writer := scheduledUpdateTraceOutput
	if writer == nil {
		if !DebugSync && !DebugConsensus {
			return
		}
		writer = os.Stdout
	}
	fmt.Fprintf(writer, "[SYNC-SCHEDULED-UPDATES] stage=%s provider=%s current_height=%d step=%s update_height=%d due_transition=%t defer_for_sync=%t update_blocked=%t planned_only=%t updated=%t processed_adds=%d processed_removes=%d next_transition_height=%d transition_validators=%d next_validators=%d\n",
		stage,
		ShortID(provider),
		state.CurrentHeight,
		step,
		state.UpdateHeight,
		state.DueTransition,
		state.DeferForSync,
		state.UpdateBlocked,
		state.PlannedOnly,
		state.Updated,
		state.ProcessedAdds,
		state.ProcessedRemoves,
		state.NextTransitionHeight,
		state.TransitionValidators,
		state.NextValidators,
	)
}

func (n *Node) queuedFutureHeightsSummary(localHeight uint64, limit int) string {
	if n == nil {
		return "none"
	}
	n.forkMu.RLock()
	defer n.forkMu.RUnlock()

	type queuedHeight struct {
		height uint64
		count  int
	}
	items := make([]queuedHeight, 0, len(n.ForkBlocks))
	for h, blocks := range n.ForkBlocks {
		if h <= localHeight || len(blocks) == 0 {
			continue
		}
		items = append(items, queuedHeight{height: h, count: len(blocks)})
	}
	if len(items) == 0 {
		return "none"
	}
	sort.Slice(items, func(i, j int) bool { return items[i].height < items[j].height })
	if limit <= 0 || limit > len(items) {
		limit = len(items)
	}
	parts := make([]string, 0, limit+1)
	for _, item := range items[:limit] {
		parts = append(parts, fmt.Sprintf("%d(%d)", item.height, item.count))
	}
	if limit < len(items) {
		parts = append(parts, fmt.Sprintf("+%d_more", len(items)-limit))
	}
	return strings.Join(parts, ",")
}

func (n *Node) queuedBlocksAtHeightSummary(height uint64, limit int) string {
	if n == nil || height == 0 {
		return "none"
	}
	n.forkMu.RLock()
	blocks := append([]Block(nil), n.ForkBlocks[height]...)
	n.forkMu.RUnlock()
	if len(blocks) == 0 {
		return "none"
	}
	if limit <= 0 || limit > len(blocks) {
		limit = len(blocks)
	}
	parts := make([]string, 0, limit+1)
	for _, block := range blocks[:limit] {
		parts = append(parts, fmt.Sprintf("%s/%s", ShortHash(block.BlockHash), ShortHash(block.PrevHash)))
	}
	if limit < len(blocks) {
		parts = append(parts, fmt.Sprintf("+%d_more", len(blocks)-limit))
	}
	return strings.Join(parts, ",")
}

func (n *Node) logSyncQueueStall(reason string, localHeight uint64, nextHeight uint64, queueTip uint64, extra string) {
	if n == nil || queueTip <= localHeight {
		return
	}
	stage, provider := n.syncDiagnosticContext()
	line := fmt.Sprintf("[SYNC-QUEUE-STALL] stage=%s provider=%s reason=%s local=%d next=%d queue_tip=%d queued_heights=%s queued_next=%s",
		stage,
		ShortID(provider),
		strings.TrimSpace(reason),
		localHeight,
		nextHeight,
		queueTip,
		n.queuedFutureHeightsSummary(localHeight, 5),
		n.queuedBlocksAtHeightSummary(nextHeight, 4),
	)
	if extra = strings.TrimSpace(extra); extra != "" {
		line += " " + extra
	}
	fmt.Println(line)
}

func (n *Node) maxQueuedFutureHeight(localHeight uint64) uint64 {
	if n == nil {
		return 0
	}
	n.forkMu.RLock()
	defer n.forkMu.RUnlock()

	maxHeight := uint64(0)
	for h, blocks := range n.ForkBlocks {
		if h <= localHeight || len(blocks) == 0 {
			continue
		}
		if h > maxHeight {
			maxHeight = h
		}
	}
	return maxHeight
}

func (n *Node) handleQueuedSyncStall(reason string, localHeight uint64, queueTip uint64) {
	if n == nil || queueTip <= localHeight {
		return
	}

	n.maybeSyncToBestObservedHeight(reason)

	// Escalate to forced snapshot only when commit is clearly stalled.
	if n.commitStallDuration() < execQuorumEmergencyStallTimeout {
		return
	}
	if queueTip <= localHeight+1 {
		return
	}
	n.maybeForceQueueSnapshotSync(queueTip, reason)
}

func (n *Node) maybeForceQueueSnapshotSync(targetHeight uint64, reason string) {
	if n == nil || targetHeight == 0 {
		return
	}
	inFlight := false
	if n.Consensus != nil {
		n.Consensus.mu.Lock()
		inFlight = n.Consensus.syncInFlight
		n.Consensus.mu.Unlock()
	}

	const queueForceCooldown = 12 * time.Second
	now := time.Now()

	n.syncMu.Lock()
	if !n.lastQueueForceSyncAt.IsZero() &&
		now.Sub(n.lastQueueForceSyncAt) < queueForceCooldown &&
		targetHeight <= n.lastQueueForceSyncTarget {
		n.syncMu.Unlock()
		return
	}
	n.lastQueueForceSyncAt = now
	n.lastQueueForceSyncTarget = targetHeight
	n.syncMu.Unlock()

	if DebugSync || DebugConsensus {
		mode := "snapshot"
		if inFlight {
			mode = "deferred_snapshot"
		}
		fmt.Printf("[SYNC-FORCE-QUEUE] reason=%s target=%d mode=%s\n", reason, targetHeight, mode)
	}
	if inFlight {
		n.forceSnapshotSyncAfterCurrentSync(targetHeight, "queue_stall_"+reason)
		return
	}
	go n.forceSnapshotSyncToHeight(targetHeight, "queue_stall_"+reason)
}

func (n *Node) ProcessQueuedBlocks() {

	currentHeight := n.Blockchain.Height()

	nextHeight := currentHeight + 1

	processed := 0

	maxProcess := 10 // Limit to prevent infinite loops

	for processed < maxProcess {

		n.forkMu.RLock()

		blocks, exists := n.ForkBlocks[nextHeight]

		if exists {

			blocks = append([]Block(nil), blocks...)

		}

		n.forkMu.RUnlock()

		if !exists || len(blocks) == 0 {
			queueTip := n.maxQueuedFutureHeight(currentHeight)
			if queueTip > currentHeight {
				n.logSyncQueueStall("queue_gap", currentHeight, nextHeight, queueTip, "")
				n.maybeRecoverMissingBlock(nextHeight, "queue_gap")
				n.handleQueuedSyncStall("queue_gap", currentHeight, queueTip)
			}

			break

		}

		// Find a block that connects to our chain

		lastBlock := n.Blockchain.LastBlock()

		var validBlock *Block

		for i, block := range blocks {

			if block.PrevHash == lastBlock.BlockHash {

				validBlock = &blocks[i]

				break

			}

		}

		if validBlock == nil {

			// No connecting block found
			queueTip := n.maxQueuedFutureHeight(currentHeight)
			expectedPrev := ShortHash(lastBlock.BlockHash)
			n.logSyncQueueStall("queue_prevhash_mismatch", currentHeight, nextHeight, queueTip,
				fmt.Sprintf("expected_prev=%s", expectedPrev))
			n.handleQueuedSyncStall("queue_prevhash_mismatch", currentHeight, queueTip)

			break

		}

		// Process the valid block

		_ = n.ReceiveBlock(*validBlock, n.Blockchain)

		if n.Blockchain.Height() != validBlock.ID {

			// Could not apply (missing quorum / invalid / still behind). Keep it queued.
			queueTip := n.maxQueuedFutureHeight(currentHeight)
			if queueTip < validBlock.ID {
				queueTip = validBlock.ID
			}
			rejectReason, failCount, haveRejectReason := n.syncApplyFailure(validBlock.ID, validBlock.BlockHash)
			if !haveRejectReason {
				rejectReason = "process_block_incomplete"
				if seenKey := blockSeenKey(*validBlock); seenKey != "" {
					n.unmarkBlockSeen(seenKey)
				}
				failCount = n.recordSyncApplyFailure(currentHeight, *validBlock, rejectReason)
				haveRejectReason = true
			}
			extra := fmt.Sprintf("candidate_hash=%s candidate_prev=%s proposer=%s",
				ShortHash(validBlock.BlockHash), ShortHash(validBlock.PrevHash), ShortID(validBlock.Proposer))
			if haveRejectReason {
				extra += fmt.Sprintf(" reject_reason=%s fail_count=%d", rejectReason, failCount)
			}
			n.logSyncQueueStall("queue_apply_failed", currentHeight, nextHeight, queueTip, extra)
			if haveRejectReason && failCount >= syncQueueApplyFailureEscalationThreshold {
				stage, provider := n.syncDiagnosticContext()
				if strings.TrimSpace(provider) != "" {
					n.setSyncAvoidProviderOnce(provider)
				}
				fmt.Printf("[SYNC-FAILURE-CONTROLLER] stage=%s provider=%s local=%d next=%d target=%d fail_count=%d reason=%s action=provider_rotate_snapshot\n",
					stage,
					ShortID(provider),
					currentHeight,
					nextHeight,
					queueTip,
					failCount,
					rejectReason,
				)
				forceTarget := queueTip
				if followup := n.bestFollowupSyncTarget(currentHeight); followup > forceTarget {
					forceTarget = followup
				}
				n.maybeForceQueueSnapshotSync(forceTarget, "queue_apply_failed_"+rejectReason)
			}
			n.handleQueuedSyncStall("queue_apply_failed", currentHeight, queueTip)

			break

		}

		// Remove this block from queue

		n.RemoveFromQueue(nextHeight, validBlock.BlockHash)

		// Update for next iteration

		currentHeight = n.Blockchain.Height()

		nextHeight = currentHeight + 1
		n.replayQueuedLeaderBlocksForCurrentEpoch()

		processed++

		// Small delay to prevent tight loop

		time.Sleep(10 * time.Millisecond)

	}

	if processed > 0 {
		n.maybeExitSyncMode("queued_blocks_applied")

	}

}

func (n *Node) RemoveFromQueue(height uint64, blockHash string) {

	n.forkMu.Lock()

	defer n.forkMu.Unlock()

	blocks, exists := n.ForkBlocks[height]

	if !exists {

		return

	}

	newBlocks := []Block{}

	for _, block := range blocks {

		if block.BlockHash != blockHash {

			newBlocks = append(newBlocks, block)

		}

	}

	if len(newBlocks) == 0 {

		delete(n.ForkBlocks, height)

	} else {

		n.ForkBlocks[height] = newBlocks

	}

}

func maxUint64(a, b uint64) uint64 {

	if a > b {

		return a

	}

	return b

}

func ComputeExpectedMempoolRoot(height int) string {

	// NOTE:

	// This is CONSENSUS-NEUTRAL.

	// Used ONLY for fork scoring / diagnostics.

	// Collect pending tx IDs deterministically

	txIDs := make([]string, 0, len(GlobalMempoolSnapshot))

	for _, tx := range GlobalMempoolSnapshot {

		txIDs = append(txIDs, tx.ID)

	}

	sort.Strings(txIDs)

	// Height binding (prevents reuse across heights)

	data := strconv.Itoa(height) + "|" + strings.Join(txIDs, ",")

	hash := sha256.Sum256([]byte(data))

	return hex.EncodeToString(hash[:])

}

func (n *Node) HandleFork(

	newBlock Block,

	existingBlock Block,

) {

	// =====================================================

	// =====================================================

	expectedRoot := ComputeExpectedMempoolRoot(

		int(n.Blockchain.Height()),
	)

	// =====================================================

	// =====================================================

	scoreNew := ScoreFork(newBlock, expectedRoot)

	scoreOld := ScoreFork(existingBlock, expectedRoot)

	if DebugConsensus {

		fmt.Printf(

			"   Fork scores | new(c=%d m=%d s=%d) old(c=%d m=%d s=%d)\n",

			scoreNew.CensorshipScore,

			scoreNew.MempoolDistance,

			scoreNew.SignatureWeight,

			scoreOld.CensorshipScore,

			scoreOld.MempoolDistance,

			scoreOld.SignatureWeight,
		)

	}

	// =====================================================

	// =====================================================

	winnerScore := PreferFork(scoreNew, scoreOld)

	var winnerBlock Block

	if winnerScore.BlockHash == newBlock.BlockHash {

		winnerBlock = newBlock

	} else {

		winnerBlock = existingBlock

	}

	n.SwitchToFork(winnerBlock)

}

func PreferFork(a, b ForkScore) ForkScore {

	// =====================================================

	// =====================================================

	if a.TotalScore > b.TotalScore {

		return a

	}

	if b.TotalScore > a.TotalScore {

		return b

	}

	// =====================================================

	// =====================================================

	if a.Timestamp > b.Timestamp {

		return a

	}

	if b.Timestamp > a.Timestamp {

		return b

	}

	// =====================================================

	// =====================================================

	if a.BlockHash < b.BlockHash {

		return a

	}

	return b

}

func ScoreFork(

	block Block,

	expectedStateRoot string,

) ForkScore {

	score := ForkScore{}

	score.Timestamp = int64(SystemTimeUnits(block.BlockTime))

	// =====================================================

	// =====================================================

	if block.ResultHash == nil || len(block.ExecutionResults) == 0 {

		return score // zero score = dead fork

	}

	score.ExecutionScore = len(block.ExecutionResults) * 10

	// =====================================================

	// =====================================================

	if block.StateRoot == expectedStateRoot {

		score.StateScore = 100

	}

	// =====================================================

	// =====================================================

	cScore := int(ValidatorCensorshipScore(

		block.Proposer,

		int(block.ID),
	))

	score.CensorshipScore = -cScore * 20

	// =====================================================

	// =====================================================

	if !ResultGossipOnly {

		age := time.Now().Unix() - block.Timestamp

		if age < 0 {

			age = 0

		}

		score.FreshnessScore = int(maxInt64(0, 30-age))

	}

	// =====================================================

	// =====================================================

	score.TotalScore =

		score.ExecutionScore +

			score.StateScore +

			score.CensorshipScore +

			score.FreshnessScore

	return score

}

