func (n *Node) SwitchToFork(newBlock Block) {

	// =====================================================

	// =====================================================

	if n == nil || n.Blockchain == nil {
		return
	}

	if n.hasCommittedDifferentHash(newBlock.ID, newBlock.BlockHash) {
		n.recordFinalizedHashConflictEvidence(newBlock.ID, newBlock.Round, "", newBlock.BlockHash, "switch_to_fork_finalized_height")
		return
	}

	// NOTE: Full reorg requires snapshot history.

	// For now, only allow switching if height matches tip.

	if newBlock.ID != n.Blockchain.Height() {

		return

	}

	// =====================================================

	// =====================================================

	n.Blockchain.mu.Lock()

	if int(newBlock.ID) >= len(n.Blockchain.Blocks) {

		n.Blockchain.mu.Unlock()

		return

	}

	n.Blockchain.Blocks[newBlock.ID] = newBlock

	n.Blockchain.mu.Unlock()

	// =====================================================

	// =====================================================

	n.seenBlockMu.Lock()

	n.SeenBlockHashes = make(map[string]bool)

	n.seenBlockQueue = nil

	n.seenBlockHead = 0

	n.seenBlockMu.Unlock()

	// =====================================================

	// =====================================================

	n.RebuildLedgerFromGenesis()

}

func GenesisLedger() Ledger {

	l := Ledger{

		Balances: make(map[string]int),

		Nonces: make(map[string]int),

		Stakes: make(map[string]StakeLock),

		ValidatorRewardWallets: make(map[string]string),

		EVMState: make(map[string]string),

		EVMCode: make(map[string]string),

		EVMStorage: make(map[string]map[string]string),
	}

	// =====================================================

	// =====================================================

	for _, bucket := range tokenomicsBuckets(FixedTotalSupply) {

		addBalance(&l, CoinSymbol, bucket.Address, int(bucket.Allocation))

	}

	ensureTreasuryAndRewards(&l)

	return l

}

func (n *Node) RebuildLedgerFromGenesis() {

	genesisLedger := GenesisLedger()

	n.setExecutionLedger(genesisLedger)

	n.Blockchain.mu.RLock()

	blocks := append([]Block(nil), n.Blockchain.Blocks...)

	n.Blockchain.mu.RUnlock()

	height := uint64(0)

	if len(blocks) > 0 {

		height = blocks[len(blocks)-1].ID

	}

	for i := uint64(1); i <= height; i++ {

		if int(i) >= len(blocks) {

			return

		}

		block := blocks[i]

		newLedger, err := ApplyBlockStateWithNode(n, n.currentExecutionLedgerClone(), block)

		if err != nil {

			return

		}

		n.setExecutionLedger(newLedger)

	}

}

type TokenomicsBucket struct {
	Name string `json:"name"`

	Address string `json:"address"`

	Allocation int64 `json:"allocation"`

	Percent float64 `json:"percent"`

	Balance int `json:"balance,omitempty"`
}

type TokenomicsSummary struct {
	ChainID string `json:"chain_id"`

	Symbol string `json:"symbol"`

	TotalSupply int64 `json:"total_supply"`

	Decimals int `json:"decimals"`

	Buckets []TokenomicsBucket `json:"buckets"`
}

func tokenomicsBuckets(total int64) []TokenomicsBucket {

	if total <= 0 {

		return nil

	}

	teamTreasury := total * 25 / 100

	foundation := total * 15 / 100

	validatorBootstrap := total * 10 / 100

	community := total * 20 / 100

	futureRewards := total * 30 / 100

	allocated := teamTreasury + foundation + validatorBootstrap + community + futureRewards

	if remainder := total - allocated; remainder > 0 {

		futureRewards += remainder

	}

	return []TokenomicsBucket{

		{

			Name: "Team Treasury",

			Address: OWNER_ADDRESS,

			Allocation: teamTreasury,

			Percent: 25,
		},

		{

			Name: "Foundation",

			Address: FOUNDATION_ADDRESS,

			Allocation: foundation,

			Percent: 15,
		},

		{

			Name: "Validator Bootstrap",

			Address: VALIDATOR_BOOTSTRAP_POOL,

			Allocation: validatorBootstrap,

			Percent: 10,
		},

		{

			Name: "Community",

			Address: COMMUNITY_POOL,

			Allocation: community,

			Percent: 20,
		},

		{

			Name: "Future Rewards",

			Address: USER_REWARD_POOL,

			Allocation: futureRewards,

			Percent: 30,
		},
	}

}

func ensureTreasuryAndRewards(ledger *Ledger) {

	if ledger == nil {

		return

	}

	if _, ok := ledger.Balances[balanceKey(CoinSymbol, TREASURY_ADDRESS)]; !ok {

		addBalance(ledger, CoinSymbol, TREASURY_ADDRESS, 0)

	}

	if _, ok := ledger.Balances[balanceKey(CoinSymbol, USER_REWARD_POOL)]; !ok {

		addBalance(ledger, CoinSymbol, USER_REWARD_POOL, 0)

	}

}

func exportTokenomicsSummary(node *Node, path string) {

	if node == nil || path == "" {

		return

	}

	buckets := tokenomicsBuckets(FixedTotalSupply)

	for i := range buckets {

		buckets[i].Balance = getBalance(node.Ledger, CoinSymbol, buckets[i].Address)

	}

	summary := TokenomicsSummary{

		ChainID: ChainID,

		Symbol: CoinSymbol,

		TotalSupply: FixedTotalSupply,

		Decimals: CoinDecimals,

		Buckets: buckets,
	}

	data, err := json.MarshalIndent(summary, "", "  ")

	if err != nil {

		return

	}

	_ = os.WriteFile(path, data, 0600)

}

func CountVerifiedSignatures(block Block) int {

	count := 0

	for _, entry := range block.Signatures {

		addr, sig, ok := ParseSignature(entry)

		if !ok {

			continue

		}

		validatorPubKeysMu.RLock()
		pub, ok := ValidatorPubKeys[addr]
		validatorPubKeysMu.RUnlock()

		if !ok {

			continue

		}

		if ed25519.Verify(pub, []byte(block.BlockHash), sig) {

			count++

		}

	}

	return count

}

