// CollectSignatures simulates quorum approval

func CollectSignatures(validators []*Node, blockHash string) []string {

	sigs := []string{}

	for _, v := range validators {

		sigs = append(sigs, v.Wallet.Address)

		if len(sigs)*3 >= len(validators)*2 {

			break // 2/3 quorum

		}

	}

	return sigs

}

