func StoreGenesisBlock(db *NodeDB, block Block) {

	data, _ := json.Marshal(block)

	_ = db.Blocks.Update(func(txn *Txn) error {

		enc, err := encryptDBValue(data)
		if err != nil {
			return err
		}
		return txn.Set([]byte("block:0"), enc)

	})
	_ = db.StoreTxRecords(block)

}

func (n *Node) cleanupInactiveValidators() {

	ticker := time.NewTicker(15 * time.Second)

	defer ticker.Stop()

	for {

		select {

		case <-n.shutdownCh:

			return

		case <-ticker.C:

			if ValidatorInactiveBlocks == 0 {

				continue

			}

			// Deterministic mode computes inactivity from finalized blocks inside
			// applyScheduledValidatorUpdates at commit time.
			if DeterministicValidatorSelection {

				continue

			}

			height := uint64(0)

			if n.Blockchain != nil {

				height = n.Blockchain.FinalizedHeight()

				if height == 0 {

					height = n.Blockchain.Height()

				}

			}

			if height == 0 {

				n.commitMu.Lock()

				height = n.committedHeight

				n.commitMu.Unlock()

			}

			if height == 0 {

				height = 1

			}

			var toRemove []string

			n.validatorMu.Lock()

			for id, st := range n.validatorStatus {

				if normalizeValidatorID(id) == normalizeValidatorID(n.ID) {

					continue

				}

				refHeight := st.FinalizedHeight

				if refHeight == 0 {

					refHeight = st.ReportedHeight

				}

				if refHeight == 0 {

					refHeight = st.Height

				}

				if refHeight == 0 {

					continue

				}

				if height > refHeight && height-refHeight >= ValidatorInactiveBlocks {

					toRemove = append(toRemove, id)

				}

			}

			n.validatorMu.Unlock()

			if len(toRemove) == 0 {

				continue

			}

			toRemove = canonicalValidatorIDs(toRemove)
			for _, id := range toRemove {
				n.applyOfflineInactivityPenalty(id, height)
			}

			activeNow := len(n.consensusValidatorsForHeight(height + 1))
			if activeNow == 0 {
				activeNow = len(n.GetConsensusValidators(int(height + 1)))
			}
			maxRemovals := activeNow - minActiveValidatorsFloor()
			if maxRemovals <= 0 {
				if DebugConsensus {
					fmt.Printf("Ã¢Å¡Â Ã¯Â¸Â Skipping inactive removals: active validators at minimum (%d)\n", minActiveValidatorsFloor())
				}
				continue
			}
			if len(toRemove) > maxRemovals {
				toRemove = toRemove[:maxRemovals]
			}

			if ValidatorInactivePermanentRemove {

				GlobalValidatorRegistry.mu.Lock()

				for _, id := range toRemove {

					rec := ensureValidatorRecordLocked(id, height)

					if rec == nil {

						continue

					}

					rec.Status = ValidatorExited

					rec.JailUntilHeight = 0

					rec.JoinHeight = 0

				}

				GlobalValidatorRegistry.mu.Unlock()

			}

			activationHeight := height + validatorSetActivationDelayBlocks()

			for _, id := range toRemove {
				n.queuePendingValidatorRemoval(id, activationHeight)

			}

		}

	}

}

