func splitCommaList(v string) []string {

	parts := strings.Split(v, ",")

	out := make([]string, 0, len(parts))

	for _, part := range parts {

		part = strings.TrimSpace(part)

		if part != "" {

			out = append(out, part)

		}

	}

	return out

}

func normalizeIDList(ids []string) []string {

	if ids == nil {

		return nil

	}

	out := make([]string, 0, len(ids))

	seen := make(map[string]struct{}, len(ids))

	for _, id := range ids {

		id = normalizeValidatorID(id)

		if id == "" {

			continue

		}

		if _, ok := seen[id]; ok {

			continue

		}

		seen[id] = struct{}{}

		out = append(out, id)

	}

	return out

}

func isCoreValidator(nodeID string) bool {
	id := strings.ToUpper(strings.TrimSpace(nodeID))
	if id == "" {
		return false
	}
	return runtimeCoreValidatorContains(id)

}

func requiresWalletAuth(nodeID string) bool {

	if !ConfigAuthRequireWallet {

		return false

	}

	return !isCoreValidator(nodeID)

}

func stripScheme(addr string) string {

	addr = strings.TrimSpace(addr)

	for _, prefix := range []string{"tcp://", "http://", "https://"} {

		if strings.HasPrefix(addr, prefix) {

			return strings.TrimPrefix(addr, prefix)

		}

	}

	return addr

}

func stripP2PComponent(addr string) string {

	if idx := strings.Index(addr, "/p2p/"); idx >= 0 {

		return addr[:idx]

	}

	return addr

}

func multiaddrFromHostPort(host, port string) (string, error) {

	if port == "" {

		return "", fmt.Errorf("missing port")

	}

	if host == "" {

		host = "0.0.0.0"

	}

	if strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {

		host = strings.TrimSuffix(strings.TrimPrefix(host, "["), "]")

	}

	if ip := net.ParseIP(host); ip != nil {

		if ip.To4() != nil {

			return fmt.Sprintf("/ip4/%s/tcp/%s", host, port), nil

		}

		return fmt.Sprintf("/ip6/%s/tcp/%s", host, port), nil

	}

	return fmt.Sprintf("/dns4/%s/tcp/%s", host, port), nil

}

func normalizeListenMultiaddr(addr string) (string, error) {

	addr = strings.TrimSpace(addr)

	if addr == "" {

		return "", nil

	}

	if strings.HasPrefix(addr, "/") {

		addr = stripP2PComponent(addr)

		if _, err := ma.NewMultiaddr(addr); err != nil {

			return "", err

		}

		return addr, nil

	}

	addr = stripScheme(addr)

	if strings.HasPrefix(addr, ":") {

		return multiaddrFromHostPort("0.0.0.0", strings.TrimPrefix(addr, ":"))

	}

	host, port, err := net.SplitHostPort(addr)

	if err != nil {

		return "", err

	}

	return multiaddrFromHostPort(host, port)

}

func applyP2PCLIListenAddr(addr string) (string, int, error) {
	addr = strings.TrimSpace(addr)
	if addr == "" {
		return "", 0, nil
	}
	normalized, err := normalizeListenMultiaddr(addr)
	if err != nil {
		return "", 0, err
	}
	return normalized, portFromMultiaddr(normalized), nil
}

func normalizeExternalMultiaddr(addr string) (string, bool, error) {

	addr = strings.TrimSpace(addr)

	if addr == "" {

		return "", false, nil

	}

	hasPeerID := strings.Contains(addr, "/p2p/")

	if strings.HasPrefix(addr, "/") {

		if !hasPeerID {

			if _, err := ma.NewMultiaddr(addr); err != nil {

				return "", false, err

			}

		}

		return addr, hasPeerID, nil

	}

	addr = stripScheme(addr)

	if strings.HasPrefix(addr, ":") {

		maddr, err := multiaddrFromHostPort("0.0.0.0", strings.TrimPrefix(addr, ":"))

		return maddr, false, err

	}

	host, port, err := net.SplitHostPort(addr)

	if err != nil {

		return "", false, err

	}

	maddr, err := multiaddrFromHostPort(host, port)

	return maddr, false, err

}

func normalizeRPCAddr(addr string) string {

	addr = strings.TrimSpace(addr)

	if addr == "" {

		return ""

	}

	if strings.HasPrefix(addr, "/") {

		if maddr, err := ma.NewMultiaddr(addr); err == nil {

			host := ""

			if v, err := maddr.ValueForProtocol(ma.P_IP4); err == nil && v != "" {

				host = v

			}

			if v, err := maddr.ValueForProtocol(ma.P_IP6); err == nil && v != "" {

				host = v

			}

			if v, err := maddr.ValueForProtocol(ma.P_DNS4); err == nil && v != "" {

				host = v

			}

			if v, err := maddr.ValueForProtocol(ma.P_DNS6); err == nil && v != "" {

				host = v

			}

			if v, err := maddr.ValueForProtocol(ma.P_TCP); err == nil && v != "" && host != "" {

				return net.JoinHostPort(host, v)

			}

		}

		return addr

	}

	return stripScheme(addr)

}

func isAddrInUseError(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, syscall.EADDRINUSE) {
		return true
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "address already in use") ||
		strings.Contains(msg, "only one usage of each socket address")
}

func portFromMultiaddr(addr string) int {

	addr = strings.TrimSpace(addr)

	if addr == "" {

		return 0

	}

	addr = stripP2PComponent(addr)

	maddr, err := ma.NewMultiaddr(addr)

	if err != nil {

		return 0

	}

	portStr, err := maddr.ValueForProtocol(ma.P_TCP)

	if err != nil {

		return 0

	}

	port, err := strconv.Atoi(portStr)

	if err != nil || port <= 0 {

		return 0

	}

	return port

}

func applyChainConfig(cc ChainConfig) bool {

	changed := false

	if cc.ChainID != "" {

		ConfigChainID = cc.ChainID

		if ChainID == "" || ChainID == ConfigChainID {

			ChainID = cc.ChainID

		}

		changed = true

	}

	if cc.Moniker != "" {

		ConfigMoniker = cc.Moniker

		changed = true

	}

	if strings.TrimSpace(cc.GenesisPath) != "" {

		ConfigGenesisPath = strings.TrimSpace(cc.GenesisPath)

		changed = true

	}

	if strings.TrimSpace(cc.GenesisHash) != "" {

		hash := strings.ToLower(strings.TrimSpace(cc.GenesisHash))

		hash = strings.TrimPrefix(hash, "0x")

		if len(hash) != 64 {

			fmt.Printf("WARN chain.genesis_hash invalid length (expected 64 hex chars)\n")

		} else {

			ConfigGenesisHash = hash

			GenesisHashExpected = hash

			GenesisHash = hash

			changed = true

		}

	}

	return changed

}

func resolveGenesisPath(dataDir string) string {

	path := strings.TrimSpace(ConfigGenesisPath)

	if path != "" {

		if !filepath.IsAbs(path) && dataDir != "" {

			candidate := filepath.Join(dataDir, path)

			if _, err := os.Stat(candidate); err == nil {

				return candidate

			}

		}

		return path

	}

	if dataDir != "" {

		candidate := filepath.Join(dataDir, "genesis.json")

		if _, err := os.Stat(candidate); err == nil {

			return candidate

		}

	}

	return "genesis.json"

}

func applyP2PConfig(pc P2PConfig) bool {

	changed := false

	if pc.Laddr != "" {

		if addr, err := normalizeListenMultiaddr(pc.Laddr); err == nil && addr != "" {

			ConfigP2PListenAddr = addr

			changed = true

		} else if err != nil {

			fmt.Printf("WARN p2p.laddr invalid: %v\n", err)

		}

	}

	if pc.ExternalAddress != "" {

		if addr, hasPeerID, err := normalizeExternalMultiaddr(pc.ExternalAddress); err == nil && addr != "" {

			ConfigP2PExternalAddr = addr

			ConfigP2PExternalHasPeerID = hasPeerID

			changed = true

		} else if err != nil {

			fmt.Printf("WARN p2p.external_address invalid: %v\n", err)

		}

	}

	if len(pc.Seeds) > 0 {

		ConfigSeeds = append([]string{}, pc.Seeds...)

		changed = true

	}

	if len(pc.PersistentPeers) > 0 {

		ConfigPersistentPeers = append([]string{}, pc.PersistentPeers...)

		changed = true

	}

	if pc.PersistPeerIDRefresh != PersistPeerIDRefresh {

		PersistPeerIDRefresh = pc.PersistPeerIDRefresh

		changed = true

	}

	combined := append([]string{}, pc.Seeds...)

	combined = append(combined, pc.PersistentPeers...)

	for _, addr := range combined {

		if addr != "" && !strings.Contains(addr, "/p2p/") {

			fmt.Printf("WARN peer address missing /p2p/ peer ID: %s\n", addr)

		}

	}

	return changed

}

func normalizeConsensusPenaltyEnforceMode(mode string) string {
	m := strings.ToLower(strings.TrimSpace(mode))
	switch m {
	case "", "converged_only":
		return "converged_only"
	case "always_strict":
		return "always_strict"
	default:
		return "converged_only"
	}
}

func applyConsensusConfig(cc ConsensusConfig) bool {

	changed := false

	parse := func(label, raw string, dst *time.Duration) {

		if raw == "" {

			return

		}

		d, err := time.ParseDuration(raw)

		if err != nil {

			fmt.Printf("WARN consensus %s invalid: %v\n", label, err)

			return

		}

		*dst = d

		changed = true

	}

	parse("timeout_propose", cc.TimeoutPropose, &ConsensusTimeoutPropose)

	parse("timeout_propose_delta", cc.TimeoutProposeDelta, &ConsensusTimeoutProposeDelta)

	parse("timeout_prevote", cc.TimeoutPrevote, &ConsensusTimeoutPrevote)

	parse("timeout_prevote_delta", cc.TimeoutPrevoteDelta, &ConsensusTimeoutPrevoteDelta)

	parse("timeout_precommit", cc.TimeoutPrecommit, &ConsensusTimeoutPrecommit)

	parse("timeout_precommit_delta", cc.TimeoutPrecommitDelta, &ConsensusTimeoutPrecommitDelta)

	parse("timeout_commit", cc.TimeoutCommit, &ConsensusTimeoutCommit)

	if cc.TimeoutPropose == "" {

		parse("propose", cc.Propose, &ConsensusTimeoutPropose)

	}

	if cc.TimeoutPrevote == "" {

		parse("prevote", cc.Prevote, &ConsensusTimeoutPrevote)

	}

	if cc.TimeoutPrecommit == "" {

		parse("precommit", cc.Precommit, &ConsensusTimeoutPrecommit)

	}

	if cc.TimeoutCommit == "" {

		parse("commit", cc.Commit, &ConsensusTimeoutCommit)

	}

	parse("min_block_interval", cc.MinBlockInterval, &ConsensusMinBlockInterval)

	parse("recompute_pause", cc.RecomputePause, &ConsensusRecomputePause)

	if applyConsensusDetectorConfig(cc) {
		changed = true
	}

	if cc.WeakSubjectivityDepth > 0 {

		WeakSubjectivityDepth = cc.WeakSubjectivityDepth

		changed = true

	}

	if cc.MaxFutureBlockGap > 0 {

		MaxFutureBlockGap = cc.MaxFutureBlockGap

		changed = true

	}

	if cc.ValidatorSetCommitmentV2Height != ValidatorSetCommitmentV2Height {

		ValidatorSetCommitmentV2Height = cc.ValidatorSetCommitmentV2Height

		changed = true

	}

	if cc.ValidatorSetHashV3Height != ValidatorSetHashV3Height {

		ValidatorSetHashV3Height = cc.ValidatorSetHashV3Height

		changed = true

	}

	if cc.ProposerRoundTimeoutSeconds > 0 {

		ProposerRoundTimeout = time.Duration(cc.ProposerRoundTimeoutSeconds) * time.Second

		changed = true

	}

	if cc.FastProposerFailoverEnabled != nil {

		ConsensusFastProposerFailoverEnabled = *cc.FastProposerFailoverEnabled

		changed = true

	}

	if cc.FastProposerFailoverMinSeconds > 0 {

		ConsensusFastProposerFailoverMin = time.Duration(cc.FastProposerFailoverMinSeconds) * time.Second

		changed = true

	}

	if cc.ProposerRoundMax != ProposerRoundMax {

		ProposerRoundMax = cc.ProposerRoundMax

		changed = true

	}

	if cc.ProposerRoundMaxSkew > 0 {

		ProposerRoundMaxSkew = cc.ProposerRoundMaxSkew

		changed = true

	}

	if cc.TransitionBarrierRelaxSeconds > 0 {

		TransitionBarrierRelaxTimeout = time.Duration(cc.TransitionBarrierRelaxSeconds) * time.Second

		changed = true

	}

	if cc.TransitionBarrierMaxDrop > 0 {

		TransitionBarrierMaxDrop = cc.TransitionBarrierMaxDrop

		changed = true

	}

	if strings.TrimSpace(cc.TransitionBarrierRetryMode) != "" {

		TransitionBarrierRetryMode = normalizeTransitionBarrierRetryMode(cc.TransitionBarrierRetryMode)

		changed = true

	}

	if cc.ExecQuorumEmergencyEnabled != nil {

		ExecQuorumEmergencyEnabled = *cc.ExecQuorumEmergencyEnabled

		changed = true

	}

	if cc.ExecQuorumEmergencyStallSeconds > 0 {

		execQuorumEmergencyStallTimeout = time.Duration(cc.ExecQuorumEmergencyStallSeconds) * time.Second

		changed = true

	}

	if strings.TrimSpace(cc.PenaltyEnforceMode) != "" {

		ConsensusPenaltyEnforceMode = normalizeConsensusPenaltyEnforceMode(cc.PenaltyEnforceMode)

		changed = true

	}

	if cc.InvalidProposerQuarantineAfter > 0 {

		ConsensusInvalidProposerQuarantineAfter = cc.InvalidProposerQuarantineAfter

		changed = true

	}

	if cc.ExecMismatchQuarantineAfter > 0 {

		ConsensusExecMismatchQuarantineAfter = cc.ExecMismatchQuarantineAfter

		changed = true

	}

	if cc.ExecMismatchSlashAfter > 0 {

		ConsensusExecMismatchSlashAfter = cc.ExecMismatchSlashAfter

		changed = true

	}

	if cc.ProposeRequiresSyncReady != ConsensusProposeRequiresSyncReady {

		ConsensusProposeRequiresSyncReady = cc.ProposeRequiresSyncReady

		changed = true

	}

	if cc.CorePendingExcludedFromProposer != nil && *cc.CorePendingExcludedFromProposer != ConsensusCorePendingExcludedFromProposer {

		ConsensusCorePendingExcludedFromProposer = *cc.CorePendingExcludedFromProposer

		changed = true

	}

	if cc.CoreActivationEffectiveHeightBuffer > 0 && cc.CoreActivationEffectiveHeightBuffer != ConsensusCoreActivationEffectiveHeightBuffer {

		ConsensusCoreActivationEffectiveHeightBuffer = cc.CoreActivationEffectiveHeightBuffer

		changed = true

	}

	if cc.PostBlockSafeModeEnabled != nil && *cc.PostBlockSafeModeEnabled != ConsensusPostBlockSafeModeEnabled {

		ConsensusPostBlockSafeModeEnabled = *cc.PostBlockSafeModeEnabled

		changed = true

	}

	if cc.PostBlockSafeModeMinSeconds > 0 {

		ConsensusPostBlockSafeModeMin = time.Duration(cc.PostBlockSafeModeMinSeconds) * time.Second

		changed = true

	}

	if cc.PostBlockSafeModeMaxSeconds > 0 {

		ConsensusPostBlockSafeModeMax = time.Duration(cc.PostBlockSafeModeMaxSeconds) * time.Second

		changed = true

	}

	if cc.PostBlockSafeModeHistoryBlocks > 0 {

		ConsensusPostBlockSafeModeHistoryBlocks = cc.PostBlockSafeModeHistoryBlocks

		changed = true

	}

	if cc.PostBlockSafeModeLiveQuorumBPS > 0 {

		ConsensusPostBlockSafeModeLiveQuorumBPS = sanitizeBPS(cc.PostBlockSafeModeLiveQuorumBPS)

		changed = true

	}

	if ConsensusPostBlockSafeModeMin <= 0 {
		ConsensusPostBlockSafeModeMin = 5 * time.Second
	}
	if ConsensusPostBlockSafeModeMax <= 0 {
		ConsensusPostBlockSafeModeMax = 8 * time.Second
	}
	if ConsensusPostBlockSafeModeMax < ConsensusPostBlockSafeModeMin {
		ConsensusPostBlockSafeModeMax = ConsensusPostBlockSafeModeMin
	}

	if cc.EnforceDeterministicTxOrder {

		EnforceDeterministicTxOrder = true

		changed = true

	}

	return changed

}

