func decodeStorageEncryptionKey(input string) ([]byte, error) {
	input = strings.TrimSpace(input)
	if input == "" {
		return nil, nil
	}

	if decoded, err := hex.DecodeString(input); err == nil {
		return decoded, nil
	}

	if decoded, err := base64.StdEncoding.DecodeString(input); err == nil {
		return decoded, nil
	}

	if decoded, err := base64.RawStdEncoding.DecodeString(input); err == nil {
		return decoded, nil
	}

	return nil, fmt.Errorf("invalid key encoding (expected hex or base64)")
}

func loadStorageEncryptionKeyFromFile(path string) ([]byte, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 32 {
		return append([]byte{}, trimmed...), nil
	}
	return decodeStorageEncryptionKey(string(trimmed))
}

func configureStorageEncryptionKey() error {
	ConfigStorageEncryptionEnabled = false
	ConfigStorageEncryptionKeySource = ""
	dbValueEncryptionKey = nil

	if ConfigStorageEncryptionKeyHex != "" {
		key, err := decodeStorageEncryptionKey(ConfigStorageEncryptionKeyHex)
		if err != nil {
			return err
		}
		if len(key) != 32 {
			return fmt.Errorf("storage.encryption_key_hex must decode to 32 bytes (got %d)", len(key))
		}
		dbValueEncryptionKey = append([]byte{}, key...)
		ConfigStorageEncryptionEnabled = true
		ConfigStorageEncryptionKeySource = "config:encryption_key_hex"
		return nil
	}

	if ConfigStorageEncryptionKeyBase64 != "" {
		key, err := decodeStorageEncryptionKey(ConfigStorageEncryptionKeyBase64)
		if err != nil {
			return err
		}
		if len(key) != 32 {
			return fmt.Errorf("storage.encryption_key_base64 must decode to 32 bytes (got %d)", len(key))
		}
		dbValueEncryptionKey = append([]byte{}, key...)
		ConfigStorageEncryptionEnabled = true
		ConfigStorageEncryptionKeySource = "config:encryption_key_base64"
		return nil
	}

	if ConfigStorageEncryptionKeyFile != "" {
		key, err := loadStorageEncryptionKeyFromFile(ConfigStorageEncryptionKeyFile)
		if err != nil {
			return err
		}
		if len(key) != 32 {
			return fmt.Errorf("storage.encryption_key_file must provide 32 bytes (got %d)", len(key))
		}
		dbValueEncryptionKey = append([]byte{}, key...)
		ConfigStorageEncryptionEnabled = true
		ConfigStorageEncryptionKeySource = "file:" + ConfigStorageEncryptionKeyFile
		return nil
	}

	envName := strings.TrimSpace(ConfigStorageEncryptionKeyEnv)
	if envName == "" {
		envName = "MSC_DB_ENCRYPTION_KEY"
	}
	envVal := strings.TrimSpace(os.Getenv(envName))
	if envVal == "" {
		return nil
	}

	key, err := decodeStorageEncryptionKey(envVal)
	if err != nil {
		return fmt.Errorf("storage env %s: %w", envName, err)
	}
	if len(key) != 32 {
		return fmt.Errorf("storage env %s must decode to 32 bytes (got %d)", envName, len(key))
	}
	dbValueEncryptionKey = append([]byte{}, key...)
	ConfigStorageEncryptionEnabled = true
	ConfigStorageEncryptionKeySource = "env:" + envName
	return nil
}

