const (
	// Keep inactivity removal in a low-but-safe range for liveness.
	// 0 remains valid and means "disabled".
	recommendedInactiveRemoveBlocksMin uint64 = 6
	recommendedInactiveRemoveBlocksMax uint64 = 20
)

func sanitizeInactiveRemoveBlocks(v uint64) uint64 {
	if v == 0 {
		return 0
	}
	if v < recommendedInactiveRemoveBlocksMin {
		return recommendedInactiveRemoveBlocksMin
	}
	if v > recommendedInactiveRemoveBlocksMax {
		return recommendedInactiveRemoveBlocksMax
	}
	return v
}

