func applyEVMConfig(ec EVMConfig) bool {
	if EVMHardDisabled {
		return forceDisableEVMConfig()
	}

	changed := false

	if ec.DefaultGasLimit > 0 && ConfigEVMDefaultGasLimit != ec.DefaultGasLimit {
		ConfigEVMDefaultGasLimit = ec.DefaultGasLimit
		changed = true
	}

	if ec.MaxGasLimit > 0 && ConfigEVMMaxGasLimit != ec.MaxGasLimit {
		ConfigEVMMaxGasLimit = ec.MaxGasLimit
		changed = true
	}

	if ec.BaseFeeMin > 0 && ConfigEVMBaseFeeMin != ec.BaseFeeMin {
		ConfigEVMBaseFeeMin = ec.BaseFeeMin
		changed = true
	}

	if ec.BaseFeeMax > 0 && ConfigEVMBaseFeeMax != ec.BaseFeeMax {
		ConfigEVMBaseFeeMax = ec.BaseFeeMax
		changed = true
	}

	if ec.BaseFeeUpdateDivisor > 0 && ConfigEVMBaseFeeUpdateDivisor != ec.BaseFeeUpdateDivisor {
		ConfigEVMBaseFeeUpdateDivisor = ec.BaseFeeUpdateDivisor
		changed = true
	}

	if ec.TargetTxPerBlock > 0 && ConfigEVMTargetTxPerBlock != ec.TargetTxPerBlock {
		ConfigEVMTargetTxPerBlock = ec.TargetTxPerBlock
		changed = true
	}

	if ConfigEVMMaxGasLimit == 0 {
		ConfigEVMMaxGasLimit = MaxEVMGasLimit
		changed = true
	}

	if ConfigEVMDefaultGasLimit == 0 {
		ConfigEVMDefaultGasLimit = DefaultEVMGasLimit
		changed = true
	}

	if ConfigEVMDefaultGasLimit > ConfigEVMMaxGasLimit {
		ConfigEVMDefaultGasLimit = ConfigEVMMaxGasLimit
		changed = true
	}

	if ConfigEVMBaseFeeMin < 1 {
		ConfigEVMBaseFeeMin = defaultEVMBaseFeeMin
		changed = true
	}

	if ConfigEVMBaseFeeMax < ConfigEVMBaseFeeMin {
		ConfigEVMBaseFeeMax = ConfigEVMBaseFeeMin
		changed = true
	}

	if ConfigEVMBaseFeeUpdateDivisor < 1 {
		ConfigEVMBaseFeeUpdateDivisor = defaultEVMBaseFeeUpdateDivisor
		changed = true
	}

	if ConfigEVMTargetTxPerBlock < 0 {
		ConfigEVMTargetTxPerBlock = 0
		changed = true
	}

	return changed

}

func applyDTLConfig(dc DTLConfig) bool {
	changed := false

	if ConfigDTLSolidityLikeRuntimeEnabled {
		ConfigDTLSolidityLikeRuntimeEnabled = false
		changed = true
	}

	if ConfigDTLContractsV2Enabled != dc.ContractsV2Enabled {
		ConfigDTLContractsV2Enabled = dc.ContractsV2Enabled
		changed = true
	}

	if ConfigDTLCompatRPCSubsetEnabled != dc.CompatRPCSubsetEnabled {
		ConfigDTLCompatRPCSubsetEnabled = dc.CompatRPCSubsetEnabled
		changed = true
	}

	if ConfigDTLV2ActivationHeight != dc.V2ActivationHeight {
		ConfigDTLV2ActivationHeight = dc.V2ActivationHeight
		changed = true
	}

	if ConfigDTLLogsIndexEnabled != dc.LogsIndexEnabled {
		ConfigDTLLogsIndexEnabled = dc.LogsIndexEnabled
		changed = true
	}

	if dc.OracleMinSigners > 0 && ConfigDTLOracleMinSigners != dc.OracleMinSigners {
		ConfigDTLOracleMinSigners = dc.OracleMinSigners
		changed = true
	}

	if dc.OracleMaxStalenessBlocks > 0 && ConfigDTLOracleMaxStalenessBlocks != dc.OracleMaxStalenessBlocks {
		ConfigDTLOracleMaxStalenessBlocks = dc.OracleMaxStalenessBlocks
		changed = true
	}

	if dc.LendingAccrualIntervalBlocks > 0 && ConfigDTLLendingAccrualIntervalBlocks != dc.LendingAccrualIntervalBlocks {
		ConfigDTLLendingAccrualIntervalBlocks = dc.LendingAccrualIntervalBlocks
		changed = true
	}

	if dc.GameBeaconDelayBlocks > 0 && ConfigDTLGameBeaconDelayBlocks != dc.GameBeaconDelayBlocks {
		ConfigDTLGameBeaconDelayBlocks = dc.GameBeaconDelayBlocks
		changed = true
	}

	if ConfigDTLMaxContractCallDepth != 0 {
		ConfigDTLMaxContractCallDepth = 0
		changed = true
	}

	if ConfigDTLBytecodeRuntimeEnabled {
		ConfigDTLBytecodeRuntimeEnabled = false
		changed = true
	}

	if ConfigDTLBytecodeActivationHeight != 0 {
		ConfigDTLBytecodeActivationHeight = 0
		changed = true
	}

	if ConfigDTLBytecodeMaxSize != DTLDefaultBytecodeMaxSize {
		ConfigDTLBytecodeMaxSize = DTLDefaultBytecodeMaxSize
		changed = true
	}

	if !ConfigDTLBytecodeRequireCanonical {
		ConfigDTLBytecodeRequireCanonical = true
		changed = true
	}

	if ConfigDTLRouterEnabled != dc.RouterEnabled {
		ConfigDTLRouterEnabled = dc.RouterEnabled
		changed = true
	}

	if dc.RouterMaxHops > 0 {
		maxHops := dc.RouterMaxHops
		if maxHops > 16 {
			maxHops = 16
		}
		if ConfigDTLRouterMaxHops != maxHops {
			ConfigDTLRouterMaxHops = maxHops
			changed = true
		}
	}

	if dc.RouterDeadlineMaxBlocks > 0 && ConfigDTLRouterDeadlineMaxBlocks != dc.RouterDeadlineMaxBlocks {
		ConfigDTLRouterDeadlineMaxBlocks = dc.RouterDeadlineMaxBlocks
		changed = true
	}

	if dc.RouterMaxPriceImpactBPS > 0 {
		priceImpact := dc.RouterMaxPriceImpactBPS
		if priceImpact > DTLMaxTaxBPS {
			priceImpact = DTLMaxTaxBPS
		}
		if ConfigDTLRouterMaxPriceImpactBPS != priceImpact {
			ConfigDTLRouterMaxPriceImpactBPS = priceImpact
			changed = true
		}
	}

	if dc.RouterQuoteMaxPaths > 0 {
		maxPaths := dc.RouterQuoteMaxPaths
		if maxPaths > 64 {
			maxPaths = 64
		}
		if ConfigDTLRouterQuoteMaxPaths != maxPaths {
			ConfigDTLRouterQuoteMaxPaths = maxPaths
			changed = true
		}
	}

	if ConfigDTLDeFiFarmEnabled != dc.DeFiFarmEnabled {
		ConfigDTLDeFiFarmEnabled = dc.DeFiFarmEnabled
		changed = true
	}

	if ConfigDTLGameFiSeasonEnabled != dc.GameFiSeasonEnabled {
		ConfigDTLGameFiSeasonEnabled = dc.GameFiSeasonEnabled
		changed = true
	}

	if rewardRef := strings.TrimSpace(dc.GameFiRewardToken); rewardRef != "" {
		if ConfigDTLGameFiRewardToken != rewardRef {
			ConfigDTLGameFiRewardToken = rewardRef
			changed = true
		}
	}

	if dc.GameFiSeasonLengthBlocks > 0 && ConfigDTLGameFiSeasonLengthBlocks != dc.GameFiSeasonLengthBlocks {
		ConfigDTLGameFiSeasonLengthBlocks = dc.GameFiSeasonLengthBlocks
		changed = true
	}

	if dc.GameFiClaimGraceBlocks > 0 && ConfigDTLGameFiClaimGraceBlocks != dc.GameFiClaimGraceBlocks {
		ConfigDTLGameFiClaimGraceBlocks = dc.GameFiClaimGraceBlocks
		changed = true
	}

	if dc.GameFiFeeShareFromPoolBPS > 0 {
		feeShare := dc.GameFiFeeShareFromPoolBPS
		if feeShare > DTLMaxTaxBPS {
			feeShare = DTLMaxTaxBPS
		}
		if ConfigDTLGameFiFeeShareFromPoolBPS != feeShare {
			ConfigDTLGameFiFeeShareFromPoolBPS = feeShare
			changed = true
		}
	}

	if dc.GameFiFeeShareFromLendingBPS > 0 {
		feeShare := dc.GameFiFeeShareFromLendingBPS
		if feeShare > DTLMaxTaxBPS {
			feeShare = DTLMaxTaxBPS
		}
		if ConfigDTLGameFiFeeShareFromLendingBPS != feeShare {
			ConfigDTLGameFiFeeShareFromLendingBPS = feeShare
			changed = true
		}
	}

	if dc.GameFiDuelWinPoints > 0 && ConfigDTLGameFiDuelWinPoints != dc.GameFiDuelWinPoints {
		ConfigDTLGameFiDuelWinPoints = dc.GameFiDuelWinPoints
		changed = true
	}

	if dc.GameFiTournamentWinPoints > 0 && ConfigDTLGameFiTournamentWinPoints != dc.GameFiTournamentWinPoints {
		ConfigDTLGameFiTournamentWinPoints = dc.GameFiTournamentWinPoints
		changed = true
	}

	if dc.GameFiTournamentPartPoints > 0 && ConfigDTLGameFiTournamentPartPoints != dc.GameFiTournamentPartPoints {
		ConfigDTLGameFiTournamentPartPoints = dc.GameFiTournamentPartPoints
		changed = true
	}

	if dc.FarmMinStakeBlocks > 0 && ConfigDTLFarmMinStakeBlocks != dc.FarmMinStakeBlocks {
		ConfigDTLFarmMinStakeBlocks = dc.FarmMinStakeBlocks
		changed = true
	}

	if dc.FarmLPPointsPerBlock > 0 && ConfigDTLFarmLPPointsPerBlock != dc.FarmLPPointsPerBlock {
		ConfigDTLFarmLPPointsPerBlock = dc.FarmLPPointsPerBlock
		changed = true
	}

	if dc.FarmMaxMultiplierBPS > 0 {
		maxMultiplier := dc.FarmMaxMultiplierBPS
		if maxMultiplier < DTLMaxTaxBPS {
			maxMultiplier = DTLMaxTaxBPS
		}
		if ConfigDTLFarmMaxMultiplierBPS != maxMultiplier {
			ConfigDTLFarmMaxMultiplierBPS = maxMultiplier
			changed = true
		}
	}

	if dc.GameFiMaxRewardPerSeason > 0 && ConfigDTLGameFiMaxRewardPerSeason != dc.GameFiMaxRewardPerSeason {
		ConfigDTLGameFiMaxRewardPerSeason = dc.GameFiMaxRewardPerSeason
		changed = true
	}

	return changed
}

func sanitizeFeeBPS(v int) int {

	if v < 1 {

		return 1

	}

	if v > 10000 {

		return 10000

	}

	return v

}

func sanitizeFeeAmount(v int) int {

	if v < 1 {

		return 1

	}

	return v

}

