func (s *Server) handleSnapshotCreate(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return

	}

	if !authorizedSubmit(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return

	}

	if s == nil || s.Node == nil {

		http.Error(w, "node unavailable", http.StatusServiceUnavailable)
		return

	}

	forceValue := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("force")))
	force := forceValue == "1" || forceValue == "true" || forceValue == "yes"

	snapshot, meta, source, err := s.Node.createCommittedTipSnapshot("rpc_create", force)
	if err != nil || snapshot == nil {
		http.Error(w, "snapshot create failed", http.StatusServiceUnavailable)
		return
	}

	status := "existing"
	created := false
	if force || source != "snapshot_committed" {
		status = "created"
		created = true
	}
	resp := snapshotMetaResponse(snapshot, meta, source)
	resp["created"] = created
	resp["status"] = status
	resp["force"] = force

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(resp)
}

