func (s *Server) handleWalletStatus(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodGet {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	addr := strings.TrimSpace(r.URL.Query().Get("address"))

	if addr == "" {

		if wallet, err := LoadSecureWallet(); err == nil {

			addr = wallet.Address

		}

	}
	addr = canonicalAddressKey(addr)

	if addr == "" {

		http.Error(w, "address required", http.StatusBadRequest)

		return

	}

	validatorID := ""

	staked := 0

	lockedUntil := uint64(0)

	if s.Node != nil {

		for key, rec := range s.Node.Ledger.Stakes {

			if rec.Amount <= 0 {

				continue

			}

			parts := strings.SplitN(key, "|", 2)

			if len(parts) != 2 {

				continue

			}

			if !addressesEqual(parts[0], addr) {

				continue

			}

			vid := strings.TrimSpace(parts[1])

			if vid == "" {

				continue

			}

			if rec.Amount > staked {

				validatorID = vid

				staked = rec.Amount

				lockedUntil = rec.LockedUntil

			}

		}

	}

	eligible := !ValidatorRequireStake

	eligibleReason := ""

	if s.Node != nil && validatorID != "" {

		staked, lockedUntil, eligible, eligibleReason = validatorStakeStatus(s.Node, addr, validatorID)

	}

	height := uint64(0)

	if s.Node != nil && s.Node.Blockchain != nil {

		height = s.Node.Blockchain.FinalizedHeight()

		if height == 0 {

			height = s.Node.Blockchain.Height()

		}

	}

	if height == 0 {

		s.Node.commitMu.Lock()

		height = s.Node.committedHeight

		s.Node.commitMu.Unlock()

	}

	status := "none"

	pendingAddHeight := uint64(0)

	pendingRemoveHeight := uint64(0)

	if validatorID != "" && s.Node != nil {

		status = "inactive"
		isActive := false
		checkHeights := []uint64{s.Node.currentEpoch()}
		if height > 0 {
			checkHeights = append(checkHeights, height)
			checkHeights = append(checkHeights, height+1)
		}
		seenCheck := make(map[uint64]struct{}, len(checkHeights))
		for _, h := range checkHeights {
			if h == 0 {
				continue
			}
			if _, ok := seenCheck[h]; ok {
				continue
			}
			seenCheck[h] = struct{}{}
			if s.Node.isValidatorInSetForHeight(validatorID, h) {
				isActive = true
				break
			}
		}
		lookupPendingActivation := func(set map[string]uint64, id string) (uint64, bool) {
			if set == nil {
				return 0, false
			}
			if act, ok := set[id]; ok {
				return act, true
			}
			for key, act := range set {
				if strings.EqualFold(strings.TrimSpace(key), strings.TrimSpace(id)) {
					return act, true
				}
			}
			return 0, false
		}

		s.Node.validatorSetMu.RLock()

		if act, ok := lookupPendingActivation(s.Node.pendingValidators, validatorID); ok {

			pendingAddHeight = act

		}

		if act, ok := lookupPendingActivation(s.Node.pendingValidatorRemovals, validatorID); ok {

			pendingRemoveHeight = act

		}

		s.Node.validatorSetMu.RUnlock()

		if isActive {
			status = "active"
		}
		if pendingAddHeight > 0 && !isActive {
			status = "pending_add"
		}
		if pendingRemoveHeight > 0 {
			if isActive {
				status = "active_pending_remove"
			} else {
				status = "pending_remove"
			}
		}

	}

	rewardWallet := ""
	if s.Node != nil && validatorID != "" {
		if addr, ok := validatorRewardWallet(&s.Node.Ledger, validatorID); ok {
			rewardWallet = addr
		}
	}

	validatorConsensusPubKey := ""
	validatorConsensusPubKeyAnchored := false
	validatorConsensusPubKeySource := "none"
	if s.Node != nil && validatorID != "" {
		snapshotHeight := height + 1
		if snapshotHeight == 0 {
			snapshotHeight = 1
		}
		registrySnapshot := s.Node.validatorRegistrySnapshotForHeight(snapshotHeight)
		validatorConsensusPubKey = validatorConsensusPubKeyHexFromSnapshot(registrySnapshot, validatorID)
		validatorConsensusPubKeyAnchored, validatorConsensusPubKeySource = s.Node.validatorConsensusPubKeyStatus(validatorID, registrySnapshot)
	}

	localValidatorID := ""
	localValidatorKeyLoaded := false
	localValidatorConsensusPubKey := ""
	localValidatorConsensusPubKeyAnchored := false
	localValidatorConsensusPubKeySource := "none"
	if s.Node != nil {
		localValidatorID = normalizeValidatorID(s.Node.ID)
		keyHealth := CollectValidatorKeyHealth(localValidatorID, s.Node.DataDir, s.Node.ValidatorKey)
		localValidatorKeyLoaded = keyHealth.Loaded
		if localValidatorKeyLoaded && len(s.Node.ValidatorKey.PublicKey) == ed25519.PublicKeySize {
			localValidatorConsensusPubKey = strings.ToLower(hex.EncodeToString(s.Node.ValidatorKey.PublicKey))
		}
		if localValidatorID != "" {
			snapshotHeight := height + 1
			if snapshotHeight == 0 {
				snapshotHeight = 1
			}
			registrySnapshot := s.Node.validatorRegistrySnapshotForHeight(snapshotHeight)
			localValidatorConsensusPubKeyAnchored, localValidatorConsensusPubKeySource = s.Node.validatorConsensusPubKeyStatus(localValidatorID, registrySnapshot)
		}
	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"wallet": displayAddress(addr),

		"validator_id": validatorID,

		"stake": staked,

		"locked_until_epoch": lockedUntil,

		"eligible": eligible,

		"eligible_reason": eligibleReason,

		"reward_wallet": displayAddress(rewardWallet),

		"status": status,

		"pending_add_height": pendingAddHeight,

		"pending_remove_height": pendingRemoveHeight,

		"validator_consensus_pubkey":          validatorConsensusPubKey,
		"validator_consensus_pubkey_anchored": validatorConsensusPubKeyAnchored,
		"validator_consensus_pubkey_source":   validatorConsensusPubKeySource,

		"local_validator_id":                        localValidatorID,
		"local_validator_key_loaded":                localValidatorKeyLoaded,
		"local_validator_consensus_pubkey":          localValidatorConsensusPubKey,
		"local_validator_consensus_pubkey_anchored": localValidatorConsensusPubKeyAnchored,
		"local_validator_consensus_pubkey_source":   localValidatorConsensusPubKeySource,

		"height": height,
	})

}

func (s *Server) handleWalletCreate(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	var req struct {
		Password string `json:"password"`

		Force bool `json:"force"`

		Account uint32 `json:"account"`
		Change  uint32 `json:"change"`
		Index   uint32 `json:"index"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	if strings.TrimSpace(req.Password) == "" {

		http.Error(w, "password required", http.StatusBadRequest)

		return

	}

	if !req.Force {

		if _, err := os.Stat(secureWalletPath()); err == nil {

			http.Error(w, "wallet already exists", http.StatusConflict)

			return

		}

	}

	wallet, mnemonic, err := CreateSecureWalletWithPath(
		req.Password,
		req.Account,
		req.Change,
		req.Index,
	)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"address": wallet.Address,

		"publicKey": wallet.PublicKey,

		"mnemonic": mnemonic,
		"hd":       wallet.HD,
	})

}

func (s *Server) handleWalletRecover(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	var req struct {
		Mnemonic string `json:"mnemonic"`

		Password string `json:"password"`

		Account uint32 `json:"account"`
		Change  uint32 `json:"change"`
		Index   uint32 `json:"index"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	if strings.TrimSpace(req.Mnemonic) == "" || strings.TrimSpace(req.Password) == "" {

		http.Error(w, "mnemonic and password required", http.StatusBadRequest)

		return

	}

	wallet, err := RecoverWalletWithPath(
		req.Mnemonic,
		req.Password,
		req.Account,
		req.Change,
		req.Index,
	)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	if err := SaveSecureWallet(wallet); err != nil {

		http.Error(w, "failed to save wallet", http.StatusInternalServerError)

		return

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"address": wallet.Address,

		"publicKey": wallet.PublicKey,

		"hd": wallet.HD,
	})

}

func (s *Server) handleStake(

	w http.ResponseWriter,

	r *http.Request,

) {

	if r.Method != http.MethodPost {

		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)

		return

	}

	if !authorized(r) {

		http.Error(w, "unauthorized", http.StatusUnauthorized)

		return

	}

	var req struct {
		ValidatorID string `json:"validator_id"`

		ValidatorPubKey string `json:"validator_pubkey"`

		Amount int `json:"amount"`

		Coin string `json:"coin"`

		Password string `json:"password"`

		LockEpochs uint64 `json:"lock_epochs"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {

		http.Error(w, "invalid request body", http.StatusBadRequest)

		return

	}

	if strings.TrimSpace(req.ValidatorID) == "" || req.Amount <= 0 {

		http.Error(w, "validator_id and amount required", http.StatusBadRequest)

		return

	}

	wallet, err := LoadSecureWallet()

	if err != nil {

		http.Error(w, "secure wallet not found", http.StatusNotFound)

		return

	}

	if other, ok := walletBoundValidator(&s.Node.Ledger, wallet.Address, req.ValidatorID); ok {

		http.Error(w, fmt.Sprintf("wallet already bound to validator %s", other), http.StatusBadRequest)

		return

	}

	coin := normalizeCoin(req.Coin)
	if !AllowedCoins[coin] {

		http.Error(w, "unsupported coin", http.StatusBadRequest)

		return

	}

	requiredFee := ComputeTxFee(req.Amount)
	totalCost := req.Amount + requiredFee
	if getBalance(s.Node.Ledger, coin, wallet.Address) < totalCost {

		http.Error(w, "insufficient balance", http.StatusBadRequest)

		return

	}

	currentNonce := getNonce(s.Node.Ledger, wallet.Address)

	tx, err := BuildSignedStakeTxSecure(

		wallet,

		req.Password,

		req.ValidatorID,

		req.ValidatorPubKey,

		req.Amount,

		currentNonce,

		coin,

		req.LockEpochs,
	)

	if err != nil {

		http.Error(w, err.Error(), http.StatusBadRequest)

		return

	}

	if !s.Node.ReceiveTransaction(tx) {

		http.Error(w, "transaction rejected", http.StatusBadRequest)

		return

	}

	_ = json.NewEncoder(w).Encode(map[string]any{

		"status": "accepted",

		"tx_id": tx.ID,

		"nonce": tx.Nonce,

		"validator_id": strings.TrimSpace(req.ValidatorID),

		"amount": tx.Amount,

		"coin": tx.Coin,
	})

}

