func (s *Server) handleV1Balance(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeV1Error(w, http.StatusMethodNotAllowed, "", "method not allowed")
		return
	}
	if !authorized(r) {
		writeV1Error(w, http.StatusUnauthorized, "", "unauthorized")
		return
	}
	if s == nil || s.Node == nil {
		writeV1Error(w, http.StatusServiceUnavailable, "", "node unavailable")
		return
	}

	addr := strings.TrimSpace(r.URL.Query().Get("address"))
	if addr == "" {
		writeV1Error(w, http.StatusBadRequest, "", "address required")
		return
	}
	addr = canonicalAddressKey(addr)

	coin := normalizeCoin(strings.TrimSpace(r.URL.Query().Get("coin")))
	if coin == "" {
		coin = CoinSymbol
	}
	if !AllowedCoins[coin] {
		writeV1Error(w, http.StatusBadRequest, "", "unsupported coin")
		return
	}

	stateTag := strings.TrimSpace(r.URL.Query().Get("state"))
	ledger, ledgerHeight, resolvedState, ok := s.resolveBalanceLedger(stateTag)
	if !ok {
		writeV1Error(w, http.StatusBadRequest, "", "invalid state (use latest|finalized|pending)")
		return
	}

	balance := getBalance(ledger, coin, addr)
	writeV1Data(w, http.StatusOK, map[string]any{
		"address":  displayAddress(addr),
		"coin":     coin,
		"balance":  balance,
		"decimals": CoinDecimals,
		"state":    resolvedState,
		"height":   ledgerHeight,
	})
}

func (s *Server) handleV1Nonce(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeV1Error(w, http.StatusMethodNotAllowed, "", "method not allowed")
		return
	}
	if !authorized(r) {
		writeV1Error(w, http.StatusUnauthorized, "", "unauthorized")
		return
	}
	if s == nil || s.Node == nil {
		writeV1Error(w, http.StatusServiceUnavailable, "", "node unavailable")
		return
	}

	addr := strings.TrimSpace(r.URL.Query().Get("address"))
	if addr == "" {
		writeV1Error(w, http.StatusBadRequest, "", "address required")
		return
	}
	addr = canonicalAddressKey(addr)

	ledger := s.Node.currentExecutionLedgerClone()
	nextNonce := s.Node.Mempool.NextNonce(addr, ledger)
	writeV1Data(w, http.StatusOK, map[string]any{
		"address":       displayAddress(addr),
		"nonce":         getNonce(ledger, addr),
		"pending_nonce": nextNonce,
	})
}

func (s *Server) handleV1Blocks(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeV1Error(w, http.StatusMethodNotAllowed, "", "method not allowed")
		return
	}
	if !authorized(r) {
		writeV1Error(w, http.StatusUnauthorized, "", "unauthorized")
		return
	}
	if s == nil || s.Node == nil || s.Node.Blockchain == nil {
		writeV1Error(w, http.StatusServiceUnavailable, "", "node unavailable")
		return
	}

	limit := 25
	if lq := strings.TrimSpace(r.URL.Query().Get("limit")); lq != "" {
		if parsed, err := strconv.Atoi(lq); err == nil {
			limit = parsed
		}
	}
	if limit < 1 {
		limit = 1
	}
	if limit > 200 {
		limit = 200
	}

	var cursor uint64
	cursorSet := false
	if cq := strings.TrimSpace(r.URL.Query().Get("cursor")); cq != "" {
		if parsed, err := strconv.ParseUint(cq, 10, 64); err == nil {
			cursor = parsed
			cursorSet = true
		} else {
			writeV1Error(w, http.StatusBadRequest, "", "invalid cursor")
			return
		}
	} else if hq := strings.TrimSpace(r.URL.Query().Get("from_height")); hq != "" {
		if parsed, err := strconv.ParseUint(hq, 10, 64); err == nil {
			cursor = parsed
			cursorSet = true
		} else {
			writeV1Error(w, http.StatusBadRequest, "", "invalid from_height")
			return
		}
	}

	s.Node.Blockchain.mu.RLock()
	blocks := append([]Block{}, s.Node.Blockchain.Blocks...)
	s.Node.Blockchain.mu.RUnlock()

	latestHeight := uint64(0)
	if len(blocks) > 0 {
		latestHeight = blocks[len(blocks)-1].ID
	}
	if !cursorSet || cursor == 0 || cursor > latestHeight {
		cursor = latestHeight
	}

	items := make([]explorerBlockSummary, 0, limit)
	var lastIncluded uint64
	for i := len(blocks) - 1; i >= 0; i-- {
		b := blocks[i]
		if b.ID > cursor {
			continue
		}
		if len(items) >= limit {
			break
		}
		items = append(items, buildExplorerBlockSummary(b))
		lastIncluded = b.ID
	}

	hasMore := false
	if len(items) == limit && lastIncluded > 0 {
		for i := len(blocks) - 1; i >= 0; i-- {
			if blocks[i].ID < lastIncluded {
				hasMore = true
				break
			}
		}
	}
	nextCursor := uint64(0)
	if hasMore && lastIncluded > 0 {
		nextCursor = lastIncluded - 1
	}

	writeV1Data(w, http.StatusOK, map[string]any{
		"latest_height":    latestHeight,
		"finalized_height": s.explorerAvailableFinalizedHeight(),
		"cursor":           cursor,
		"limit":            limit,
		"has_more":         hasMore,
		"next_cursor":      nextCursor,
		"blocks":           items,
	})
}

