func (s *Server) handleV1Validators(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeV1Error(w, http.StatusMethodNotAllowed, "", "method not allowed")
		return
	}
	if !authorized(r) {
		writeV1Error(w, http.StatusUnauthorized, "", "unauthorized")
		return
	}
	if s == nil || s.Node == nil || s.Node.Blockchain == nil {
		writeV1Error(w, http.StatusServiceUnavailable, "", "node unavailable")
		return
	}

	height := s.defaultValidatorViewHeight()
	if hq := strings.TrimSpace(r.URL.Query().Get("height")); hq != "" {
		if parsed, err := strconv.Atoi(hq); err == nil && parsed > 0 {
			height = parsed
		} else {
			writeV1Error(w, http.StatusBadRequest, "", "invalid height")
			return
		}
	}

	validators := canonicalValidatorIDs(s.Node.GetConsensusValidators(height))
	onlineValidators, offlineValidators := s.Node.splitValidatorsByFinalizedActivity(validators, uint64(height))
	localOnlineValidators, localOfflineValidators := s.Node.splitValidatorsByLiveness(validators)
	pendingHeight, pendingAdds, pendingRemoves := s.collectPendingValidators()

	writeV1Data(w, http.StatusOK, map[string]any{
		"height":                    height,
		"validators":                validators,
		"online_validators":         onlineValidators,
		"inactive_validators":       offlineValidators,
		"offline_validators":        offlineValidators,
		"local_online_validators":   localOnlineValidators,
		"local_inactive_validators": localOfflineValidators,
		"pending_height":            pendingHeight,
		"pending_add":               pendingAdds,
		"pending_remove":            pendingRemoves,
	})
}

